fn mysql_parse_aggregate_projection_expr(
    aggregate_expr: &str,
) -> Option<(Option<String>, String, MySqlCompatAggregateOp)> {
    let aggregate_lower = aggregate_expr
        .chars()
        .filter(|ch| !ch.is_ascii_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    if matches!(aggregate_lower.as_str(), "count(*)" | "count(1)") {
        let alias = if aggregate_lower == "count(1)" {
            "COUNT(1)".to_string()
        } else {
            "COUNT(*)".to_string()
        };
        return Some((None, alias, MySqlCompatAggregateOp::CountRows));
    }
    if aggregate_lower.starts_with("count(") && aggregate_lower.ends_with(')') {
        let arg = aggregate_expr[6..aggregate_expr.len() - 1].trim();
        if arg.len() > 9 && arg[..9].eq_ignore_ascii_case("distinct ") {
            let col_arg = arg[9..].trim();
            let (col, table) = parse_sql_column_ref(col_arg)?;
            let select_expr = table
                .map(|table| format!("{table}.{col}"))
                .unwrap_or(col.clone());
            return Some((
                Some(select_expr.clone()),
                format!("COUNT(DISTINCT {select_expr})"),
                MySqlCompatAggregateOp::CountDistinct,
            ));
        }
        let (col, table) = parse_sql_column_ref(arg)?;
        let select_expr = table
            .map(|table| format!("{table}.{col}"))
            .unwrap_or(col.clone());
        return Some((
            Some(select_expr.clone()),
            format!("COUNT({select_expr})"),
            MySqlCompatAggregateOp::CountNonNull,
        ));
    }
    if aggregate_lower.starts_with("sum(") && aggregate_lower.ends_with(')') {
        return mysql_parse_column_aggregate_projection(
            aggregate_expr,
            "sum",
            MySqlCompatAggregateOp::Sum,
        );
    }
    if aggregate_lower.starts_with("min(") && aggregate_lower.ends_with(')') {
        return mysql_parse_column_aggregate_projection(
            aggregate_expr,
            "min",
            MySqlCompatAggregateOp::Min,
        );
    }
    if aggregate_lower.starts_with("max(") && aggregate_lower.ends_with(')') {
        return mysql_parse_column_aggregate_projection(
            aggregate_expr,
            "max",
            MySqlCompatAggregateOp::Max,
        );
    }
    if aggregate_lower.starts_with("avg(") && aggregate_lower.ends_with(')') {
        return mysql_parse_column_aggregate_projection(
            aggregate_expr,
            "avg",
            MySqlCompatAggregateOp::Avg,
        );
    }
    if aggregate_lower.starts_with("group_concat(") && aggregate_lower.ends_with(')') {
        return mysql_parse_group_concat_projection(aggregate_expr);
    }
    if aggregate_lower.starts_with("bit_and(") && aggregate_lower.ends_with(')') {
        return mysql_parse_column_aggregate_projection(
            aggregate_expr,
            "bit_and",
            MySqlCompatAggregateOp::BitAnd,
        );
    }
    if aggregate_lower.starts_with("bit_or(") && aggregate_lower.ends_with(')') {
        return mysql_parse_column_aggregate_projection(
            aggregate_expr,
            "bit_or",
            MySqlCompatAggregateOp::BitOr,
        );
    }
    if aggregate_lower.starts_with("bit_xor(") && aggregate_lower.ends_with(')') {
        return mysql_parse_column_aggregate_projection(
            aggregate_expr,
            "bit_xor",
            MySqlCompatAggregateOp::BitXor,
        );
    }
    // PG string_agg(col, separator)
    if aggregate_lower.starts_with("string_agg(") && aggregate_lower.ends_with(')') {
        let inner = aggregate_expr["string_agg(".len()..aggregate_expr.len() - 1].trim();
        let parts = split_csv_top_level(inner);
        if !parts.is_empty() {
            let col_part = parts[0].trim();
            let (col, table) = parse_sql_column_ref(col_part)?;
            let select_expr = table.map(|t| format!("{t}.{col}")).unwrap_or(col.clone());
            return Some((
                Some(select_expr.clone()),
                format!("STRING_AGG({select_expr})"),
                MySqlCompatAggregateOp::StringAgg,
            ));
        }
    }
    // PG array_agg(col)
    if aggregate_lower.starts_with("array_agg(") && aggregate_lower.ends_with(')') {
        return mysql_parse_column_aggregate_projection(
            aggregate_expr,
            "array_agg",
            MySqlCompatAggregateOp::ArrayAgg,
        );
    }
    None
}

fn mysql_parse_column_aggregate_projection(
    aggregate_expr: &str,
    function_name: &str,
    op: MySqlCompatAggregateOp,
) -> Option<(Option<String>, String, MySqlCompatAggregateOp)> {
    let arg_start = function_name.len() + 1;
    let arg = aggregate_expr[arg_start..aggregate_expr.len() - 1].trim();
    let (col, table) = parse_sql_column_ref(arg)?;
    let select_expr = table
        .map(|table| format!("{table}.{col}"))
        .unwrap_or(col.clone());
    Some((
        Some(select_expr.clone()),
        format!("{}({select_expr})", function_name.to_ascii_uppercase()),
        op,
    ))
}

fn mysql_parse_group_concat_projection(
    aggregate_expr: &str,
) -> Option<(Option<String>, String, MySqlCompatAggregateOp)> {
    let arg_start = "group_concat(".len();
    let mut arg = aggregate_expr[arg_start..aggregate_expr.len() - 1]
        .trim()
        .to_string();
    // Strip DISTINCT prefix
    let arg_lower = arg.to_ascii_lowercase();
    if arg_lower.starts_with("distinct ") {
        arg = arg["distinct ".len()..].trim().to_string();
    }
    // Strip ORDER BY clause
    if let Some(idx) = arg.to_ascii_lowercase().find(" order by ") {
        arg = arg[..idx].trim().to_string();
    }
    // Strip SEPARATOR clause
    if let Some(idx) = arg.to_ascii_lowercase().find(" separator ") {
        arg = arg[..idx].trim().to_string();
    }
    let (col, table) = parse_sql_column_ref(&arg)?;
    let select_expr = table
        .map(|table| format!("{table}.{col}"))
        .unwrap_or(col.clone());
    Some((
        Some(select_expr.clone()),
        format!("GROUP_CONCAT({select_expr})"),
        MySqlCompatAggregateOp::GroupConcat,
    ))
}

fn mysql_parse_numeric_aggregate_value(raw: &str) -> Result<(f64, bool), RpcError> {
    if let Ok(value) = raw.parse::<i64>() {
        return Ok((value as f64, true));
    }
    if let Ok(value) = raw.parse::<f64>() {
        return Ok((value, false));
    }
    Err(RpcError::new(
        "not_supported",
        format!(
            "numeric aggregate compatibility currently supports only numeric result values (got '{}')",
            raw.chars().take(80).collect::<String>()
        ),
    ))
}

fn mysql_render_numeric_aggregate_value(value: f64, prefer_integer: bool) -> String {
    if prefer_integer && value.fract() == 0.0 {
        return (value as i64).to_string();
    }
    let mut rendered = value.to_string();
    if rendered.contains('.') {
        while rendered.ends_with('0') {
            rendered.pop();
        }
        if rendered.ends_with('.') {
            rendered.pop();
        }
    }
    rendered
}

fn mysql_aggregate_value_ordering(left: &str, right: &str) -> std::cmp::Ordering {
    mysql_numeric_text_ordering(Some(left), Some(right))
        .unwrap_or_else(|| mysql_text_ordering(Some(left), Some(right)))
}

fn mysql_text_result_value_to_lit(value: Option<&str>) -> Lit {
    match value {
        None => Lit::Null,
        Some(raw) => {
            if let Ok(v) = raw.parse::<i64>() {
                Lit::I64 { v }
            } else if let Ok(v) = raw.parse::<f64>() {
                Lit::F64 { v }
            } else {
                Lit::Str { v: raw.to_string() }
            }
        }
    }
}

fn mysql_lit_to_string(lit: &Lit) -> Option<String> {
    match lit {
        Lit::Null => None,
        Lit::Str { v } => Some(v.clone()),
        Lit::I64 { v } => Some(v.to_string()),
        Lit::U64 { v } => Some(v.to_string()),
        Lit::F64 { v } => Some(v.to_string()),
        Lit::Bool { v } => Some(if *v { "1".to_string() } else { "0".to_string() }),
        Lit::Date { iso } => Some(iso.clone()),
        Lit::Time { iso } => Some(iso.clone()),
        Lit::Datetime { iso } => Some(iso.clone()),
        Lit::Dec { v } => Some(v.clone()),
        Lit::Uuid { v } => Some(v.clone()),
        Lit::Bytes { .. } | Lit::Json { .. } | Lit::Embedding { .. } => None,
    }
}

fn mysql_eval_row_expr_value(expr: &Expr, row: &BTreeMap<String, Lit>) -> Result<Lit, RpcError> {
    match expr {
        Expr::Col { col, .. } => Ok(row_get_lit(row, col).unwrap_or(Lit::Null)),
        Expr::Lit { lit } => Ok(lit.clone()),
        _ => Err(RpcError::new(
            "not_supported",
            "aggregate compatibility supports only column/literal comparisons",
        )),
    }
}

fn mysql_eval_row_predicate_expr(
    expr: &Expr,
    row: &BTreeMap<String, Lit>,
) -> Result<bool, RpcError> {
    match expr {
        Expr::Op {
            op,
            a,
            b,
            args: _,
            list,
            lo: _,
            hi: _,
        } => match op.as_str() {
            "and" => {
                let left = a.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                let right = b.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                Ok(mysql_eval_row_predicate_expr(left, row)?
                    && mysql_eval_row_predicate_expr(right, row)?)
            }
            "or" => {
                let left = a.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                let right = b.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                Ok(mysql_eval_row_predicate_expr(left, row)?
                    || mysql_eval_row_predicate_expr(right, row)?)
            }
            "not" => {
                let inner = a.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                Ok(!mysql_eval_row_predicate_expr(inner, row)?)
            }
            "is_null" => {
                let inner = a.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                Ok(matches!(mysql_eval_row_expr_value(inner, row)?, Lit::Null))
            }
            "in" => {
                let left_expr = a.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                let left = mysql_eval_row_expr_value(left_expr, row)?;
                if matches!(left, Lit::Null) {
                    return Ok(false);
                }
                for candidate_expr in list.as_deref().unwrap_or_default() {
                    if lit_eq(&left, &mysql_eval_row_expr_value(candidate_expr, row)?) {
                        return Ok(true);
                    }
                }
                Ok(false)
            }
            "like" | "ilike" => {
                let left_expr = a.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                let right_expr = b.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                let left = mysql_lit_to_string(&mysql_eval_row_expr_value(left_expr, row)?);
                let right = mysql_lit_to_string(&mysql_eval_row_expr_value(right_expr, row)?);
                let Some(left) = left else {
                    return Ok(false);
                };
                let Some(pattern) = right else {
                    return Ok(false);
                };
                if op == "ilike" {
                    Ok(mysql_like_matches(
                        &left.to_ascii_lowercase(),
                        &pattern.to_ascii_lowercase(),
                    ))
                } else {
                    Ok(mysql_like_matches(&left, &pattern))
                }
            }
            "eq" | "ne" | "gt" | "ge" | "lt" | "le" => {
                let left_expr = a.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                let right_expr = b.as_deref().ok_or_else(|| {
                    RpcError::new("invalid_request", "malformed predicate expression")
                })?;
                let left = mysql_eval_row_expr_value(left_expr, row)?;
                let right = mysql_eval_row_expr_value(right_expr, row)?;
                let ord = lit_cmp(&left, &right);
                Ok(match op.as_str() {
                    "eq" => lit_eq(&left, &right),
                    "ne" => !lit_eq(&left, &right),
                    "gt" => ord
                        .map(|cmp| cmp == std::cmp::Ordering::Greater)
                        .unwrap_or(false),
                    "ge" => ord
                        .map(|cmp| {
                            cmp == std::cmp::Ordering::Greater || cmp == std::cmp::Ordering::Equal
                        })
                        .unwrap_or(false),
                    "lt" => ord
                        .map(|cmp| cmp == std::cmp::Ordering::Less)
                        .unwrap_or(false),
                    "le" => ord
                        .map(|cmp| {
                            cmp == std::cmp::Ordering::Less || cmp == std::cmp::Ordering::Equal
                        })
                        .unwrap_or(false),
                    _ => false,
                })
            }
            _ => Err(RpcError::new(
                "not_supported",
                format!("unsupported predicate operator '{}'", op),
            )),
        },
        Expr::Lit {
            lit: Lit::Bool { v },
        } => Ok(*v),
        _ => Err(RpcError::new(
            "not_supported",
            "aggregate compatibility supports only simple predicates",
        )),
    }
}

fn mysql_parse_projection_expr_alias(item: &str) -> (String, Option<String>) {
    let projection = item.trim();
    if let Some(idx) = find_keyword_top_level(projection, "as") {
        let expr = projection[..idx].trim();
        let alias = clean_sql_ident(projection[idx + 2..].trim());
        if !expr.is_empty() && !alias.is_empty() {
            return (expr.to_string(), Some(alias));
        }
    }
    (projection.to_string(), None)
}

fn mysql_collect_expr_columns(expr: &Expr, out: &mut Vec<String>) {
    match expr {
        Expr::Col { col, .. } => {
            if !out
                .iter()
                .any(|existing| existing.eq_ignore_ascii_case(col))
            {
                out.push(col.clone());
            }
        }
        Expr::Op {
            a,
            b,
            args,
            list,
            lo,
            hi,
            ..
        } => {
            if let Some(expr) = a.as_deref() {
                mysql_collect_expr_columns(expr, out);
            }
            if let Some(expr) = b.as_deref() {
                mysql_collect_expr_columns(expr, out);
            }
            if let Some(expr) = lo.as_deref() {
                mysql_collect_expr_columns(expr, out);
            }
            if let Some(expr) = hi.as_deref() {
                mysql_collect_expr_columns(expr, out);
            }
            for expr in args.iter().flatten() {
                mysql_collect_expr_columns(expr, out);
            }
            for expr in list.iter().flatten() {
                mysql_collect_expr_columns(expr, out);
            }
        }
        Expr::Func { args, .. } => {
            for expr in args {
                mysql_collect_expr_columns(expr, out);
            }
        }
        Expr::Exists { .. }
        | Expr::Lit { .. }
        | Expr::Param { .. }
        | Expr::Cast { .. }
        | Expr::Case { .. }
        | Expr::Subquery { .. } => {}
    }
}

fn mysql_parse_multi_aggregate_projection_item(
    raw: &str,
    source_columns: &mut Vec<String>,
) -> Option<MySqlCompatMultiAggregateItem> {
    let (expr_raw, alias_raw) = mysql_parse_projection_expr_alias(raw);
    let expr_trimmed = expr_raw.trim();
    let expr_lower = expr_trimmed
        .chars()
        .filter(|ch| !ch.is_ascii_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    let alias = alias_raw
        .filter(|alias| !alias.is_empty())
        .unwrap_or_else(|| expr_trimmed.to_string());

    if matches!(expr_lower.as_str(), "count(*)" | "count(1)") {
        return Some(MySqlCompatMultiAggregateItem::Rows { alias });
    }

    if !expr_lower.starts_with("count(") || !expr_lower.ends_with(')') {
        return None;
    }

    let inner = expr_trimmed[6..expr_trimmed.len() - 1].trim();
    let inner_lower = inner.to_ascii_lowercase();
    if inner_lower.starts_with("nullif(") && inner.ends_with(')') {
        let args_sql = &inner[7..inner.len() - 1];
        let args = split_csv_top_level(args_sql);
        if args.len() != 2 {
            return None;
        }
        let predicate = parse_where_expr(&args[0]).ok().flatten()?;
        let right = parse_sql_lit(&args[1]).ok()?;
        let matches_false = matches!(right, Lit::Bool { v: false })
            || matches!(right, Lit::I64 { v: 0 })
            || matches!(right, Lit::U64 { v: 0 });
        if !matches_false {
            return None;
        }
        mysql_collect_expr_columns(&predicate, source_columns);
        return Some(MySqlCompatMultiAggregateItem::Predicate { alias, predicate });
    }

    if let Some((col, table)) = parse_sql_column_ref(inner) {
        let select_expr = table
            .map(|table| format!("{table}.{col}"))
            .unwrap_or(col.clone());
        if !source_columns
            .iter()
            .any(|existing| existing.eq_ignore_ascii_case(&select_expr))
        {
            source_columns.push(select_expr);
        }
        return Some(MySqlCompatMultiAggregateItem::NonNull { alias, column: col });
    }

    None
}

fn mysql_parse_multi_aggregate_query(sql: &str) -> Option<MySqlCompatMultiAggregateQuery> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    if !trimmed.is_ascii() || trimmed.len() < 6 || !trimmed[..6].eq_ignore_ascii_case("select") {
        return None;
    }
    let rest = trimmed[6..].trim();
    let from_idx = find_keyword_top_level(rest, "from")?;
    let mut projection = rest[..from_idx].trim();
    loop {
        if projection.len() >= 19 && projection[..19].eq_ignore_ascii_case("sql_calc_found_rows") {
            let after = projection[19..].trim_start();
            if after.len() != projection.len() {
                projection = after;
                continue;
            }
        }
        if projection.len() >= 8 && projection[..8].eq_ignore_ascii_case("distinct") {
            let after = projection[8..].trim_start();
            if after.len() != projection.len() {
                projection = after;
                continue;
            }
        }
        break;
    }

    let mut from_tail = rest[from_idx..].trim().to_string();
    if find_keyword_top_level(&from_tail, "group by").is_some()
        || find_keyword_top_level(&from_tail, "having").is_some()
    {
        return None;
    }
    let truncate_at = ["order by", "limit", "offset"]
        .iter()
        .filter_map(|keyword| find_keyword_top_level(&from_tail, keyword))
        .min()
        .unwrap_or(from_tail.len());
    from_tail.truncate(truncate_at);
    let from_tail = from_tail.trim().to_string();
    if from_tail.is_empty() {
        return None;
    }

    let projection_items = split_csv_top_level(projection);
    if projection_items.len() < 2 {
        return None;
    }

    let mut source_columns = Vec::new();
    let mut items = Vec::new();
    for item in projection_items {
        items.push(mysql_parse_multi_aggregate_projection_item(
            &item,
            &mut source_columns,
        )?);
    }

    let source_projection = if source_columns.is_empty() {
        "1".to_string()
    } else {
        source_columns.join(", ")
    };
    Some(MySqlCompatMultiAggregateQuery {
        source_sql: format!("SELECT {source_projection} {from_tail}"),
        items,
    })
}

fn mysql_parse_top_level_add_terms(expr: &str) -> Option<Vec<String>> {
    let bytes = expr.as_bytes();
    let mut parts = Vec::new();
    let mut start = 0usize;
    let mut depth = 0u32;
    let mut quote = 0u8;
    let mut idx = 0usize;

    while idx < bytes.len() {
        let byte = bytes[idx];
        if quote != 0 {
            if byte == quote {
                if quote == b'\'' && idx + 1 < bytes.len() && bytes[idx + 1] == b'\'' {
                    idx += 2;
                    continue;
                }
                quote = 0;
            }
            idx += 1;
            continue;
        }
        match byte {
            b'\'' | b'"' | b'`' => {
                quote = byte;
            }
            b'(' => {
                depth = depth.saturating_add(1);
            }
            b')' => {
                depth = depth.saturating_sub(1);
            }
            b'+' if depth == 0 => {
                let part = expr[start..idx].trim();
                if part.is_empty() {
                    return None;
                }
                parts.push(part.to_string());
                start = idx + 1;
            }
            _ => {}
        }
        idx += 1;
    }

    let tail = expr[start..].trim();
    if tail.is_empty() {
        return None;
    }
    parts.push(tail.to_string());
    Some(parts)
}

fn mysql_parse_info_schema_table_storage_query(
    sql: &str,
    _default_db: Option<&str>,
) -> Option<MySqlCompatInfoSchemaTableStorageQuery> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    if !trimmed.is_ascii() || trimmed.len() < 6 || !trimmed[..6].eq_ignore_ascii_case("select") {
        return None;
    }
    let rest = trimmed[6..].trim();
    let from_idx = find_keyword_top_level(rest, "from")?;
    let projection_sql = rest[..from_idx].trim();
    let from_tail = rest[from_idx..].trim();
    let group_idx = find_keyword_top_level(from_tail, "group by")?;
    let source_from_tail = from_tail[..group_idx].trim().to_string();
    if source_from_tail.is_empty() {
        return None;
    }

    let source_from_lower = source_from_tail.to_ascii_lowercase();
    if !source_from_lower.starts_with("from ") {
        return None;
    }
    let source_table_end = ["where", "order by", "limit", "offset"]
        .iter()
        .filter_map(|keyword| find_keyword_top_level(&source_from_tail[5..], keyword))
        .min()
        .unwrap_or(source_from_tail.len().saturating_sub(5));
    let source_table_sql = source_from_tail[5..5 + source_table_end].trim();
    let source_table = parse_from_table_ref(source_table_sql, None).ok()?;
    let TableRef::Base(source_table) = source_table else {
        return None;
    };
    if !source_table.db.eq_ignore_ascii_case("information_schema")
        || !source_table.table.eq_ignore_ascii_case("tables")
    {
        return None;
    }

    let group_tail = from_tail[group_idx + "group by".len()..].trim();
    let group_expr_end = ["having", "order by", "limit", "offset"]
        .iter()
        .filter_map(|keyword| find_keyword_top_level(group_tail, keyword))
        .min()
        .unwrap_or(group_tail.len());
    let group_expr = group_tail[..group_expr_end].trim();
    if group_expr.is_empty() {
        return None;
    }
    if !group_tail[group_expr_end..].trim().is_empty() {
        return None;
    }

    let projection_items = split_csv_top_level(projection_sql);
    if projection_items.len() != 3 {
        return None;
    }

    let (table_expr, table_alias_raw) = mysql_parse_projection_expr_alias(&projection_items[0]);
    let (table_col, _) = parse_sql_column_ref(&table_expr)?;
    if !table_col.eq_ignore_ascii_case("TABLE_NAME") {
        return None;
    }
    let table_alias = table_alias_raw
        .filter(|alias| !alias.is_empty())
        .unwrap_or_else(|| "TABLE_NAME".to_string());

    let (rows_expr, rows_alias_raw) = mysql_parse_projection_expr_alias(&projection_items[1]);
    let (rows_col, _) = parse_sql_column_ref(&rows_expr)?;
    if !rows_col.eq_ignore_ascii_case("TABLE_ROWS") {
        return None;
    }
    let rows_alias = rows_alias_raw
        .filter(|alias| !alias.is_empty())
        .unwrap_or_else(|| "TABLE_ROWS".to_string());

    let (bytes_expr, bytes_alias_raw) = mysql_parse_projection_expr_alias(&projection_items[2]);
    let bytes_trimmed = bytes_expr.trim();
    let bytes_lower = bytes_trimmed
        .chars()
        .filter(|ch| !ch.is_ascii_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    if !bytes_lower.starts_with("sum(") || !bytes_lower.ends_with(')') {
        return None;
    }
    let bytes_inner = bytes_trimmed[4..bytes_trimmed.len() - 1].trim();
    let terms = mysql_parse_top_level_add_terms(bytes_inner)?;
    if terms.len() != 2 {
        return None;
    }
    let mut saw_data_length = false;
    let mut saw_index_length = false;
    for term in terms {
        let (col, _) = parse_sql_column_ref(&term)?;
        if col.eq_ignore_ascii_case("DATA_LENGTH") {
            saw_data_length = true;
        } else if col.eq_ignore_ascii_case("INDEX_LENGTH") {
            saw_index_length = true;
        } else {
            return None;
        }
    }
    if !saw_data_length || !saw_index_length {
        return None;
    }
    let bytes_alias = bytes_alias_raw
        .filter(|alias| !alias.is_empty())
        .unwrap_or_else(|| bytes_trimmed.to_string());

    if let Ok(position) = group_expr.parse::<usize>() {
        if position != 1 {
            return None;
        }
    } else {
        let (group_col, _) = parse_sql_column_ref(group_expr)?;
        if !group_col.eq_ignore_ascii_case("TABLE_NAME")
            && !group_col.eq_ignore_ascii_case(&table_alias)
        {
            return None;
        }
    }

    Some(MySqlCompatInfoSchemaTableStorageQuery {
        table_alias,
        rows_alias,
        bytes_alias,
        source_sql: format!(
            "SELECT TABLE_NAME, TABLE_ROWS, DATA_LENGTH, INDEX_LENGTH {source_from_tail}"
        ),
    })
}

fn mysql_grouped_order_matches_group_column(
    order_col: &str,
    order_table: Option<&str>,
    group_col: &str,
    group_table: Option<&str>,
    group_alias: &str,
) -> bool {
    if order_table.is_none() && order_col.eq_ignore_ascii_case(group_alias) {
        return true;
    }
    if !order_col.eq_ignore_ascii_case(group_col) {
        return false;
    }
    match (order_table, group_table) {
        (Some(order_table), Some(group_table)) => order_table.eq_ignore_ascii_case(group_table),
        (Some(_), None) => false,
        _ => true,
    }
}

fn mysql_grouped_aggregate_having_target_for_raw(
    raw: &str,
    group_expr_raw: &str,
    group_col: &str,
    group_table: Option<&str>,
    group_alias: &str,
    aggregate_expr_raw: &str,
    aggregate_alias: &str,
) -> Option<MySqlCompatGroupedAggregateHavingTarget> {
    let trimmed = trim_wrapping_parentheses(raw.trim());
    if trimmed.eq_ignore_ascii_case(group_alias) || trimmed.eq_ignore_ascii_case(group_expr_raw) {
        return Some(MySqlCompatGroupedAggregateHavingTarget::Group);
    }
    if trimmed.eq_ignore_ascii_case(aggregate_alias)
        || trimmed.eq_ignore_ascii_case(aggregate_expr_raw)
    {
        return Some(MySqlCompatGroupedAggregateHavingTarget::Aggregate);
    }
    let (col, table) = parse_sql_column_ref(trimmed)?;
    if table.is_none() && col.eq_ignore_ascii_case(group_alias) {
        return Some(MySqlCompatGroupedAggregateHavingTarget::Group);
    }
    if sql_column_refs_match(&col, table.as_deref(), group_col, group_table)
        || (table.is_none() && col.eq_ignore_ascii_case(group_col))
    {
        return Some(MySqlCompatGroupedAggregateHavingTarget::Group);
    }
    if table.is_none() && col.eq_ignore_ascii_case(aggregate_alias) {
        return Some(MySqlCompatGroupedAggregateHavingTarget::Aggregate);
    }
    None
}

fn mysql_parse_grouped_aggregate_having_clauses(
    having_sql: &str,
    group_expr_raw: &str,
    group_col: &str,
    group_table: Option<&str>,
    group_alias: &str,
    aggregate_expr_raw: &str,
    aggregate_alias: &str,
) -> Option<Vec<MySqlCompatGroupedAggregateHavingClause>> {
    let mut clauses = Vec::new();
    for part in split_top_level_and(trim_wrapping_parentheses(having_sql)) {
        let clause = trim_wrapping_parentheses(part.trim());
        if clause.is_empty() {
            return None;
        }
        if let Some(idx) = find_keyword_top_level(clause, "is") {
            let left = clause[..idx].trim();
            let right = clause[idx + 2..].trim();
            let target = mysql_grouped_aggregate_having_target_for_raw(
                left,
                group_expr_raw,
                group_col,
                group_table,
                group_alias,
                aggregate_expr_raw,
                aggregate_alias,
            )?;
            let op = if right.eq_ignore_ascii_case("null") {
                MySqlCompatGroupedAggregateHavingOp::IsNull
            } else if right.eq_ignore_ascii_case("not null") {
                MySqlCompatGroupedAggregateHavingOp::IsNotNull
            } else {
                return None;
            };
            clauses.push(MySqlCompatGroupedAggregateHavingClause {
                target,
                op,
                value: None,
            });
            continue;
        }

        let bytes = clause.as_bytes();
        let mut i = 0usize;
        let mut depth = 0u32;
        let mut quote = 0u8;
        let mut parsed = None::<MySqlCompatGroupedAggregateHavingClause>;
        while i < bytes.len() {
            let b = bytes[i];
            if quote != 0 {
                if b == quote {
                    if quote == b'\'' && i + 1 < bytes.len() && bytes[i + 1] == b'\'' {
                        i += 2;
                        continue;
                    }
                    quote = 0;
                }
                i += 1;
                continue;
            }
            match b {
                b'\'' | b'"' | b'`' => {
                    quote = b;
                    i += 1;
                    continue;
                }
                b'(' => {
                    depth = depth.saturating_add(1);
                    i += 1;
                    continue;
                }
                b')' => {
                    depth = depth.saturating_sub(1);
                    i += 1;
                    continue;
                }
                _ => {}
            }
            if depth == 0 {
                for (token, op) in [
                    (">=", MySqlCompatGroupedAggregateHavingOp::Ge),
                    ("<=", MySqlCompatGroupedAggregateHavingOp::Le),
                    ("<>", MySqlCompatGroupedAggregateHavingOp::Ne),
                    ("!=", MySqlCompatGroupedAggregateHavingOp::Ne),
                    ("=", MySqlCompatGroupedAggregateHavingOp::Eq),
                    (">", MySqlCompatGroupedAggregateHavingOp::Gt),
                    ("<", MySqlCompatGroupedAggregateHavingOp::Lt),
                ] {
                    if clause[i..].starts_with(token) {
                        let left = clause[..i].trim();
                        let right = clause[i + token.len()..].trim();
                        if left.is_empty() || right.is_empty() {
                            return None;
                        }
                        let target = mysql_grouped_aggregate_having_target_for_raw(
                            left,
                            group_expr_raw,
                            group_col,
                            group_table,
                            group_alias,
                            aggregate_expr_raw,
                            aggregate_alias,
                        )?;
                        let lit = parse_sql_lit(right).ok()?;
                        parsed = Some(MySqlCompatGroupedAggregateHavingClause {
                            target,
                            op,
                            value: mysql_default_cell_value(&lit),
                        });
                        break;
                    }
                }
                if parsed.is_some() {
                    break;
                }
            }
            i += 1;
        }
        clauses.push(parsed?);
    }
    Some(clauses)
}

fn mysql_parse_grouped_aggregate_query(sql: &str) -> Option<MySqlCompatGroupedAggregateQuery> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    if !trimmed.is_ascii() || trimmed.len() < 6 || !trimmed[..6].eq_ignore_ascii_case("select") {
        return None;
    }
    let rest = trimmed[6..].trim();
    let from_idx = find_keyword_top_level(rest, "from")?;
    let projection = rest[..from_idx].trim();
    let from_tail = rest[from_idx..].trim();
    let group_idx = find_keyword_top_level(from_tail, "group by")?;
    let source_from_tail = from_tail[..group_idx].trim().to_string();
    if source_from_tail.is_empty() {
        return None;
    }

    let mut group_tail = from_tail[group_idx + "group by".len()..].trim();
    let group_key_end = ["having", "order by", "limit", "offset"]
        .iter()
        .filter_map(|keyword| find_keyword_top_level(group_tail, keyword))
        .min()
        .unwrap_or(group_tail.len());
    let group_by_expr = group_tail[..group_key_end].trim().to_string();
    if group_by_expr.is_empty() {
        return None;
    }
    group_tail = group_tail[group_key_end..].trim();

    let mut having_sql = None::<String>;
    let mut order_sql = None::<String>;
    let mut limit_sql = None::<String>;
    let mut offset_sql = None::<String>;
    while !group_tail.is_empty() {
        if group_tail.to_ascii_lowercase().starts_with("having ") {
            let tail = group_tail[6..].trim_start();
            let next = ["order by", "limit", "offset"]
                .iter()
                .filter_map(|keyword| find_keyword_top_level(tail, keyword))
                .min()
                .unwrap_or(tail.len());
            having_sql = Some(tail[..next].trim().to_string());
            group_tail = tail[next..].trim();
            continue;
        }
        if group_tail.to_ascii_lowercase().starts_with("order by ") {
            let tail = group_tail[8..].trim_start();
            let next = ["limit", "offset"]
                .iter()
                .filter_map(|keyword| find_keyword_top_level(tail, keyword))
                .min()
                .unwrap_or(tail.len());
            order_sql = Some(tail[..next].trim().to_string());
            group_tail = tail[next..].trim();
            continue;
        }
        if group_tail.to_ascii_lowercase().starts_with("limit ") {
            let tail = group_tail[5..].trim_start();
            let next = ["offset"]
                .iter()
                .filter_map(|keyword| find_keyword_top_level(tail, keyword))
                .min()
                .unwrap_or(tail.len());
            limit_sql = Some(tail[..next].trim().to_string());
            group_tail = tail[next..].trim();
            continue;
        }
        if group_tail.to_ascii_lowercase().starts_with("offset ") {
            let tail = group_tail[6..].trim_start();
            offset_sql = Some(tail.trim().to_string());
            group_tail = "";
            continue;
        }
        return None;
    }

    let projection_items = split_csv_top_level(projection);
    if projection_items.len() != 2 {
        return None;
    }
    let projection_items = projection_items
        .iter()
        .map(|item| mysql_parse_projection_expr_alias(item))
        .collect::<Vec<_>>();

    let mut aggregate_idx = None::<usize>;
    let mut aggregate = None::<(Option<String>, String, MySqlCompatAggregateOp)>;
    for (idx, (expr, _)) in projection_items.iter().enumerate() {
        if let Some(parsed) = mysql_parse_aggregate_projection_expr(expr) {
            if aggregate_idx.is_some() {
                return None;
            }
            aggregate_idx = Some(idx);
            aggregate = Some(parsed);
        }
    }
    let aggregate_idx = aggregate_idx?;
    let (aggregate_select_expr, aggregate_default_alias, aggregate_op) = aggregate?;
    let group_idx = if aggregate_idx == 0 { 1 } else { 0 };
    let (group_expr_raw, group_alias_raw) = &projection_items[group_idx];
    let aggregate_expr_raw = projection_items[aggregate_idx].0.clone();
    let (group_col, group_table) = parse_sql_column_ref(group_expr_raw)?;
    let group_select_expr = group_table
        .as_ref()
        .map(|table| format!("{table}.{group_col}"))
        .unwrap_or_else(|| group_col.clone());
    let group_alias = group_alias_raw
        .clone()
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| group_col.clone());
    if group_alias.is_empty() {
        return None;
    }
    let aggregate_alias = projection_items[aggregate_idx]
        .1
        .clone()
        .filter(|name| !name.is_empty())
        .unwrap_or(aggregate_default_alias);
    if aggregate_alias.is_empty() {
        return None;
    }

    let having = if let Some(having_sql) = having_sql.as_deref() {
        mysql_parse_grouped_aggregate_having_clauses(
            having_sql,
            group_expr_raw,
            &group_col,
            group_table.as_deref(),
            &group_alias,
            &aggregate_expr_raw,
            &aggregate_alias,
        )?
    } else {
        Vec::new()
    };

    if let Ok(position) = group_by_expr.parse::<usize>() {
        if position == 0 || position > projection_items.len() || position - 1 != group_idx {
            return None;
        }
    } else {
        let (group_by_col, group_by_table) = parse_sql_column_ref(&group_by_expr)?;
        let matches_alias =
            group_by_table.is_none() && group_by_col.eq_ignore_ascii_case(&group_alias);
        let matches_column = group_by_col.eq_ignore_ascii_case(&group_col)
            && match (&group_by_table, &group_table) {
                (Some(lhs), Some(rhs)) => lhs.eq_ignore_ascii_case(rhs),
                (Some(_), None) => false,
                _ => true,
            };
        if !matches_alias && !matches_column {
            return None;
        }
    }

    let mut order_by = Vec::new();
    if let Some(order_sql) = order_sql {
        let parsed = parse_order_by(&order_sql).ok()?;
        for item in parsed {
            let Expr::Col { col, table } = item.expr else {
                return None;
            };
            let target = if table.is_none() && col == "1" {
                Some(MySqlCompatGroupedAggregateOrderTarget::Group)
            } else if table.is_none() && col == "2" {
                Some(MySqlCompatGroupedAggregateOrderTarget::Aggregate)
            } else if mysql_grouped_order_matches_group_column(
                &col,
                table.as_deref(),
                &group_col,
                group_table.as_deref(),
                &group_alias,
            ) {
                Some(MySqlCompatGroupedAggregateOrderTarget::Group)
            } else if table.is_none() && col.eq_ignore_ascii_case(&aggregate_alias) {
                Some(MySqlCompatGroupedAggregateOrderTarget::Aggregate)
            } else {
                None
            };
            let target = target?;
            order_by.push(MySqlCompatGroupedAggregateOrder {
                target,
                desc: matches!(item.dir, Some(OrderDir::Desc)),
            });
        }
    }

    let mut source_projection = vec![group_select_expr];
    if let Some(aggregate_select_expr) = aggregate_select_expr.as_ref() {
        source_projection.push(aggregate_select_expr.clone());
    }
    let source_sql = format!(
        "SELECT {} {}",
        source_projection.join(", "),
        source_from_tail
    );

    Some(MySqlCompatGroupedAggregateQuery {
        group_alias,
        aggregate_alias,
        aggregate_op,
        source_sql,
        having,
        order_by,
        limit: parse_limit_clause(limit_sql.as_deref(), offset_sql.as_deref()).ok()?,
    })
}

fn mysql_text_ordering(left: Option<&str>, right: Option<&str>) -> std::cmp::Ordering {
    match (left, right) {
        (None, None) => std::cmp::Ordering::Equal,
        (None, Some(_)) => std::cmp::Ordering::Less,
        (Some(_), None) => std::cmp::Ordering::Greater,
        (Some(lhs), Some(rhs)) => lhs.cmp(rhs),
    }
}

fn mysql_numeric_text_ordering(
    left: Option<&str>,
    right: Option<&str>,
) -> Option<std::cmp::Ordering> {
    let parse = |raw: &str| -> Option<f64> {
        if let Ok(value) = raw.parse::<i64>() {
            return Some(value as f64);
        }
        raw.parse::<f64>().ok()
    };
    match (left, right) {
        (None, None) => Some(std::cmp::Ordering::Equal),
        (None, Some(_)) => Some(std::cmp::Ordering::Less),
        (Some(_), None) => Some(std::cmp::Ordering::Greater),
        (Some(lhs), Some(rhs)) => {
            parse(lhs).and_then(|lhs| parse(rhs).and_then(|rhs| lhs.partial_cmp(&rhs)))
        }
    }
}

fn mysql_grouped_aggregate_having_clause_matches(
    row: &[Option<String>],
    clause: &MySqlCompatGroupedAggregateHavingClause,
) -> bool {
    let left = match clause.target {
        MySqlCompatGroupedAggregateHavingTarget::Group => {
            row.first().and_then(|value| value.as_deref())
        }
        MySqlCompatGroupedAggregateHavingTarget::Aggregate => {
            row.get(1).and_then(|value| value.as_deref())
        }
    };
    match clause.op {
        MySqlCompatGroupedAggregateHavingOp::IsNull => left.is_none(),
        MySqlCompatGroupedAggregateHavingOp::IsNotNull => left.is_some(),
        op => {
            let Some(right) = clause.value.as_deref() else {
                return false;
            };
            let Some(left) = left else {
                return false;
            };
            let cmp = mysql_numeric_text_ordering(Some(left), Some(right))
                .unwrap_or_else(|| mysql_text_ordering(Some(left), Some(right)));
            match op {
                MySqlCompatGroupedAggregateHavingOp::Eq => cmp == std::cmp::Ordering::Equal,
                MySqlCompatGroupedAggregateHavingOp::Ne => cmp != std::cmp::Ordering::Equal,
                MySqlCompatGroupedAggregateHavingOp::Lt => cmp == std::cmp::Ordering::Less,
                MySqlCompatGroupedAggregateHavingOp::Le => cmp != std::cmp::Ordering::Greater,
                MySqlCompatGroupedAggregateHavingOp::Gt => cmp == std::cmp::Ordering::Greater,
                MySqlCompatGroupedAggregateHavingOp::Ge => cmp != std::cmp::Ordering::Less,
                MySqlCompatGroupedAggregateHavingOp::IsNull
                | MySqlCompatGroupedAggregateHavingOp::IsNotNull => false,
            }
        }
    }
}

fn mysql_parse_simple_aggregate_having_clauses(
    having_sql: &str,
    aggregate_expr_raw: &str,
    aggregate_alias: &str,
) -> Option<Vec<MySqlCompatGroupedAggregateHavingClause>> {
    let placeholder_group = "__skeindb_unused_group__";
    let clauses = mysql_parse_grouped_aggregate_having_clauses(
        having_sql,
        placeholder_group,
        placeholder_group,
        None,
        placeholder_group,
        aggregate_expr_raw,
        aggregate_alias,
    )?;
    clauses
        .iter()
        .all(|clause| {
            matches!(
                clause.target,
                MySqlCompatGroupedAggregateHavingTarget::Aggregate
            )
        })
        .then_some(clauses)
}

fn mysql_parse_simple_aggregate_query(sql: &str) -> Option<MySqlCompatSimpleAggregateQuery> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    if !trimmed.is_ascii() || trimmed.len() < 6 || !trimmed[..6].eq_ignore_ascii_case("select") {
        return None;
    }
    let rest = trimmed[6..].trim();
    let from_idx = find_keyword_top_level(rest, "from")?;
    let mut projection = rest[..from_idx].trim();
    loop {
        if projection.len() >= 19 && projection[..19].eq_ignore_ascii_case("sql_calc_found_rows") {
            let after = projection[19..].trim_start();
            if after.len() != projection.len() {
                projection = after;
                continue;
            }
        }
        if projection.len() >= 8 && projection[..8].eq_ignore_ascii_case("distinct") {
            let after = projection[8..].trim_start();
            if after.len() != projection.len() {
                projection = after;
                continue;
            }
        }
        break;
    }
    let (aggregate_expr, alias_raw) = if let Some(idx) = find_keyword_top_level(projection, "as") {
        (projection[..idx].trim(), Some(projection[idx + 2..].trim()))
    } else {
        (projection, None)
    };
    let (aggregate_select_expr, default_alias, op) =
        mysql_parse_aggregate_projection_expr(aggregate_expr)?;
    let select_expr = aggregate_select_expr.unwrap_or_else(|| "*".to_string());
    let alias = alias_raw
        .map(clean_sql_ident)
        .filter(|name| !name.is_empty())
        .unwrap_or(default_alias);
    let mut tail = rest[from_idx..].trim();
    if find_keyword_top_level(tail, "group by").is_some() {
        return None;
    }
    let source_end = ["having", "order by", "limit", "offset"]
        .iter()
        .filter_map(|keyword| find_keyword_top_level(tail, keyword))
        .min()
        .unwrap_or(tail.len());
    let source_from_tail = tail[..source_end].trim().to_string();
    if source_from_tail.is_empty() {
        return None;
    }
    tail = tail[source_end..].trim();

    let mut having_sql = None::<String>;
    let mut limit_sql = None::<String>;
    let mut offset_sql = None::<String>;
    while !tail.is_empty() {
        if tail.to_ascii_lowercase().starts_with("having ") {
            let clause_tail = tail[6..].trim_start();
            let next = ["order by", "limit", "offset"]
                .iter()
                .filter_map(|keyword| find_keyword_top_level(clause_tail, keyword))
                .min()
                .unwrap_or(clause_tail.len());
            having_sql = Some(clause_tail[..next].trim().to_string());
            tail = clause_tail[next..].trim();
            continue;
        }
        if tail.to_ascii_lowercase().starts_with("order by ") {
            let clause_tail = tail[8..].trim_start();
            let next = ["limit", "offset"]
                .iter()
                .filter_map(|keyword| find_keyword_top_level(clause_tail, keyword))
                .min()
                .unwrap_or(clause_tail.len());
            tail = clause_tail[next..].trim();
            continue;
        }
        if tail.to_ascii_lowercase().starts_with("limit ") {
            let clause_tail = tail[5..].trim_start();
            let next = ["offset"]
                .iter()
                .filter_map(|keyword| find_keyword_top_level(clause_tail, keyword))
                .min()
                .unwrap_or(clause_tail.len());
            limit_sql = Some(clause_tail[..next].trim().to_string());
            tail = clause_tail[next..].trim();
            continue;
        }
        if tail.to_ascii_lowercase().starts_with("offset ") {
            let clause_tail = tail[6..].trim_start();
            offset_sql = Some(clause_tail.trim().to_string());
            tail = "";
            continue;
        }
        return None;
    }

    let having = if let Some(having_sql) = having_sql.as_deref() {
        mysql_parse_simple_aggregate_having_clauses(having_sql, aggregate_expr, &alias)?
    } else {
        Vec::new()
    };

    let source_sql = if matches!(op, MySqlCompatAggregateOp::CountDistinct) {
        format!("SELECT DISTINCT {select_expr} {source_from_tail}")
    } else {
        format!("SELECT {select_expr} {source_from_tail}")
    };

    Some(MySqlCompatSimpleAggregateQuery {
        alias,
        aggregate_op: op,
        source_sql,
        having,
        limit: parse_limit_clause(limit_sql.as_deref(), offset_sql.as_deref()).ok()?,
    })
}

async fn mysql_try_simple_aggregate_query_outcome(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Result<Option<MySqlQueryOutcome>, RpcError> {
    let Some(query) = mysql_parse_simple_aggregate_query(sql) else {
        return Ok(None);
    };
    let params = SqlExecParams {
        sql: query.source_sql.clone(),
        explain: false,
        default_db: default_db.map(|db| db.to_string()),
        result_format: Some(ResultFormat::RowsJson),
        as_of_ms: None,
    };
    let result = sql_exec(state, params).await?;
    let (_, rows) =
        mysql_extract_result_data(&result).map_err(|msg| RpcError::new("internal", msg))?;
    let value = match query.aggregate_op {
        MySqlCompatAggregateOp::CountRows => Some(rows.len().to_string()),
        MySqlCompatAggregateOp::CountDistinct => Some(rows.len().to_string()),
        MySqlCompatAggregateOp::CountNonNull => Some(
            rows.iter()
                .filter(|row| row.first().and_then(|value| value.as_ref()).is_some())
                .count()
                .to_string(),
        ),
        MySqlCompatAggregateOp::Sum => {
            let mut total = 0.0f64;
            let mut saw_value = false;
            let mut all_i64 = true;
            for row in &rows {
                let Some(raw) = row.first().and_then(|value| value.as_deref()) else {
                    continue;
                };
                saw_value = true;
                let (value, is_i64) = mysql_parse_numeric_aggregate_value(raw)?;
                all_i64 &= is_i64;
                total += value;
            }
            if !saw_value {
                None
            } else {
                Some(mysql_render_numeric_aggregate_value(total, all_i64))
            }
        }
        MySqlCompatAggregateOp::Min => rows
            .iter()
            .filter_map(|row| row.first().and_then(|value| value.clone()))
            .min_by(|left, right| mysql_aggregate_value_ordering(left, right)),
        MySqlCompatAggregateOp::Max => rows
            .iter()
            .filter_map(|row| row.first().and_then(|value| value.clone()))
            .max_by(|left, right| mysql_aggregate_value_ordering(left, right)),
        MySqlCompatAggregateOp::Avg => {
            let mut total = 0.0f64;
            let mut count = 0u64;
            let mut all_i64 = true;
            for row in &rows {
                let Some(raw) = row.first().and_then(|value| value.as_deref()) else {
                    continue;
                };
                let (value, is_i64) = mysql_parse_numeric_aggregate_value(raw)?;
                all_i64 &= is_i64;
                total += value;
                count = count.saturating_add(1);
            }
            if count == 0 {
                None
            } else {
                Some(mysql_render_numeric_aggregate_value(
                    total / count as f64,
                    all_i64,
                ))
            }
        }
        MySqlCompatAggregateOp::GroupConcat | MySqlCompatAggregateOp::StringAgg => {
            let values: Vec<String> = rows
                .iter()
                .filter_map(|row| row.first().and_then(|value| value.clone()))
                .collect();
            if values.is_empty() {
                None
            } else {
                Some(values.join(","))
            }
        }
        MySqlCompatAggregateOp::ArrayAgg => {
            let values: Vec<String> = rows
                .iter()
                .filter_map(|row| row.first().and_then(|value| value.clone()))
                .collect();
            if values.is_empty() {
                None
            } else {
                let inner = values.join(",");
                Some(format!("{{{inner}}}"))
            }
        }
        MySqlCompatAggregateOp::BitAnd => {
            let mut acc = u64::MAX;
            for row in &rows {
                if let Some(raw) = row.first().and_then(|value| value.as_deref()) {
                    if let Ok(v) = raw.parse::<u64>() {
                        acc &= v;
                    }
                }
            }
            Some(acc.to_string())
        }
        MySqlCompatAggregateOp::BitOr => {
            let mut acc = 0u64;
            for row in &rows {
                if let Some(raw) = row.first().and_then(|value| value.as_deref()) {
                    if let Ok(v) = raw.parse::<u64>() {
                        acc |= v;
                    }
                }
            }
            Some(acc.to_string())
        }
        MySqlCompatAggregateOp::BitXor => {
            let mut acc = 0u64;
            for row in &rows {
                if let Some(raw) = row.first().and_then(|value| value.as_deref()) {
                    if let Ok(v) = raw.parse::<u64>() {
                        acc ^= v;
                    }
                }
            }
            Some(acc.to_string())
        }
    };
    let mut out_rows = if query.having.is_empty() {
        vec![vec![value]]
    } else {
        let having_row = vec![None, value.clone()];
        if query
            .having
            .iter()
            .all(|clause| mysql_grouped_aggregate_having_clause_matches(&having_row, clause))
        {
            vec![vec![value]]
        } else {
            Vec::new()
        }
    };

    if let Some(limit) = query.limit {
        let offset = limit.offset.unwrap_or(0) as usize;
        if offset > 0 {
            out_rows = out_rows.into_iter().skip(offset).collect();
        }
        if let Some(limit) = limit.limit {
            out_rows = out_rows.into_iter().take(limit as usize).collect();
        }
    }

    Ok(Some(MySqlQueryOutcome::ResultSet {
        columns: vec![query.alias],
        rows: out_rows,
    }))
}

async fn mysql_try_multi_aggregate_query_outcome(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Result<Option<MySqlQueryOutcome>, RpcError> {
    let Some(query) = mysql_parse_multi_aggregate_query(sql) else {
        return Ok(None);
    };
    let result = sql_exec(
        state,
        SqlExecParams {
            sql: query.source_sql,
            explain: false,
            default_db: default_db.map(|db| db.to_string()),
            result_format: Some(ResultFormat::RowsJson),
            as_of_ms: None,
        },
    )
    .await?;
    let (columns, rows) =
        mysql_extract_result_data(&result).map_err(|msg| RpcError::new("internal", msg))?;
    let mut counts = vec![0u64; query.items.len()];

    for row in rows {
        let row_map = columns
            .iter()
            .zip(row.iter())
            .filter_map(|(column, value)| {
                value
                    .as_ref()
                    .map(|raw| (column.clone(), mysql_text_result_value_to_lit(Some(raw))))
            })
            .collect::<BTreeMap<_, _>>();

        for (idx, item) in query.items.iter().enumerate() {
            match item {
                MySqlCompatMultiAggregateItem::Rows { .. } => {
                    counts[idx] = counts[idx].saturating_add(1);
                }
                MySqlCompatMultiAggregateItem::NonNull { column, .. } => {
                    let value = row_get_lit(&row_map, column);
                    if value.is_some() && !matches!(value, Some(Lit::Null)) {
                        counts[idx] = counts[idx].saturating_add(1);
                    }
                }
                MySqlCompatMultiAggregateItem::Predicate { predicate, .. } => {
                    if mysql_eval_row_predicate_expr(predicate, &row_map)? {
                        counts[idx] = counts[idx].saturating_add(1);
                    }
                }
            }
        }
    }

    Ok(Some(MySqlQueryOutcome::ResultSet {
        columns: query
            .items
            .iter()
            .map(|item| match item {
                MySqlCompatMultiAggregateItem::Rows { alias }
                | MySqlCompatMultiAggregateItem::NonNull { alias, .. }
                | MySqlCompatMultiAggregateItem::Predicate { alias, .. } => alias.clone(),
            })
            .collect(),
        rows: vec![counts
            .into_iter()
            .map(|count| Some(count.to_string()))
            .collect()],
    }))
}

// ── Multi-column GROUP BY parser ────────────────────────────────────────
fn mysql_parse_multi_grouped_aggregate_query(
    sql: &str,
) -> Option<MySqlCompatMultiGroupedAggregateQuery> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    if !trimmed.is_ascii() || trimmed.len() < 6 || !trimmed[..6].eq_ignore_ascii_case("select") {
        return None;
    }
    let rest = trimmed[6..].trim();
    let from_idx = find_keyword_top_level(rest, "from")?;
    let projection = rest[..from_idx].trim();
    let from_tail = rest[from_idx..].trim();
    let group_idx = find_keyword_top_level(from_tail, "group by")?;
    let source_from_tail = from_tail[..group_idx].trim().to_string();
    if source_from_tail.is_empty() {
        return None;
    }
    let mut group_tail = from_tail[group_idx + "group by".len()..].trim();
    let group_key_end = ["having", "order by", "limit", "offset"]
        .iter()
        .filter_map(|keyword| find_keyword_top_level(group_tail, keyword))
        .min()
        .unwrap_or(group_tail.len());
    let group_by_expr = group_tail[..group_key_end].trim().to_string();
    if group_by_expr.is_empty() {
        return None;
    }
    group_tail = group_tail[group_key_end..].trim();

    let mut limit_sql = None::<String>;
    let mut offset_sql = None::<String>;
    let mut order_sql = None::<String>;
    while !group_tail.is_empty() {
        let gl = group_tail.to_ascii_lowercase();
        if gl.starts_with("having ") {
            return None;
        }
        if gl.starts_with("order by ") {
            let tail = group_tail[8..].trim_start();
            let next = ["limit", "offset"]
                .iter()
                .filter_map(|keyword| find_keyword_top_level(tail, keyword))
                .min()
                .unwrap_or(tail.len());
            order_sql = Some(tail[..next].trim().to_string());
            group_tail = tail[next..].trim();
            continue;
        }
        if gl.starts_with("limit ") {
            let tail = group_tail[5..].trim_start();
            let next = ["offset"]
                .iter()
                .filter_map(|keyword| find_keyword_top_level(tail, keyword))
                .min()
                .unwrap_or(tail.len());
            limit_sql = Some(tail[..next].trim().to_string());
            group_tail = tail[next..].trim();
            continue;
        }
        if gl.starts_with("offset ") {
            let tail = group_tail[6..].trim_start();
            offset_sql = Some(tail.trim().to_string());
            group_tail = "";
            continue;
        }
        return None;
    }

    let projection_items = split_csv_top_level(projection);
    // Requires at least 3 items (distinguishes from 2-item single-column handler)
    if projection_items.len() < 3 {
        return None;
    }
    let projection_items = projection_items
        .iter()
        .map(|item| mysql_parse_projection_expr_alias(item))
        .collect::<Vec<_>>();

    let mut group_cols = Vec::new();
    let mut group_aliases = Vec::new();
    let mut aggregate_aliases = Vec::new();
    let mut aggregate_ops = Vec::new();
    let mut agg_select_exprs = Vec::new(); // aggregate input columns (e.g. "o.id", "o.amount")
    let mut source_exprs = Vec::new();

    for (expr, alias_opt) in &projection_items {
        if let Some((select_expr, default_alias, op)) = mysql_parse_aggregate_projection_expr(expr)
        {
            let alias = alias_opt
                .clone()
                .filter(|s| !s.is_empty())
                .unwrap_or(default_alias);
            aggregate_aliases.push(alias);
            aggregate_ops.push(op);
            agg_select_exprs.push(select_expr);
        } else if let Some((col, table)) = parse_sql_column_ref(expr) {
            let select_expr = table
                .as_ref()
                .map(|t| format!("{t}.{col}"))
                .unwrap_or_else(|| col.clone());
            let alias = alias_opt
                .clone()
                .filter(|s| !s.is_empty())
                .unwrap_or_else(|| col.clone());
            group_cols.push(select_expr.clone());
            group_aliases.push(alias);
            source_exprs.push(select_expr);
        } else {
            return None;
        }
    }
    if group_cols.is_empty() || aggregate_ops.is_empty() {
        return None;
    }

    // Validate GROUP BY columns match projected group columns
    let group_by_parts = split_csv_top_level(&group_by_expr);
    if group_by_parts.len() != group_cols.len() {
        return None;
    }
    for part in &group_by_parts {
        let part_trimmed = part.trim();
        if let Ok(pos) = part_trimmed.parse::<usize>() {
            if pos == 0 || pos > projection_items.len() {
                return None;
            }
        } else {
            let found = group_cols
                .iter()
                .any(|gc| gc.eq_ignore_ascii_case(part_trimmed))
                || group_aliases
                    .iter()
                    .any(|ga| ga.eq_ignore_ascii_case(part_trimmed));
            if !found {
                return None;
            }
        }
    }

    // Append aggregate input columns to source_exprs and track their indices
    let mut agg_col_indices = Vec::with_capacity(agg_select_exprs.len());
    for agg_expr in &agg_select_exprs {
        if let Some(expr) = agg_expr {
            // Check if already in source_exprs
            let existing = source_exprs
                .iter()
                .position(|e| e.eq_ignore_ascii_case(expr));
            if let Some(idx) = existing {
                agg_col_indices.push(Some(idx));
            } else {
                let idx = source_exprs.len();
                source_exprs.push(expr.clone());
                agg_col_indices.push(Some(idx));
            }
        } else {
            agg_col_indices.push(None); // COUNT(*) - no column needed
        }
    }

    let source_sql = format!("SELECT {} {}", source_exprs.join(", "), source_from_tail);

    // Parse ORDER BY
    let mut order_by = Vec::new();
    if let Some(order_str) = order_sql {
        for part in split_csv_top_level(&order_str) {
            let part = part.trim();
            let desc = part.to_ascii_lowercase().ends_with(" desc");
            let asc = part.to_ascii_lowercase().ends_with(" asc");
            let col = if desc {
                part[..part.len() - 5].trim()
            } else if asc {
                part[..part.len() - 4].trim()
            } else {
                part
            };
            order_by.push((col.to_string(), desc));
        }
    }

    Some(MySqlCompatMultiGroupedAggregateQuery {
        group_aliases,
        aggregate_aliases,
        aggregate_ops,
        agg_col_indices,
        source_sql,
        order_by,
        limit: parse_limit_clause(limit_sql.as_deref(), offset_sql.as_deref()).ok()?,
    })
}

// ── Multi-column GROUP BY executor ──────────────────────────────────────
async fn mysql_try_multi_grouped_aggregate_query_outcome(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Result<Option<MySqlQueryOutcome>, RpcError> {
    let Some(query) = mysql_parse_multi_grouped_aggregate_query(sql) else {
        return Ok(None);
    };
    let num_groups = query.group_aliases.len();
    let params = SqlExecParams {
        sql: query.source_sql,
        explain: false,
        default_db: default_db.map(|db| db.to_string()),
        result_format: Some(ResultFormat::RowsJson),
        as_of_ms: None,
    };
    let result = sql_exec(state, params).await?;
    let (_, rows) =
        mysql_extract_result_data(&result).map_err(|msg| RpcError::new("internal", msg))?;

    let mut grouped_rows =
        Vec::<(Vec<Option<String>>, Vec<MySqlCompatGroupedAggregateState>)>::new();
    let mut grouped_lookup = HashMap::<Vec<Option<String>>, usize>::new();
    for row in rows {
        let group_key: Vec<Option<String>> = row.iter().take(num_groups).cloned().collect();
        let entry_idx = if let Some(idx) = grouped_lookup.get(&group_key).copied() {
            idx
        } else {
            let states = query
                .aggregate_ops
                .iter()
                .map(|_| MySqlCompatGroupedAggregateState::new())
                .collect();
            grouped_rows.push((group_key.clone(), states));
            let idx = grouped_rows.len().saturating_sub(1);
            grouped_lookup.insert(group_key, idx);
            idx
        };
        let states = &mut grouped_rows[entry_idx].1;
        for (agg_idx, op) in query.aggregate_ops.iter().enumerate() {
            let agg_state = &mut states[agg_idx];
            agg_state.row_count = agg_state.row_count.saturating_add(1);
            let agg_val = query.agg_col_indices[agg_idx]
                .and_then(|ci| row.get(ci))
                .and_then(|v| v.as_deref());
            match op {
                MySqlCompatAggregateOp::CountRows => {}
                MySqlCompatAggregateOp::CountNonNull => {
                    if agg_val.is_some() {
                        agg_state.non_null_count = agg_state.non_null_count.saturating_add(1);
                    }
                }
                MySqlCompatAggregateOp::CountDistinct => {
                    if let Some(raw) = agg_val {
                        agg_state.distinct_values.insert(raw.to_string());
                    }
                }
                MySqlCompatAggregateOp::Sum | MySqlCompatAggregateOp::Avg => {
                    if let Some(raw) = agg_val {
                        if let Ok((value, is_i64)) = mysql_parse_numeric_aggregate_value(raw) {
                            agg_state.non_null_count = agg_state.non_null_count.saturating_add(1);
                            agg_state.numeric_saw_value = true;
                            agg_state.numeric_all_i64 &= is_i64;
                            agg_state.numeric_total += value;
                        }
                    }
                }
                MySqlCompatAggregateOp::Min => {
                    if let Some(raw) = agg_val {
                        agg_state.non_null_count = agg_state.non_null_count.saturating_add(1);
                        if agg_state
                            .min_value
                            .as_deref()
                            .map(|current| mysql_aggregate_value_ordering(raw, current).is_lt())
                            .unwrap_or(true)
                        {
                            agg_state.min_value = Some(raw.to_string());
                        }
                    }
                }
                MySqlCompatAggregateOp::Max => {
                    if let Some(raw) = agg_val {
                        agg_state.non_null_count = agg_state.non_null_count.saturating_add(1);
                        if agg_state
                            .max_value
                            .as_deref()
                            .map(|current| mysql_aggregate_value_ordering(raw, current).is_gt())
                            .unwrap_or(true)
                        {
                            agg_state.max_value = Some(raw.to_string());
                        }
                    }
                }
                MySqlCompatAggregateOp::GroupConcat
                | MySqlCompatAggregateOp::StringAgg
                | MySqlCompatAggregateOp::ArrayAgg => {
                    if let Some(raw) = agg_val {
                        agg_state.concat_values.push(raw.to_string());
                    }
                }
                MySqlCompatAggregateOp::BitAnd => {
                    if let Some(raw) = agg_val {
                        if let Ok(v) = raw.parse::<u64>() {
                            if !agg_state.bitwise_initialized {
                                agg_state.bitwise_acc = u64::MAX;
                                agg_state.bitwise_initialized = true;
                            }
                            agg_state.bitwise_acc &= v;
                        }
                    }
                }
                MySqlCompatAggregateOp::BitOr => {
                    if let Some(raw) = agg_val {
                        if let Ok(v) = raw.parse::<u64>() {
                            agg_state.bitwise_initialized = true;
                            agg_state.bitwise_acc |= v;
                        }
                    }
                }
                MySqlCompatAggregateOp::BitXor => {
                    if let Some(raw) = agg_val {
                        if let Ok(v) = raw.parse::<u64>() {
                            agg_state.bitwise_initialized = true;
                            agg_state.bitwise_acc ^= v;
                        }
                    }
                }
            }
        }
    }

    let mut out_rows: Vec<Vec<Option<String>>> = grouped_rows
        .into_iter()
        .map(|(group_key, states)| {
            let mut row = group_key;
            for (agg_idx, op) in query.aggregate_ops.iter().enumerate() {
                let st = &states[agg_idx];
                let val = match op {
                    MySqlCompatAggregateOp::CountRows => Some(st.row_count.to_string()),
                    MySqlCompatAggregateOp::CountNonNull => Some(st.non_null_count.to_string()),
                    MySqlCompatAggregateOp::CountDistinct => {
                        Some(st.distinct_values.len().to_string())
                    }
                    MySqlCompatAggregateOp::Sum => {
                        if !st.numeric_saw_value {
                            None
                        } else {
                            Some(mysql_render_numeric_aggregate_value(
                                st.numeric_total,
                                st.numeric_all_i64,
                            ))
                        }
                    }
                    MySqlCompatAggregateOp::Min => st.min_value.clone(),
                    MySqlCompatAggregateOp::Max => st.max_value.clone(),
                    MySqlCompatAggregateOp::Avg => {
                        if !st.numeric_saw_value || st.non_null_count == 0 {
                            None
                        } else {
                            Some(mysql_render_numeric_aggregate_value(
                                st.numeric_total / st.non_null_count as f64,
                                st.numeric_all_i64,
                            ))
                        }
                    }
                    MySqlCompatAggregateOp::GroupConcat => {
                        if st.concat_values.is_empty() {
                            None
                        } else {
                            Some(st.concat_values.join(","))
                        }
                    }
                    MySqlCompatAggregateOp::StringAgg => {
                        if st.concat_values.is_empty() {
                            None
                        } else {
                            Some(st.concat_values.join(","))
                        }
                    }
                    MySqlCompatAggregateOp::ArrayAgg => {
                        if st.concat_values.is_empty() {
                            None
                        } else {
                            let inner = st.concat_values.join(",");
                            Some(format!("{{{inner}}}"))
                        }
                    }
                    MySqlCompatAggregateOp::BitAnd
                    | MySqlCompatAggregateOp::BitOr
                    | MySqlCompatAggregateOp::BitXor => Some(st.bitwise_acc.to_string()),
                };
                row.push(val);
            }
            row
        })
        .collect();

    let mut columns = query.group_aliases;
    columns.extend(query.aggregate_aliases);

    // Apply ORDER BY
    if !query.order_by.is_empty() {
        let col_indices: Vec<(usize, bool)> = query
            .order_by
            .iter()
            .filter_map(|(col, desc)| {
                columns
                    .iter()
                    .position(|c| c.eq_ignore_ascii_case(col))
                    .map(|idx| (idx, *desc))
            })
            .collect();
        if !col_indices.is_empty() {
            out_rows.sort_by(|a, b| {
                for &(ci, desc) in &col_indices {
                    let va = a.get(ci).and_then(|v| v.as_deref()).unwrap_or("");
                    let vb = b.get(ci).and_then(|v| v.as_deref()).unwrap_or("");
                    let ord = mysql_aggregate_value_ordering(va, vb);
                    let ord = if desc { ord.reverse() } else { ord };
                    if ord != std::cmp::Ordering::Equal {
                        return ord;
                    }
                }
                std::cmp::Ordering::Equal
            });
        }
    }

    if let Some(limit) = query.limit {
        let offset = limit.offset.unwrap_or(0) as usize;
        if offset > 0 {
            out_rows = out_rows.into_iter().skip(offset).collect();
        }
        if let Some(limit) = limit.limit {
            out_rows = out_rows.into_iter().take(limit as usize).collect();
        }
    }

    Ok(Some(MySqlQueryOutcome::ResultSet {
        columns,
        rows: out_rows,
    }))
}

// ── Window function support ──────────────────────────────────────────────
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WindowFunctionKind {
    RowNumber,
    Rank,
    DenseRank,
}

struct WindowFunctionSpec {
    kind: WindowFunctionKind,
    alias: String,
    partition_col: Option<String>,
    order_col: Option<String>,
    order_desc: bool,
}

fn mysql_parse_window_function_select(
    sql: &str,
) -> Option<(Vec<WindowFunctionSpec>, Vec<String>, String)> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("select ") {
        return None;
    }
    let from_idx = find_keyword_top_level(trimmed, "from")?;
    let projection = trimmed[7..from_idx].trim();
    let rest_from = trimmed[from_idx..].trim();

    let exprs = split_select_expressions(projection)?;
    let mut window_specs = Vec::new();
    let mut pass_through_cols = Vec::new();

    for expr in &exprs {
        let expr_trimmed = expr.trim();
        let expr_lower = expr_trimmed.to_ascii_lowercase();

        let (kind, fn_len) = if expr_lower.starts_with("row_number()") {
            (WindowFunctionKind::RowNumber, "row_number()".len())
        } else if expr_lower.starts_with("dense_rank()") {
            (WindowFunctionKind::DenseRank, "dense_rank()".len())
        } else if expr_lower.starts_with("rank()") {
            (WindowFunctionKind::Rank, "rank()".len())
        } else {
            // Regular column — extract alias or use expression
            let (_, alias_opt) = if let Some(as_pos) =
                find_ascii_ci_outside_quotes(expr_trimmed.as_bytes(), b" as ")
            {
                (
                    expr_trimmed[..as_pos].trim(),
                    Some(expr_trimmed[as_pos + 4..].trim().to_string()),
                )
            } else {
                (expr_trimmed, None)
            };
            let col_name = alias_opt.unwrap_or_else(|| expr_trimmed.to_string());
            pass_through_cols.push(col_name);
            continue;
        };

        let after_fn = expr_trimmed[fn_len..].trim();
        let after_fn_lower = after_fn.to_ascii_lowercase();
        if !after_fn_lower.starts_with("over") {
            pass_through_cols.push(expr_trimmed.to_string());
            continue;
        }
        let over_rest = after_fn[4..].trim();
        // Parse OVER(... ) AS alias
        if !over_rest.starts_with('(') {
            continue;
        }
        let close_paren = over_rest.find(')')?;
        let over_body = over_rest[1..close_paren].trim();
        let after_over = over_rest[close_paren + 1..].trim();

        let alias =
            if let Some(as_pos) = find_ascii_ci_outside_quotes(after_over.as_bytes(), b" as ") {
                after_over[as_pos + 4..].trim().to_string()
            } else if after_over.to_ascii_lowercase().starts_with("as ") {
                after_over[3..].trim().to_string()
            } else {
                match kind {
                    WindowFunctionKind::RowNumber => "row_number".to_string(),
                    WindowFunctionKind::Rank => "rank".to_string(),
                    WindowFunctionKind::DenseRank => "dense_rank".to_string(),
                }
            };

        let over_lower = over_body.to_ascii_lowercase();
        let partition_col = if let Some(p_idx) = over_lower.find("partition by ") {
            let rest = over_body[p_idx + "partition by ".len()..].trim();
            let end = rest
                .find(|c: char| c.is_ascii_whitespace())
                .unwrap_or(rest.len());
            Some(rest[..end].trim().to_string())
        } else {
            None
        };
        let (order_col, order_desc) = if let Some(o_idx) = over_lower.find("order by ") {
            let rest = over_body[o_idx + "order by ".len()..].trim();
            let rest_lower = rest.to_ascii_lowercase();
            let desc = rest_lower.ends_with(" desc");
            let asc = rest_lower.ends_with(" asc");
            let col = if desc {
                rest[..rest.len() - 5].trim().to_string()
            } else if asc {
                rest[..rest.len() - 4].trim().to_string()
            } else {
                rest.to_string()
            };
            (Some(col), desc)
        } else {
            (None, false)
        };

        window_specs.push(WindowFunctionSpec {
            kind,
            alias,
            partition_col,
            order_col,
            order_desc,
        });
    }

    if window_specs.is_empty() {
        return None;
    }

    // Reconstruct SELECT with only the pass-through columns
    let base_select = if pass_through_cols.is_empty() {
        format!("SELECT * {rest_from}")
    } else {
        format!("SELECT {} {rest_from}", pass_through_cols.join(", "))
    };

    Some((window_specs, pass_through_cols, base_select))
}

async fn mysql_try_window_function_query(
    state: &AppState,
    sql: &str,
    session: &mut MySqlSessionState,
) -> Result<Option<MySqlQueryOutcome>, MySqlWireError> {
    let Some((window_specs, _pass_cols, base_sql)) = mysql_parse_window_function_select(sql) else {
        return Ok(None);
    };

    let base_result = Box::pin(mysql_execute_sql(state, &base_sql, session)).await?;
    let MySqlQueryOutcome::ResultSet {
        mut columns, rows, ..
    } = base_result
    else {
        return Ok(None);
    };

    // Add window function columns
    for spec in &window_specs {
        columns.push(spec.alias.clone());
    }

    // For each window function, compute the values
    let mut augmented_rows: Vec<Vec<Option<String>>> = rows;

    for spec in &window_specs {
        let order_col_idx = spec
            .order_col
            .as_ref()
            .and_then(|name| columns.iter().position(|c| c.eq_ignore_ascii_case(name)));
        let partition_col_idx = spec
            .partition_col
            .as_ref()
            .and_then(|name| columns.iter().position(|c| c.eq_ignore_ascii_case(name)));

        // Sort rows if ORDER BY specified
        if let Some(ord_idx) = order_col_idx {
            augmented_rows.sort_by(|a, b| {
                let va = a.get(ord_idx).and_then(|v| v.as_deref()).unwrap_or("");
                let vb = b.get(ord_idx).and_then(|v| v.as_deref()).unwrap_or("");
                let cmp = mysql_aggregate_value_ordering(va, vb);
                if spec.order_desc {
                    cmp.reverse()
                } else {
                    cmp
                }
            });
        }

        // Compute window values
        let num_rows = augmented_rows.len();
        let mut window_values = Vec::with_capacity(num_rows);

        match spec.kind {
            WindowFunctionKind::RowNumber => {
                let mut partition_counters: HashMap<String, u64> = HashMap::new();
                for row in &augmented_rows {
                    let partition_key = partition_col_idx
                        .and_then(|idx| row.get(idx).and_then(|v| v.clone()))
                        .unwrap_or_default();
                    let counter = partition_counters.entry(partition_key).or_insert(0);
                    *counter += 1;
                    window_values.push(Some(counter.to_string()));
                }
            }
            WindowFunctionKind::Rank => {
                let mut partition_state: HashMap<String, (u64, Option<String>)> = HashMap::new();
                for (i, row) in augmented_rows.iter().enumerate() {
                    let partition_key = partition_col_idx
                        .and_then(|idx| row.get(idx).and_then(|v| v.clone()))
                        .unwrap_or_default();
                    let order_val =
                        order_col_idx.and_then(|idx| row.get(idx).and_then(|v| v.clone()));
                    let state = partition_state.entry(partition_key).or_insert((0, None));
                    state.0 += 1; // row position within partition
                    if state.1 != order_val || i == 0 {
                        // New rank value
                        window_values.push(Some(state.0.to_string()));
                        state.1 = order_val;
                    } else {
                        // Same rank as previous
                        let prev = window_values
                            .last()
                            .cloned()
                            .unwrap_or(Some("1".to_string()));
                        window_values.push(prev);
                    }
                }
            }
            WindowFunctionKind::DenseRank => {
                let mut partition_state: HashMap<String, (u64, Option<String>)> = HashMap::new();
                for row in &augmented_rows {
                    let partition_key = partition_col_idx
                        .and_then(|idx| row.get(idx).and_then(|v| v.clone()))
                        .unwrap_or_default();
                    let order_val =
                        order_col_idx.and_then(|idx| row.get(idx).and_then(|v| v.clone()));
                    let state = partition_state.entry(partition_key).or_insert((0, None));
                    if state.1 != order_val {
                        state.0 += 1;
                        state.1 = order_val;
                    }
                    window_values.push(Some(state.0.to_string()));
                }
            }
        }

        // Append window values to rows
        for (row, wval) in augmented_rows.iter_mut().zip(window_values) {
            row.push(wval);
        }
    }

    Ok(Some(MySqlQueryOutcome::ResultSet {
        columns,
        rows: augmented_rows,
    }))
}

async fn mysql_try_grouped_aggregate_query_outcome(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Result<Option<MySqlQueryOutcome>, RpcError> {
    let Some(query) = mysql_parse_grouped_aggregate_query(sql) else {
        return Ok(None);
    };
    let params = SqlExecParams {
        sql: query.source_sql,
        explain: false,
        default_db: default_db.map(|db| db.to_string()),
        result_format: Some(ResultFormat::RowsJson),
        as_of_ms: None,
    };
    let result = sql_exec(state, params).await?;
    let (_, rows) =
        mysql_extract_result_data(&result).map_err(|msg| RpcError::new("internal", msg))?;

    let mut grouped_rows = Vec::<(Option<String>, MySqlCompatGroupedAggregateState)>::new();
    let mut grouped_lookup = HashMap::<Option<String>, usize>::new();
    for row in rows {
        let group_key = row.first().cloned().unwrap_or(None);
        let entry_idx = if let Some(idx) = grouped_lookup.get(&group_key).copied() {
            idx
        } else {
            grouped_rows.push((group_key.clone(), MySqlCompatGroupedAggregateState::new()));
            let idx = grouped_rows.len().saturating_sub(1);
            grouped_lookup.insert(group_key, idx);
            idx
        };
        let state = &mut grouped_rows[entry_idx].1;
        state.row_count = state.row_count.saturating_add(1);
        let aggregate_value = row
            .get(1)
            .and_then(|value| value.as_ref())
            .map(|s| s.as_str());
        match query.aggregate_op {
            MySqlCompatAggregateOp::CountRows => {}
            MySqlCompatAggregateOp::CountNonNull => {
                if aggregate_value.is_some() {
                    state.non_null_count = state.non_null_count.saturating_add(1);
                }
            }
            MySqlCompatAggregateOp::CountDistinct => {
                if let Some(raw) = aggregate_value {
                    state.distinct_values.insert(raw.to_string());
                }
            }
            MySqlCompatAggregateOp::Sum | MySqlCompatAggregateOp::Avg => {
                let Some(raw) = aggregate_value else {
                    continue;
                };
                let (value, is_i64) = mysql_parse_numeric_aggregate_value(raw)?;
                state.non_null_count = state.non_null_count.saturating_add(1);
                state.numeric_saw_value = true;
                state.numeric_all_i64 &= is_i64;
                state.numeric_total += value;
            }
            MySqlCompatAggregateOp::Min => {
                let Some(raw) = aggregate_value else {
                    continue;
                };
                state.non_null_count = state.non_null_count.saturating_add(1);
                if state
                    .min_value
                    .as_deref()
                    .map(|current| mysql_aggregate_value_ordering(raw, current).is_lt())
                    .unwrap_or(true)
                {
                    state.min_value = Some(raw.to_string());
                }
            }
            MySqlCompatAggregateOp::Max => {
                let Some(raw) = aggregate_value else {
                    continue;
                };
                state.non_null_count = state.non_null_count.saturating_add(1);
                if state
                    .max_value
                    .as_deref()
                    .map(|current| mysql_aggregate_value_ordering(raw, current).is_gt())
                    .unwrap_or(true)
                {
                    state.max_value = Some(raw.to_string());
                }
            }
            MySqlCompatAggregateOp::GroupConcat
            | MySqlCompatAggregateOp::StringAgg
            | MySqlCompatAggregateOp::ArrayAgg => {
                if let Some(raw) = aggregate_value {
                    state.concat_values.push(raw.to_string());
                }
            }
            MySqlCompatAggregateOp::BitAnd => {
                if let Some(raw) = aggregate_value {
                    if let Ok(v) = raw.parse::<u64>() {
                        if !state.bitwise_initialized {
                            state.bitwise_acc = u64::MAX;
                            state.bitwise_initialized = true;
                        }
                        state.bitwise_acc &= v;
                    }
                }
            }
            MySqlCompatAggregateOp::BitOr => {
                if let Some(raw) = aggregate_value {
                    if let Ok(v) = raw.parse::<u64>() {
                        state.bitwise_initialized = true;
                        state.bitwise_acc |= v;
                    }
                }
            }
            MySqlCompatAggregateOp::BitXor => {
                if let Some(raw) = aggregate_value {
                    if let Ok(v) = raw.parse::<u64>() {
                        state.bitwise_initialized = true;
                        state.bitwise_acc ^= v;
                    }
                }
            }
        }
    }

    let mut out_rows = grouped_rows
        .into_iter()
        .map(|(group_key, state)| {
            let aggregate_value = match query.aggregate_op {
                MySqlCompatAggregateOp::CountRows => Some(state.row_count.to_string()),
                MySqlCompatAggregateOp::CountNonNull => Some(state.non_null_count.to_string()),
                MySqlCompatAggregateOp::CountDistinct => {
                    Some(state.distinct_values.len().to_string())
                }
                MySqlCompatAggregateOp::Sum => {
                    if !state.numeric_saw_value {
                        None
                    } else {
                        Some(mysql_render_numeric_aggregate_value(
                            state.numeric_total,
                            state.numeric_all_i64,
                        ))
                    }
                }
                MySqlCompatAggregateOp::Min => state.min_value,
                MySqlCompatAggregateOp::Max => state.max_value,
                MySqlCompatAggregateOp::Avg => {
                    if !state.numeric_saw_value || state.non_null_count == 0 {
                        None
                    } else {
                        Some(mysql_render_numeric_aggregate_value(
                            state.numeric_total / state.non_null_count as f64,
                            state.numeric_all_i64,
                        ))
                    }
                }
                MySqlCompatAggregateOp::GroupConcat | MySqlCompatAggregateOp::StringAgg => {
                    if state.concat_values.is_empty() {
                        None
                    } else {
                        Some(state.concat_values.join(","))
                    }
                }
                MySqlCompatAggregateOp::ArrayAgg => {
                    if state.concat_values.is_empty() {
                        None
                    } else {
                        let inner = state.concat_values.join(",");
                        Some(format!("{{{inner}}}"))
                    }
                }
                MySqlCompatAggregateOp::BitAnd
                | MySqlCompatAggregateOp::BitOr
                | MySqlCompatAggregateOp::BitXor => Some(state.bitwise_acc.to_string()),
            };
            vec![group_key, aggregate_value]
        })
        .collect::<Vec<_>>();

    if !query.having.is_empty() {
        out_rows.retain(|row| {
            query
                .having
                .iter()
                .all(|clause| mysql_grouped_aggregate_having_clause_matches(row, clause))
        });
    }

    if !query.order_by.is_empty() {
        out_rows.sort_by(|left, right| {
            for order in &query.order_by {
                let (left_value, right_value) = match order.target {
                    MySqlCompatGroupedAggregateOrderTarget::Group => (
                        left.first().and_then(|value| value.as_deref()),
                        right.first().and_then(|value| value.as_deref()),
                    ),
                    MySqlCompatGroupedAggregateOrderTarget::Aggregate => (
                        left.get(1).and_then(|value| value.as_deref()),
                        right.get(1).and_then(|value| value.as_deref()),
                    ),
                };
                let mut cmp = if matches!(
                    order.target,
                    MySqlCompatGroupedAggregateOrderTarget::Aggregate
                ) {
                    mysql_numeric_text_ordering(left_value, right_value)
                        .unwrap_or_else(|| mysql_text_ordering(left_value, right_value))
                } else {
                    mysql_text_ordering(left_value, right_value)
                };
                if order.desc {
                    cmp = cmp.reverse();
                }
                if cmp != std::cmp::Ordering::Equal {
                    return cmp;
                }
            }
            std::cmp::Ordering::Equal
        });
    }

    if let Some(limit) = query.limit {
        let offset = limit.offset.unwrap_or(0) as usize;
        if offset > 0 {
            out_rows = out_rows.into_iter().skip(offset).collect();
        }
        if let Some(limit) = limit.limit {
            out_rows = out_rows.into_iter().take(limit as usize).collect();
        }
    }

    Ok(Some(MySqlQueryOutcome::ResultSet {
        columns: vec![query.group_alias, query.aggregate_alias],
        rows: out_rows,
    }))
}

async fn mysql_try_info_schema_table_storage_query_outcome(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Result<Option<MySqlQueryOutcome>, RpcError> {
    let Some(query) = mysql_parse_info_schema_table_storage_query(sql, default_db) else {
        return Ok(None);
    };
    let result = sql_exec(
        state,
        SqlExecParams {
            sql: query.source_sql,
            explain: false,
            default_db: default_db.map(|db| db.to_string()),
            result_format: Some(ResultFormat::RowsJson),
            as_of_ms: None,
        },
    )
    .await?;
    let (_, rows) =
        mysql_extract_result_data(&result).map_err(|msg| RpcError::new("internal", msg))?;

    let mut grouped_rows = Vec::<(Option<String>, Option<String>, u64)>::new();
    let mut grouped_lookup = HashMap::<Option<String>, usize>::new();
    for row in rows {
        let table_name = row.first().cloned().unwrap_or(None);
        let entry_idx = if let Some(idx) = grouped_lookup.get(&table_name).copied() {
            idx
        } else {
            grouped_rows.push((table_name.clone(), None, 0));
            let idx = grouped_rows.len().saturating_sub(1);
            grouped_lookup.insert(table_name, idx);
            idx
        };
        let entry = &mut grouped_rows[entry_idx];
        if entry.1.is_none() {
            entry.1 = row.get(1).cloned().unwrap_or(None);
        }
        let data_length = row
            .get(2)
            .and_then(|value| value.as_deref())
            .and_then(|value| value.parse::<u64>().ok())
            .unwrap_or(0);
        let index_length = row
            .get(3)
            .and_then(|value| value.as_deref())
            .and_then(|value| value.parse::<u64>().ok())
            .unwrap_or(0);
        entry.2 = entry
            .2
            .saturating_add(data_length.saturating_add(index_length));
    }

    Ok(Some(MySqlQueryOutcome::ResultSet {
        columns: vec![query.table_alias, query.rows_alias, query.bytes_alias],
        rows: grouped_rows
            .into_iter()
            .map(|(table_name, table_rows, bytes)| {
                vec![table_name, table_rows, Some(bytes.to_string())]
            })
            .collect(),
    }))
}

fn mysql_render_create_table(table_name: &str, desc: &Value) -> String {
    let mut defs = Vec::new();
    let columns = desc
        .get("columns")
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_default();
    for col in columns {
        let name = col.get("name").and_then(|v| v.as_str()).unwrap_or_default();
        let mut line = format!(
            "  {} {}",
            mysql_quote_ident(name),
            mysql_type_desc_display(col.get("type").unwrap_or(&Value::Null))
        );
        if !col
            .get("nullable")
            .and_then(|v| v.as_bool())
            .unwrap_or(true)
        {
            line.push_str(" NOT NULL");
        }
        if let Some(default) = mysql_desc_column_default(desc, name) {
            line.push_str(" DEFAULT ");
            line.push_str(&mysql_render_default_lit(&default));
        }
        if col
            .get("auto_increment")
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
        {
            line.push_str(" AUTO_INCREMENT");
        }
        defs.push(line);
    }
    let pk = desc
        .get("primary_key")
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_default();
    if !pk.is_empty() {
        let keys = pk
            .iter()
            .filter_map(|v| v.as_str())
            .map(mysql_quote_ident)
            .collect::<Vec<_>>()
            .join(", ");
        defs.push(format!("  PRIMARY KEY ({keys})"));
    }
    for (index_name, columns, unique) in mysql_desc_indexes(desc) {
        let cols = columns
            .iter()
            .map(|col| mysql_quote_ident(col))
            .collect::<Vec<_>>()
            .join(", ");
        let prefix = if unique { "UNIQUE KEY" } else { "KEY" };
        defs.push(format!(
            "  {prefix} {} ({cols})",
            mysql_quote_ident(&index_name)
        ));
    }
    format!(
        "CREATE TABLE {} (\n{}\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        mysql_quote_ident(table_name),
        defs.join(",\n")
    )
}

async fn mysql_build_insert_undo_sql(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
    result: &Value,
) -> Option<String> {
    let affected = result
        .get("write")
        .and_then(|v| v.get("affected"))
        .and_then(|v| v.as_u64())?;
    if affected != 1 {
        return None;
    }
    let last_insert_id = result
        .get("write")
        .and_then(|v| v.get("last_insert_id"))
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let SqlPlan::Insert { table, rows, .. } = parse_sql_plan(sql, default_db).ok()? else {
        return None;
    };
    let eng = state.engine.read().await;
    let desc = eng.describe_table(&table.db, &table.table).ok()?;
    let pk = desc.get("primary_key").and_then(|v| v.as_array())?;
    if pk.len() != 1 {
        return None;
    }
    let pk_name = pk.first().and_then(|v| v.as_str())?;
    let auto_increment = desc
        .get("columns")
        .and_then(|v| v.as_array())
        .into_iter()
        .flatten()
        .any(|col| {
            col.get("name").and_then(|v| v.as_str()) == Some(pk_name)
                && col
                    .get("auto_increment")
                    .and_then(|v| v.as_bool())
                    .unwrap_or(false)
        });
    let pk_literal = if auto_increment && last_insert_id != 0 {
        last_insert_id.to_string()
    } else {
        let row = rows.first()?;
        mysql_render_default_lit(row.get(pk_name)?)
    };
    Some(format!(
        "DELETE FROM {}.{} WHERE {} = {} LIMIT 1",
        mysql_quote_ident(&table.db),
        mysql_quote_ident(&table.table),
        mysql_quote_ident(pk_name),
        pk_literal
    ))
}

async fn mysql_rollback_transaction(state: &AppState, undo_sql: &[String]) -> Result<(), RpcError> {
    for sql in undo_sql.iter().rev() {
        let params = SqlExecParams {
            sql: sql.clone(),
            explain: false,
            default_db: None,
            result_format: Some(ResultFormat::RowsJson),
            as_of_ms: None,
        };
        sql_exec(state, params).await?;
    }
    Ok(())
}

fn mysql_parse_select_where_parts(sql: &str) -> Option<(String, String, String)> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    if !trimmed.is_ascii() || !trimmed.to_ascii_lowercase().starts_with("select ") {
        return None;
    }
    let where_idx = find_keyword_top_level(trimmed, "where")?;
    let prefix = trimmed[..where_idx].trim_end().to_string();
    let tail = trimmed[where_idx + 5..].trim_start();
    let next_idx = ["group by", "having", "order by", "limit", "offset"]
        .iter()
        .filter_map(|k| find_keyword_top_level(tail, k))
        .min()
        .unwrap_or(tail.len());
    let where_clause = tail[..next_idx].trim().to_string();
    if where_clause.is_empty() {
        return None;
    }
    let suffix = tail[next_idx..].trim().to_string();
    Some((prefix, where_clause, suffix))
}

fn mysql_parse_in_subquery_where_clause(where_clause: &str) -> Option<(String, bool, String)> {
    let clause = trim_wrapping_parentheses(where_clause.trim());
    let (idx, negated, token_len) = if let Some(idx) = find_keyword_top_level(clause, "not in") {
        (idx, true, "not in".len())
    } else if let Some(idx) = find_keyword_top_level(clause, "in") {
        (idx, false, "in".len())
    } else {
        return None;
    };
    let lhs = clause[..idx].trim();
    if lhs.is_empty() {
        return None;
    }
    let rhs = clause[idx + token_len..].trim_start();
    if !rhs.starts_with('(') {
        return None;
    }
    let close_idx = find_matching_parenthesis(rhs, 0)?;
    if !rhs[close_idx + 1..].trim().is_empty() {
        return None;
    }
    let subquery_sql = rhs[1..close_idx].trim();
    if !subquery_sql.to_ascii_lowercase().starts_with("select ") {
        return None;
    }
    Some((lhs.to_string(), negated, subquery_sql.to_string()))
}

fn mysql_parse_exists_subquery_where_clause(where_clause: &str) -> Option<(bool, String)> {
    let clause = trim_wrapping_parentheses(where_clause.trim());
    let lower = clause.to_ascii_lowercase();
    let (negated, rest) = if lower.starts_with("exists") {
        (false, clause[6..].trim_start())
    } else if lower.starts_with("not exists") {
        (true, clause[10..].trim_start())
    } else {
        return None;
    };
    if !rest.starts_with('(') {
        return None;
    }
    let close_idx = find_matching_parenthesis(rest, 0)?;
    if !rest[close_idx + 1..].trim().is_empty() {
        return None;
    }
    let subquery_sql = rest[1..close_idx].trim();
    if !subquery_sql.to_ascii_lowercase().starts_with("select ") {
        return None;
    }
    Some((negated, subquery_sql.to_string()))
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum MySqlSubqueryCompatPredicate {
    In {
        lhs: String,
        negated: bool,
        subquery_sql: String,
    },
    Exists {
        negated: bool,
        subquery_sql: String,
    },
    Compare {
        other_sql: String,
        op: String,
        subquery_sql: String,
        subquery_on_left: bool,
    },
}

fn mysql_parse_scalar_subquery_select(raw: &str) -> Option<String> {
    let trimmed = trim_wrapping_parentheses(raw.trim());
    trimmed
        .to_ascii_lowercase()
        .starts_with("select ")
        .then_some(trimmed.to_string())
}

fn mysql_parse_scalar_subquery_compare_where_clause(
    where_clause: &str,
) -> Option<(String, String, String, bool)> {
    let clause = trim_wrapping_parentheses(where_clause.trim());
    let (left, op, right) = mysql_split_top_level_comparison(clause)?;
    match (
        mysql_parse_scalar_subquery_select(&left),
        mysql_parse_scalar_subquery_select(&right),
    ) {
        (Some(subquery_sql), None) => Some((right, op.to_string(), subquery_sql, true)),
        (None, Some(subquery_sql)) => Some((left, op.to_string(), subquery_sql, false)),
        _ => None,
    }
}

fn mysql_parse_subquery_compat_predicate(
    where_clause: &str,
) -> Option<MySqlSubqueryCompatPredicate> {
    if let Some((lhs, negated, subquery_sql)) = mysql_parse_in_subquery_where_clause(where_clause) {
        return Some(MySqlSubqueryCompatPredicate::In {
            lhs,
            negated,
            subquery_sql,
        });
    }
    if let Some((negated, subquery_sql)) = mysql_parse_exists_subquery_where_clause(where_clause) {
        return Some(MySqlSubqueryCompatPredicate::Exists {
            negated,
            subquery_sql,
        });
    }
    if let Some((other_sql, op, subquery_sql, subquery_on_left)) =
        mysql_parse_scalar_subquery_compare_where_clause(where_clause)
    {
        return Some(MySqlSubqueryCompatPredicate::Compare {
            other_sql,
            op,
            subquery_sql,
            subquery_on_left,
        });
    }
    None
}

fn mysql_render_base_table_ref(base: &BaseTableRef) -> String {
    let mut rendered = format!(
        "{}.{}",
        mysql_quote_ident(&base.db),
        mysql_quote_ident(&base.table)
    );
    if let Some(alias) = base.r#as.as_deref() {
        rendered.push_str(" AS ");
        rendered.push_str(&mysql_quote_ident(alias));
    }
    rendered
}

fn mysql_expr_is_inner_subquery_col(expr: &Expr, inner_base: &BaseTableRef) -> bool {
    match expr {
        Expr::Col {
            table: Some(table), ..
        } => mysql_stmt_table_matches_name(inner_base, table),
        Expr::Col { table: None, .. } => true,
        _ => false,
    }
}

fn mysql_expr_is_outer_correlated_col(expr: &Expr, inner_base: &BaseTableRef) -> bool {
    match expr {
        Expr::Col {
            table: Some(table), ..
        } => !mysql_stmt_table_matches_name(inner_base, table),
        _ => false,
    }
}

fn mysql_parse_correlated_subquery_equality_clause(
    clause: &str,
    inner_base: &BaseTableRef,
) -> Option<(String, String)> {
    let clause = trim_wrapping_parentheses(clause.trim());
    let bytes = clause.as_bytes();
    let mut i = 0usize;
    let mut depth = 0u32;
    let mut quote = 0u8;
    while i < bytes.len() {
        let b = bytes[i];
        if quote != 0 {
            if b == quote {
                if quote == b'\'' && i + 1 < bytes.len() && bytes[i + 1] == b'\'' {
                    i += 2;
                    continue;
                }
                quote = 0;
            }
            i += 1;
            continue;
        }
        match b {
            b'\'' | b'"' | b'`' => {
                quote = b;
                i += 1;
                continue;
            }
            b'(' => {
                depth += 1;
                i += 1;
                continue;
            }
            b')' => {
                depth = depth.saturating_sub(1);
                i += 1;
                continue;
            }
            _ => {}
        }
        if depth == 0 && b == b'=' {
            if matches!(
                i.checked_sub(1).and_then(|idx| bytes.get(idx)),
                Some(b'!') | Some(b'<') | Some(b'>')
            ) || bytes.get(i + 1) == Some(&b'=')
            {
                i += 1;
                continue;
            }
            let left_raw = clause[..i].trim();
            let right_raw = clause[i + 1..].trim();
            if left_raw.is_empty() || right_raw.is_empty() {
                return None;
            }
            let left_expr = parse_sql_scalar_expr(left_raw).ok()?;
            let right_expr = parse_sql_scalar_expr(right_raw).ok()?;
            let left_inner = mysql_expr_is_inner_subquery_col(&left_expr, inner_base);
            let right_inner = mysql_expr_is_inner_subquery_col(&right_expr, inner_base);
            let left_outer = mysql_expr_is_outer_correlated_col(&left_expr, inner_base);
            let right_outer = mysql_expr_is_outer_correlated_col(&right_expr, inner_base);
            if left_inner && right_outer {
                return Some((left_raw.to_string(), right_raw.to_string()));
            }
            if right_inner && left_outer {
                return Some((right_raw.to_string(), left_raw.to_string()));
            }
            return None;
        }
        i += 1;
    }
    None
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MySqlCorrelatedSubqueryRewrite {
    outer_exprs: Vec<String>,
    rewritten_subquery_sql: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MySqlSubqueryCompatWhereRewrite {
    sql: String,
    saw_subquery: bool,
}

fn mysql_parse_simple_select_projection_sql(sql: &str) -> Option<Vec<String>> {
    let trimmed = sql.trim();
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("select ") {
        return None;
    }
    let rest = trimmed[6..].trim_start();
    let from_idx = find_keyword_top_level(rest, "from")?;
    let projection = rest[..from_idx].trim();
    if projection.is_empty() {
        return None;
    }
    Some(split_csv_top_level(projection))
}

fn mysql_try_rewrite_correlated_subquery(
    subquery_sql: &str,
    default_db: Option<&str>,
    outer_value_expr_sql: Option<&str>,
) -> Option<MySqlCorrelatedSubqueryRewrite> {
    let SqlPlan::Select {
        from: Some(TableRef::Base(inner_base)),
        ..
    } = parse_sql_plan(subquery_sql, default_db).ok()?
    else {
        return None;
    };
    let (_, subquery_where, subquery_suffix) = mysql_parse_select_where_parts(subquery_sql)?;
    let mut remaining_parts = Vec::new();
    let mut correlations = Vec::<(String, String)>::new();
    for part in split_top_level_and(trim_wrapping_parentheses(&subquery_where)) {
        if let Some(parsed) = mysql_parse_correlated_subquery_equality_clause(&part, &inner_base) {
            correlations.push(parsed);
        } else {
            remaining_parts.push(part);
        }
    }
    if correlations.is_empty() {
        return None;
    }

    let mut inner_select_exprs = correlations
        .iter()
        .map(|(inner_expr_sql, _)| inner_expr_sql.clone())
        .collect::<Vec<_>>();
    let mut outer_exprs = correlations
        .iter()
        .map(|(_, outer_expr_sql)| outer_expr_sql.clone())
        .collect::<Vec<_>>();
    if let Some(outer_value_expr_sql) = outer_value_expr_sql {
        let projection_sqls = mysql_parse_simple_select_projection_sql(subquery_sql)?;
        if projection_sqls.len() != 1 {
            return None;
        }
        inner_select_exprs.push(projection_sqls[0].clone());
        outer_exprs.push(outer_value_expr_sql.trim().to_string());
    }

    let mut non_null_exprs = HashSet::new();
    for inner_expr_sql in &inner_select_exprs {
        let normalized = inner_expr_sql.trim().to_ascii_lowercase();
        if non_null_exprs.insert(normalized) {
            remaining_parts.push(format!("{inner_expr_sql} IS NOT NULL"));
        }
    }

    let mut rewritten = format!(
        "SELECT {} FROM {}",
        inner_select_exprs.join(", "),
        mysql_render_base_table_ref(&inner_base)
    );
    if !remaining_parts.is_empty() {
        rewritten.push_str(" WHERE ");
        rewritten.push_str(&remaining_parts.join(" AND "));
    }
    if !subquery_suffix.trim().is_empty() {
        rewritten.push(' ');
        rewritten.push_str(subquery_suffix.trim());
    }
    Some(MySqlCorrelatedSubqueryRewrite {
        outer_exprs,
        rewritten_subquery_sql: rewritten,
    })
}

fn mysql_rebuild_select_with_where(
    prefix: &str,
    where_clause: Option<&str>,
    suffix: &str,
) -> String {
    let mut sql = prefix.trim().to_string();
    if let Some(where_clause) = where_clause {
        sql.push_str(" WHERE ");
        sql.push_str(where_clause.trim());
    }
    if !suffix.trim().is_empty() {
        sql.push(' ');
        sql.push_str(suffix.trim());
    }
    sql
}

fn mysql_subquery_outcome_result_rows(
    outcome: &MySqlQueryOutcome,
) -> Result<MySqlTextRowsRef<'_>, RpcError> {
    match outcome {
        MySqlQueryOutcome::ResultSet { columns, rows } => Ok((columns, rows)),
        MySqlQueryOutcome::Ok { .. } => Err(RpcError::new(
            "not_supported",
            "subquery compatibility currently supports only SELECT subqueries",
        )),
    }
}

fn mysql_subquery_text_cell_to_lit(cell: Option<&str>) -> Lit {
    let Some(raw) = cell else {
        return Lit::Null;
    };
    if let Ok(value) = raw.parse::<i64>() {
        return Lit::I64 { v: value };
    }
    if let Ok(value) = raw.parse::<u64>() {
        return Lit::U64 { v: value };
    }
    if let Ok(value) = raw.parse::<f64>() {
        return Lit::F64 { v: value };
    }
    Lit::Str { v: raw.to_string() }
}

fn mysql_extract_subquery_first_column_lits(
    outcome: &MySqlQueryOutcome,
) -> Result<Vec<Lit>, RpcError> {
    let (columns, rows) = mysql_subquery_outcome_result_rows(outcome)?;
    if columns.len() != 1 {
        return Err(RpcError::new(
            "not_supported",
            "subquery compatibility currently requires a single projected column",
        ));
    }
    Ok(rows
        .iter()
        .map(|row| mysql_subquery_text_cell_to_lit(row.first().and_then(|value| value.as_deref())))
        .collect())
}

fn mysql_extract_scalar_subquery_lit(outcome: &MySqlQueryOutcome) -> Result<Lit, RpcError> {
    let lits = mysql_extract_subquery_first_column_lits(outcome)?;
    match lits.as_slice() {
        [] => Ok(Lit::Null),
        [lit] => Ok(lit.clone()),
        _ => Err(RpcError::new(
            "not_supported",
            "scalar subquery compatibility currently requires at most one row",
        )),
    }
}

fn mysql_extract_subquery_row_lits(outcome: &MySqlQueryOutcome) -> Result<Vec<Vec<Lit>>, RpcError> {
    let (columns, rows) = mysql_subquery_outcome_result_rows(outcome)?;
    if columns.is_empty() {
        return Err(RpcError::new(
            "not_supported",
            "subquery compatibility currently requires at least one projected column",
        ));
    }
    Ok(rows
        .iter()
        .map(|row| {
            row.iter()
                .map(|value| mysql_subquery_text_cell_to_lit(value.as_deref()))
                .collect::<Vec<_>>()
        })
        .collect())
}

fn mysql_render_correlated_subquery_match_clause(
    outer_exprs: &[String],
    rows: &[Vec<Lit>],
    negated: bool,
) -> Option<String> {
    if outer_exprs.is_empty() {
        return None;
    }
    let mut seen = HashSet::new();
    let mut clauses = Vec::new();
    for row in rows {
        if row.len() != outer_exprs.len() || row.iter().any(|lit| matches!(lit, Lit::Null)) {
            continue;
        }
        let parts = outer_exprs
            .iter()
            .zip(row.iter())
            .map(|(outer_expr_sql, lit)| {
                format!("{outer_expr_sql} = {}", mysql_render_default_lit(lit))
            })
            .collect::<Vec<_>>();
        let clause = if parts.len() == 1 {
            parts[0].clone()
        } else {
            format!("({})", parts.join(" AND "))
        };
        if seen.insert(clause.clone()) {
            clauses.push(clause);
        }
    }
    if clauses.is_empty() {
        return None;
    }
    let joined = if clauses.len() == 1 {
        clauses[0].clone()
    } else {
        format!("({})", clauses.join(" OR "))
    };
    if negated {
        Some(format!("NOT {joined}"))
    } else {
        Some(joined)
    }
}

async fn mysql_rewrite_subquery_compat_predicate(
    state: &AppState,
    predicate: MySqlSubqueryCompatPredicate,
    default_db: Option<&str>,
) -> Result<String, RpcError> {
    match predicate {
        MySqlSubqueryCompatPredicate::In {
            lhs,
            negated,
            subquery_sql,
        } => {
            if let Some(rewrite) =
                mysql_try_rewrite_correlated_subquery(&subquery_sql, default_db, Some(&lhs))
            {
                let subquery_result = mysql_exec_subquery_query_outcome(
                    state,
                    &rewrite.rewritten_subquery_sql,
                    default_db,
                )
                .await?;
                let rows = mysql_extract_subquery_row_lits(&subquery_result)?;
                return Ok(mysql_render_correlated_subquery_match_clause(
                    &rewrite.outer_exprs,
                    &rows,
                    negated,
                )
                .unwrap_or_else(|| {
                    if negated {
                        "1 = 1".to_string()
                    } else {
                        "1 = 0".to_string()
                    }
                }));
            }
            let subquery_result =
                mysql_exec_subquery_query_outcome(state, &subquery_sql, default_db).await?;
            let lits = mysql_extract_subquery_first_column_lits(&subquery_result)?;
            if lits.is_empty() {
                return Ok(if negated {
                    "1 = 1".to_string()
                } else {
                    "1 = 0".to_string()
                });
            }
            let values = lits
                .iter()
                .map(mysql_render_default_lit)
                .collect::<Vec<_>>()
                .join(", ");
            let op = if negated { "NOT IN" } else { "IN" };
            Ok(format!("{lhs} {op} ({values})"))
        }
        MySqlSubqueryCompatPredicate::Exists {
            negated,
            subquery_sql,
        } => {
            if let Some(rewrite) =
                mysql_try_rewrite_correlated_subquery(&subquery_sql, default_db, None)
            {
                let subquery_result = mysql_exec_subquery_query_outcome(
                    state,
                    &rewrite.rewritten_subquery_sql,
                    default_db,
                )
                .await?;
                let rows = mysql_extract_subquery_row_lits(&subquery_result)?;
                return Ok(mysql_render_correlated_subquery_match_clause(
                    &rewrite.outer_exprs,
                    &rows,
                    negated,
                )
                .unwrap_or_else(|| {
                    if negated {
                        "1 = 1".to_string()
                    } else {
                        "1 = 0".to_string()
                    }
                }));
            }
            let subquery_result =
                mysql_exec_subquery_query_outcome(state, &subquery_sql, default_db).await?;
            let (_, rows) = mysql_subquery_outcome_result_rows(&subquery_result)?;
            let exists = !rows.is_empty();
            Ok(if negated == exists {
                "1 = 0".to_string()
            } else {
                "1 = 1".to_string()
            })
        }
        MySqlSubqueryCompatPredicate::Compare {
            other_sql,
            op,
            subquery_sql,
            subquery_on_left,
        } => {
            let subquery_result =
                mysql_exec_subquery_query_outcome(state, &subquery_sql, default_db).await?;
            let lit = mysql_extract_scalar_subquery_lit(&subquery_result)?;
            let scalar_sql = mysql_render_default_lit(&lit);
            Ok(if subquery_on_left {
                format!("{scalar_sql} {op} {other_sql}")
            } else {
                format!("{other_sql} {op} {scalar_sql}")
            })
        }
    }
}

fn mysql_split_top_level_comparison(clause: &str) -> Option<(String, &'static str, String)> {
    let bytes = clause.as_bytes();
    let mut i = 0usize;
    let mut depth = 0u32;
    let mut quote = 0u8;
    while i < bytes.len() {
        let b = bytes[i];
        if quote != 0 {
            if b == quote {
                if quote == b'\'' && i + 1 < bytes.len() && bytes[i + 1] == b'\'' {
                    i += 2;
                    continue;
                }
                quote = 0;
            }
            i += 1;
            continue;
        }
        match b {
            b'\'' | b'"' | b'`' => {
                quote = b;
                i += 1;
                continue;
            }
            b'(' => {
                depth += 1;
                i += 1;
                continue;
            }
            b')' => {
                depth = depth.saturating_sub(1);
                i += 1;
                continue;
            }
            _ => {}
        }
        if depth == 0 {
            let op = if clause[i..].starts_with("<=") {
                Some("<=")
            } else if clause[i..].starts_with(">=") {
                Some(">=")
            } else if clause[i..].starts_with("!=") {
                Some("!=")
            } else if clause[i..].starts_with("<>") {
                Some("<>")
            } else if clause[i..].starts_with("=") {
                Some("=")
            } else if clause[i..].starts_with("<") {
                Some("<")
            } else if clause[i..].starts_with(">") {
                Some(">")
            } else {
                None
            };
            if let Some(op) = op {
                let left = clause[..i].trim();
                let right = clause[i + op.len()..].trim();
                if !left.is_empty() && !right.is_empty() {
                    return Some((left.to_string(), op, right.to_string()));
                }
            }
        }
        i += 1;
    }
    None
}

fn mysql_negate_leaf_predicate_sql(sql: &str) -> Option<String> {
    let trimmed = trim_wrapping_parentheses(sql.trim());
    if trimmed.is_empty() {
        return None;
    }
    let lower = trimmed.to_ascii_lowercase();
    if let Some(expr) = lower
        .strip_suffix(" is not null")
        .map(|_| trimmed[..trimmed.len() - " is not null".len()].trim())
    {
        return Some(format!("{expr} IS NULL"));
    }
    if let Some(expr) = lower
        .strip_suffix(" is null")
        .map(|_| trimmed[..trimmed.len() - " is null".len()].trim())
    {
        return Some(format!("{expr} IS NOT NULL"));
    }
    if let Some((left, op, right)) = mysql_split_top_level_comparison(trimmed) {
        let negated = match op {
            "=" => "<>",
            "!=" | "<>" => "=",
            "<" => ">=",
            "<=" => ">",
            ">" => "<=",
            ">=" => "<",
            _ => return None,
        };
        return Some(format!("{left} {negated} {right}"));
    }
    if let Some(idx) = find_keyword_top_level(trimmed, "not in") {
        let left = trimmed[..idx].trim();
        let right = trimmed[idx + "not in".len()..].trim();
        if !left.is_empty() && !right.is_empty() {
            return Some(format!("{left} IN {right}"));
        }
    }
    if let Some(idx) = find_keyword_top_level(trimmed, "in") {
        let left = trimmed[..idx].trim();
        let right = trimmed[idx + "in".len()..].trim();
        if !left.is_empty() && !right.is_empty() {
            return Some(format!("{left} NOT IN {right}"));
        }
    }
    if let Some(idx) = find_keyword_top_level(trimmed, "not like") {
        let left = trimmed[..idx].trim();
        let right = trimmed[idx + "not like".len()..].trim();
        if !left.is_empty() && !right.is_empty() {
            return Some(format!("{left} LIKE {right}"));
        }
    }
    if let Some(idx) = find_keyword_top_level(trimmed, "like") {
        let left = trimmed[..idx].trim();
        let right = trimmed[idx + "like".len()..].trim();
        if !left.is_empty() && !right.is_empty() {
            return Some(format!("{left} NOT LIKE {right}"));
        }
    }
    None
}

fn mysql_negate_rewritten_where_sql(sql: &str) -> Option<String> {
    let trimmed = trim_wrapping_parentheses(sql.trim());
    if trimmed.is_empty() {
        return None;
    }
    let or_parts = split_top_level_or(trimmed);
    if or_parts.len() > 1 {
        let rewritten = or_parts
            .into_iter()
            .map(|part| mysql_negate_rewritten_where_sql(&part).map(|sql| format!("({sql})")))
            .collect::<Option<Vec<_>>>()?;
        return Some(rewritten.join(" AND "));
    }
    let and_parts = split_top_level_and(trimmed);
    if and_parts.len() > 1 {
        let rewritten = and_parts
            .into_iter()
            .map(|part| mysql_negate_rewritten_where_sql(&part).map(|sql| format!("({sql})")))
            .collect::<Option<Vec<_>>>()?;
        return Some(rewritten.join(" OR "));
    }
    mysql_negate_leaf_predicate_sql(trimmed)
}

fn mysql_rewrite_subquery_compat_where_clause<'a>(
    state: &'a AppState,
    where_clause: &'a str,
    default_db: Option<&'a str>,
) -> Pin<
    Box<dyn Future<Output = Result<Option<MySqlSubqueryCompatWhereRewrite>, RpcError>> + Send + 'a>,
> {
    Box::pin(async move {
        let trimmed = trim_wrapping_parentheses(where_clause.trim());
        if trimmed.is_empty() {
            return Ok(None);
        }

        let or_parts = split_top_level_or(trimmed);
        if or_parts.len() > 1 {
            let mut rewritten = Vec::with_capacity(or_parts.len());
            let mut saw_subquery = false;
            for part in or_parts {
                let Some(result) =
                    mysql_rewrite_subquery_compat_where_clause(state, &part, default_db).await?
                else {
                    return Ok(None);
                };
                saw_subquery |= result.saw_subquery;
                rewritten.push(format!("({})", result.sql));
            }
            return Ok(Some(MySqlSubqueryCompatWhereRewrite {
                sql: rewritten.join(" OR "),
                saw_subquery,
            }));
        }

        let and_parts = split_top_level_and(trimmed);
        if and_parts.len() > 1 {
            let mut rewritten = Vec::with_capacity(and_parts.len());
            let mut saw_subquery = false;
            for part in and_parts {
                let Some(result) =
                    mysql_rewrite_subquery_compat_where_clause(state, &part, default_db).await?
                else {
                    return Ok(None);
                };
                saw_subquery |= result.saw_subquery;
                rewritten.push(format!("({})", result.sql));
            }
            return Ok(Some(MySqlSubqueryCompatWhereRewrite {
                sql: rewritten.join(" AND "),
                saw_subquery,
            }));
        }

        if trimmed
            .get(..3)
            .map(|prefix| prefix.eq_ignore_ascii_case("not"))
            .unwrap_or(false)
            && trimmed[3..]
                .chars()
                .next()
                .map(|ch| ch.is_ascii_whitespace() || ch == '(')
                .unwrap_or(false)
        {
            let inner = trimmed[3..].trim_start();
            let Some(result) =
                mysql_rewrite_subquery_compat_where_clause(state, inner, default_db).await?
            else {
                return Ok(None);
            };
            let Some(negated_sql) = mysql_negate_rewritten_where_sql(&result.sql) else {
                return Ok(None);
            };
            return Ok(Some(MySqlSubqueryCompatWhereRewrite {
                sql: negated_sql,
                saw_subquery: result.saw_subquery,
            }));
        }

        if let Some(predicate) = mysql_parse_subquery_compat_predicate(trimmed) {
            return Ok(Some(MySqlSubqueryCompatWhereRewrite {
                sql: mysql_rewrite_subquery_compat_predicate(state, predicate, default_db).await?,
                saw_subquery: true,
            }));
        }

        Ok(Some(MySqlSubqueryCompatWhereRewrite {
            sql: trimmed.to_string(),
            saw_subquery: false,
        }))
    })
}

fn mysql_query_outcome_from_sql_exec_result(
    result: &Value,
    sql: Option<&str>,
    default_db: Option<&str>,
) -> Result<MySqlQueryOutcome, RpcError> {
    let statement = result
        .get("statement")
        .and_then(|v| v.as_str())
        .unwrap_or_default();
    if statement != "select" {
        return Err(RpcError::new(
            "not_supported",
            "subquery compatibility currently supports only SELECT outer queries",
        ));
    }
    let (columns, rows) = mysql_extract_result_data_for_sql(result, sql, default_db)
        .map_err(|err| RpcError::new("internal", err))?;
    Ok(MySqlQueryOutcome::ResultSet { columns, rows })
}

async fn mysql_exec_subquery_query_outcome(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Result<MySqlQueryOutcome, RpcError> {
    if let Some(outcome) = mysql_try_compat_query_outcome(state, sql, default_db).await? {
        return Ok(outcome);
    }
    let result = sql_exec(
        state,
        SqlExecParams {
            sql: sql.to_string(),
            explain: false,
            default_db: default_db.map(|db| db.to_string()),
            result_format: Some(ResultFormat::RowsJson),
            as_of_ms: None,
        },
    )
    .await?;
    mysql_query_outcome_from_sql_exec_result(&result, Some(sql), default_db)
}

/// Handle SELECT queries that contain `(SELECT ...)` subqueries in the projection.
/// Supports both non-correlated (`SELECT (SELECT COUNT(*) FROM t) AS total`)
/// and correlated (`SELECT name, (SELECT COUNT(*) FROM orders WHERE user_id = users.id) ...`)
/// projection subqueries.
async fn mysql_try_projection_subquery(
    state: &AppState,
    sql: &str,
    session: &mut MySqlSessionState,
) -> Result<Option<MySqlQueryOutcome>, MySqlWireError> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("select ") {
        return Ok(None);
    }
    // Must contain a parenthesized SELECT in the projection area
    if !lower.contains("(select ") {
        return Ok(None);
    }

    let rest = &trimmed[7..]; // after "SELECT "
    let from_pos = match find_keyword_top_level(rest, "from") {
        Some(pos) => pos,
        None => {
            // No FROM — standalone projection subquery like `SELECT (SELECT COUNT(*) FROM t) AS a`
            let items = split_csv_top_level(rest.trim().trim_end_matches(';').trim());
            let mut columns = Vec::new();
            let mut row = Vec::new();
            let mut saw_subquery = false;
            for (idx, item) in items.iter().enumerate() {
                let (expr_raw, alias) = mysql_parse_projection_expr_alias(item);
                if let Some(sub_sql) = mysql_parse_scalar_subquery_select(&expr_raw) {
                    saw_subquery = true;
                    let col_name = alias.unwrap_or_else(|| {
                        format!("({})", sub_sql.chars().take(40).collect::<String>())
                    });
                    let sub_result = mysql_exec_subquery_query_outcome(
                        state,
                        &sub_sql,
                        session.default_db.as_deref(),
                    )
                    .await
                    .map_err(|e| mysql_error_from_rpc(&e))?;
                    let scalar = mysql_extract_scalar_subquery_lit(&sub_result)
                        .map_err(|e| mysql_error_from_rpc(&e))?;
                    columns.push(col_name);
                    row.push(mysql_literal_text_from_lit(&scalar));
                } else {
                    columns.push(alias.unwrap_or_else(|| format!("expr{}", idx + 1)));
                    // Try to parse as a literal
                    let text = expr_raw.trim().trim_matches('\'');
                    row.push(Some(text.to_string()));
                }
            }
            if !saw_subquery {
                return Ok(None);
            }
            return Ok(Some(MySqlQueryOutcome::ResultSet {
                columns,
                rows: vec![row],
            }));
        }
    };

    let projection_str = rest[..from_pos].trim();
    let from_tail = rest[from_pos..].trim();

    // Check if any projection item contains a subquery
    let proj_items = split_csv_top_level(projection_str);
    let mut subquery_indices = Vec::new();
    for (idx, item) in proj_items.iter().enumerate() {
        let (expr_raw, _) = mysql_parse_projection_expr_alias(item);
        if mysql_parse_scalar_subquery_select(&expr_raw).is_some() {
            subquery_indices.push(idx);
        }
    }
    if subquery_indices.is_empty() {
        // No pure scalar-subquery projection items, but check for embedded subqueries
        // in arithmetic expressions like `salary - (SELECT AVG(salary) FROM users)`
        let mut has_embedded = false;
        for item in &proj_items {
            let (expr_raw, _) = mysql_parse_projection_expr_alias(item);
            if expr_raw.to_ascii_lowercase().contains("(select ") {
                has_embedded = true;
                break;
            }
        }
        if !has_embedded {
            return Ok(None);
        }
        // Pre-evaluate embedded subqueries and replace with literal values
        let mut new_proj_items = Vec::new();
        for item in &proj_items {
            let mut expr_str = item.clone();
            loop {
                let lower = expr_str.to_ascii_lowercase();
                let Some(sel_pos) = lower.find("(select ") else {
                    break;
                };
                let close = find_matching_parenthesis(&expr_str, sel_pos);
                let Some(close_pos) = close else { break };
                let sub_sql = expr_str[sel_pos + 1..close_pos].trim();
                let sub_result = mysql_exec_subquery_query_outcome(
                    state,
                    sub_sql,
                    session.default_db.as_deref(),
                )
                .await
                .map_err(|e| mysql_error_from_rpc(&e))?;
                let scalar = mysql_extract_scalar_subquery_lit(&sub_result)
                    .map_err(|e| mysql_error_from_rpc(&e))?;
                let replacement = match &scalar {
                    Lit::Null => "NULL".to_string(),
                    Lit::I64 { v } => v.to_string(),
                    Lit::U64 { v } => v.to_string(),
                    Lit::F64 { v } => v.to_string(),
                    Lit::Dec { v } | Lit::Str { v } => {
                        if v.parse::<f64>().is_ok() {
                            v.clone()
                        } else {
                            format!("'{}'", v.replace('\'', "''"))
                        }
                    }
                    Lit::Bool { v } => if *v { "1" } else { "0" }.to_string(),
                    _ => "NULL".to_string(),
                };
                expr_str = format!(
                    "{}{}{}",
                    &expr_str[..sel_pos],
                    replacement,
                    &expr_str[close_pos + 1..]
                );
            }
            new_proj_items.push(expr_str);
        }
        let rewritten_sql = format!("SELECT {} {}", new_proj_items.join(", "), from_tail);
        return Box::pin(mysql_execute_sql(state, &rewritten_sql, session))
            .await
            .map(Some);
    }

    // Extract outer table info from FROM clause for correlated ref detection
    let from_table_info = mysql_extract_from_table_info(from_tail);

    // Collect subquery specs and detect correlated outer refs
    struct ProjSubquery {
        insert_pos: usize,
        alias: String,
        sub_sql: String,
        outer_refs: Vec<String>, // e.g. ["users.id"]
    }
    let mut subquery_specs = Vec::new();
    let mut outer_proj_items = Vec::new();
    let mut extra_cols: Vec<String> = Vec::new();
    let mut non_sub_count = 0usize;

    for (idx, item) in proj_items.iter().enumerate() {
        let (expr_raw, alias) = mysql_parse_projection_expr_alias(item);
        if subquery_indices.contains(&idx) {
            let sub_sql = mysql_parse_scalar_subquery_select(&expr_raw).unwrap();
            let col_name = alias.unwrap_or_else(|| format!("subq{}", subquery_specs.len() + 1));
            let outer_refs = mysql_find_outer_refs_in_subquery(&sub_sql, &from_table_info);
            // Add referenced columns to the outer projection if not already present
            for oref in &outer_refs {
                if let Some((_tbl, col)) = oref.split_once('.') {
                    let col_lower = col.to_ascii_lowercase();
                    let already = outer_proj_items.iter().any(|p: &String| {
                        let (pe, _) = mysql_parse_projection_expr_alias(p);
                        let pe_l = pe.to_ascii_lowercase();
                        pe_l == col_lower || pe_l.ends_with(&format!(".{}", col_lower))
                    }) || extra_cols.iter().any(|e| e.eq_ignore_ascii_case(oref));
                    if !already {
                        extra_cols.push(oref.clone());
                    }
                }
            }
            subquery_specs.push(ProjSubquery {
                insert_pos: non_sub_count,
                alias: col_name,
                sub_sql,
                outer_refs,
            });
        } else {
            outer_proj_items.push(item.clone());
            non_sub_count += 1;
        }
    }

    // Add extra columns needed for correlated ref lookup
    for ec in &extra_cols {
        outer_proj_items.push(ec.clone());
    }

    if outer_proj_items.is_empty() {
        outer_proj_items.push("1 AS _dummy".to_string());
    }

    let outer_sql = format!("SELECT {} {}", outer_proj_items.join(", "), from_tail);

    // Execute the outer query
    let outer_result = Box::pin(mysql_execute_sql(state, &outer_sql, session)).await?;
    let (mut columns, mut rows) = match outer_result {
        MySqlQueryOutcome::ResultSet { columns, rows } => (columns, rows),
        _ => return Ok(None),
    };

    // Remove _dummy column if we added one
    if outer_proj_items.first().map(|s| s.as_str()) == Some("1 AS _dummy") {
        columns.clear();
        for row in &mut rows {
            row.clear();
        }
    }

    // For each subquery spec, compute values and insert into the result
    for spec in &subquery_specs {
        if spec.outer_refs.is_empty() {
            // Non-correlated: execute once
            let sub_result = mysql_exec_subquery_query_outcome(
                state,
                &spec.sub_sql,
                session.default_db.as_deref(),
            )
            .await
            .map_err(|e| mysql_error_from_rpc(&e))?;
            let scalar = mysql_extract_scalar_subquery_lit(&sub_result)
                .map_err(|e| mysql_error_from_rpc(&e))?;
            let text = mysql_literal_text_from_lit(&scalar);
            columns.insert(spec.insert_pos, spec.alias.clone());
            for row in rows.iter_mut() {
                row.insert(spec.insert_pos, text.clone());
            }
        } else {
            // Correlated: execute per row with substituted values
            let mut sub_values = Vec::with_capacity(rows.len());
            for row in &rows {
                let mut subquery = spec.sub_sql.clone();
                for oref in &spec.outer_refs {
                    // Find column index in the result set
                    let col_idx = columns.iter().position(|c| {
                        c.eq_ignore_ascii_case(oref)
                            || oref
                                .split_once('.')
                                .map(|(_, col)| c.eq_ignore_ascii_case(col))
                                .unwrap_or(false)
                    });
                    let val = col_idx.and_then(|i| row.get(i)).and_then(|v| v.as_deref());
                    let replacement = match val {
                        None | Some("NULL") => "NULL".to_string(),
                        Some(v) if v.parse::<f64>().is_ok() => v.to_string(),
                        Some(v) => format!("'{}'", v.replace('\'', "''")),
                    };
                    subquery =
                        mysql_replace_case_insensitive_outer_ref(&subquery, oref, &replacement);
                }
                let sub_result = mysql_exec_subquery_query_outcome(
                    state,
                    &subquery,
                    session.default_db.as_deref(),
                )
                .await
                .map_err(|e| mysql_error_from_rpc(&e))?;
                let scalar = mysql_extract_scalar_subquery_lit(&sub_result)
                    .map_err(|e| mysql_error_from_rpc(&e))?;
                sub_values.push(mysql_literal_text_from_lit(&scalar));
            }
            columns.insert(spec.insert_pos, spec.alias.clone());
            for (ri, row) in rows.iter_mut().enumerate() {
                row.insert(spec.insert_pos, sub_values[ri].clone());
            }
        }
    }

    // Strip extra columns that were added only for correlated ref lookup
    if !extra_cols.is_empty() {
        let final_col_count = columns.len() - extra_cols.len();
        columns.truncate(final_col_count);
        for row in rows.iter_mut() {
            row.truncate(final_col_count);
        }
    }

    Ok(Some(MySqlQueryOutcome::ResultSet { columns, rows }))
}

/// Extract table name and alias from a FROM clause like `FROM users` or `FROM users u`.
fn mysql_extract_from_table_info(from_tail: &str) -> Vec<(String, Option<String>)> {
    let lower = from_tail.to_ascii_lowercase();
    let rest = lower.strip_prefix("from").unwrap_or(&lower).trim();
    let end = [
        "where",
        "order by",
        "group by",
        "limit",
        "having",
        "join",
        "left join",
        "right join",
        "inner join",
        "cross join",
        "natural join",
    ]
    .iter()
    .filter_map(|kw| find_keyword_top_level(rest, kw))
    .min()
    .unwrap_or(rest.len());
    let orig_rest = from_tail
        .strip_prefix("from")
        .or_else(|| from_tail.strip_prefix("FROM"))
        .or_else(|| from_tail.strip_prefix("From"))
        .unwrap_or(from_tail)
        .trim();
    let orig_table_part = orig_rest[..end.min(orig_rest.len())]
        .trim()
        .trim_end_matches(';');

    let tables = split_csv_top_level(orig_table_part);
    let mut result = Vec::new();
    for table_str in &tables {
        let parts: Vec<&str> = table_str.split_ascii_whitespace().collect();
        match parts.as_slice() {
            [table] => result.push((clean_sql_ident(table), None)),
            [table, alias] if !alias.eq_ignore_ascii_case("as") => {
                result.push((clean_sql_ident(table), Some(clean_sql_ident(alias))))
            }
            [table, _, alias] => {
                result.push((clean_sql_ident(table), Some(clean_sql_ident(alias))))
            }
            _ => {}
        }
    }
    result
}

/// Find references to outer table columns in a subquery.
/// E.g. for `WHERE user_id = users.id` with outer table `users`,
/// returns `["users.id"]`.
fn mysql_find_outer_refs_in_subquery(
    sub_sql: &str,
    from_tables: &[(String, Option<String>)],
) -> Vec<String> {
    let sub_lower = sub_sql.to_ascii_lowercase();
    let mut refs = Vec::new();

    // Parse the subquery's own FROM clause to know its own tables
    let sub_from_pos = find_keyword_top_level(&sub_lower, "from");
    let sub_tables: Vec<String> = if let Some(pos) = sub_from_pos {
        let sub_rest = sub_lower[pos + 4..].trim();
        let end = ["where", "order by", "group by", "limit", "having", "join"]
            .iter()
            .filter_map(|kw| find_keyword_top_level(sub_rest, kw))
            .min()
            .unwrap_or(sub_rest.len());
        let table_part = sub_rest[..end].trim().trim_end_matches(';');
        split_csv_top_level(table_part)
            .iter()
            .flat_map(|t| {
                let parts: Vec<&str> = t.split_ascii_whitespace().collect();
                match parts.as_slice() {
                    [table] => vec![clean_sql_ident(table)],
                    [table, alias] if !alias.eq_ignore_ascii_case("as") => {
                        vec![clean_sql_ident(table), clean_sql_ident(alias)]
                    }
                    [table, _, alias] => {
                        vec![clean_sql_ident(table), clean_sql_ident(alias)]
                    }
                    _ => vec![],
                }
            })
            .collect()
    } else {
        Vec::new()
    };

    // Look for `table.column` patterns where `table` matches an outer table
    // but NOT a subquery-internal table
    for (table_name, alias) in from_tables {
        let names_to_check: Vec<&str> = {
            let mut v = vec![table_name.as_str()];
            if let Some(a) = alias {
                v.push(a.as_str());
            }
            v
        };
        for outer_name in &names_to_check {
            let prefix = format!("{}.", outer_name.to_ascii_lowercase());
            if sub_tables
                .iter()
                .any(|st| st.eq_ignore_ascii_case(outer_name))
            {
                continue;
            }
            let mut search_from = 0;
            while let Some(pos) = sub_lower[search_from..].find(&prefix) {
                let abs_pos = search_from + pos;
                let after = &sub_sql[abs_pos + prefix.len()..];
                let col_end = after
                    .find(|c: char| !c.is_ascii_alphanumeric() && c != '_' && c != '`')
                    .unwrap_or(after.len());
                if col_end > 0 {
                    let col = clean_sql_ident(&after[..col_end]);
                    let full_ref = format!("{}.{}", outer_name, col);
                    if !refs
                        .iter()
                        .any(|r: &String| r.eq_ignore_ascii_case(&full_ref))
                    {
                        refs.push(full_ref);
                    }
                }
                search_from = abs_pos + prefix.len() + col_end;
            }
        }
    }
    refs
}

fn mysql_literal_text_from_lit(lit: &Lit) -> Option<String> {
    match lit {
        Lit::Null => None,
        Lit::Bool { v } => Some(if *v { "1".to_string() } else { "0".to_string() }),
        Lit::I64 { v } => Some(v.to_string()),
        Lit::U64 { v } => Some(v.to_string()),
        Lit::F64 { v } => Some(v.to_string()),
        Lit::Dec { v } | Lit::Str { v } => Some(v.clone()),
        Lit::Date { iso } | Lit::Time { iso } | Lit::Datetime { iso } => Some(iso.clone()),
        Lit::Uuid { v } => Some(v.clone()),
        Lit::Bytes { .. } | Lit::Json { .. } | Lit::Embedding { .. } => None,
    }
}

fn mysql_replace_case_insensitive_outer_ref(
    sql: &str,
    outer_ref: &str,
    replacement: &str,
) -> String {
    let needle = outer_ref.trim();
    if needle.is_empty() {
        return sql.to_string();
    }

    let bytes = sql.as_bytes();
    let lower = sql.to_ascii_lowercase().into_bytes();
    let needle_lower = needle.to_ascii_lowercase().into_bytes();
    let mut out = String::with_capacity(sql.len());
    let mut quote = 0u8;
    let mut i = 0usize;
    let mut last_emit = 0usize;

    while i < bytes.len() {
        let b = bytes[i];
        if quote != 0 {
            if b == quote {
                if mysql_is_doubled_single_quote(bytes, i, quote) {
                    i += 2;
                    continue;
                }
                if quote != b'`' && mysql_is_backslash_escaped(bytes, i) {
                    i += 1;
                    continue;
                }
                quote = 0;
            }
            i += 1;
            continue;
        }

        match b {
            b'\'' | b'"' | b'`' => {
                quote = b;
                i += 1;
                continue;
            }
            _ => {}
        }

        if i + needle_lower.len() <= bytes.len()
            && &lower[i..i + needle_lower.len()] == needle_lower.as_slice()
            && (i == 0 || !is_sql_ident_char(lower[i - 1]))
            && (i + needle_lower.len() == bytes.len()
                || !is_sql_ident_char(lower[i + needle_lower.len()]))
        {
            out.push_str(&sql[last_emit..i]);
            out.push_str(replacement);
            i += needle_lower.len();
            last_emit = i;
            continue;
        }

        i += 1;
    }

    if last_emit == 0 {
        return sql.to_string();
    }

    out.push_str(&sql[last_emit..]);
    out
}

async fn mysql_try_select_subquery_compat_outcome(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Result<Option<MySqlQueryOutcome>, RpcError> {
    let Some((prefix, where_clause, suffix)) = mysql_parse_select_where_parts(sql) else {
        return Ok(None);
    };
    let Some(rewrite) =
        mysql_rewrite_subquery_compat_where_clause(state, &where_clause, default_db).await?
    else {
        return Ok(None);
    };
    if !rewrite.saw_subquery {
        return Ok(None);
    }

    let rewritten_sql = mysql_rebuild_select_with_where(&prefix, Some(&rewrite.sql), &suffix);
    let rewritten_result = sql_exec(
        state,
        SqlExecParams {
            sql: rewritten_sql.clone(),
            explain: false,
            default_db: default_db.map(|db| db.to_string()),
            result_format: Some(ResultFormat::RowsJson),
            as_of_ms: None,
        },
    )
    .await?;
    mysql_query_outcome_from_sql_exec_result(&rewritten_result, Some(&rewritten_sql), default_db)
        .map(Some)
}

async fn mysql_try_compat_query_outcome(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Result<Option<MySqlQueryOutcome>, RpcError> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    if trimmed.is_empty() {
        return Ok(None);
    }
    let lower = trimmed.to_ascii_lowercase();

    // SHOW CREATE DATABASE / SHOW CREATE SCHEMA
    if lower.starts_with("show create database ") || lower.starts_with("show create schema ") {
        let prefix_len = if lower.starts_with("show create database ") {
            "show create database ".len()
        } else {
            "show create schema ".len()
        };
        let db_name = trimmed[prefix_len..]
            .trim()
            .trim_matches('`')
            .trim_matches('"')
            .to_string();
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec!["Database".to_string(), "Create Database".to_string()],
            rows: vec![vec![
                Some(db_name.clone()),
                Some(format!(
                    "CREATE DATABASE `{}` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci */",
                    db_name
                )),
            ]],
        }));
    }

    if let Some(result) =
        mysql_try_multi_grouped_aggregate_query_outcome(state, trimmed, default_db).await?
    {
        return Ok(Some(result));
    }

    if let Some(result) =
        mysql_try_grouped_aggregate_query_outcome(state, trimmed, default_db).await?
    {
        return Ok(Some(result));
    }

    if let Some(result) =
        mysql_try_multi_aggregate_query_outcome(state, trimmed, default_db).await?
    {
        return Ok(Some(result));
    }

    if let Some(result) =
        mysql_try_simple_aggregate_query_outcome(state, trimmed, default_db).await?
    {
        return Ok(Some(result));
    }

    if let Some(result) =
        mysql_try_info_schema_table_storage_query_outcome(state, trimmed, default_db).await?
    {
        return Ok(Some(result));
    }

    if let Some(result) =
        mysql_try_select_subquery_compat_outcome(state, trimmed, default_db).await?
    {
        return Ok(Some(result));
    }

    if let Some(filter) = mysql_parse_show_character_set_query(trimmed) {
        let mut rows = mysql_known_character_sets()
            .iter()
            .copied()
            .filter(|(charset, _, _, _)| {
                filter
                    .as_deref()
                    .map(|pattern| mysql_like_matches(charset, pattern))
                    .unwrap_or(true)
            })
            .map(|(charset, description, default_collation, maxlen)| {
                vec![
                    Some(charset.to_string()),
                    Some(description.to_string()),
                    Some(default_collation.to_string()),
                    Some(maxlen.to_string()),
                ]
            })
            .collect::<Vec<_>>();
        rows.sort_unstable();
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec![
                "Charset".to_string(),
                "Description".to_string(),
                "Default collation".to_string(),
                "Maxlen".to_string(),
            ],
            rows,
        }));
    }

    if let Some(filter) = mysql_parse_show_collation_query(trimmed) {
        let mut rows = mysql_known_collations()
            .iter()
            .copied()
            .filter(|(collation, charset, _, _, _)| match &filter {
                MySqlShowCollationFilter::All => true,
                MySqlShowCollationFilter::CollationLike(pattern) => {
                    mysql_like_matches(collation, pattern)
                }
                MySqlShowCollationFilter::CharsetLike(pattern) => {
                    mysql_like_matches(charset, pattern)
                }
            })
            .map(|(collation, charset, id, is_default, sortlen)| {
                vec![
                    Some(collation.to_string()),
                    Some(charset.to_string()),
                    Some(id.to_string()),
                    Some(if is_default { "Yes" } else { "" }.to_string()),
                    Some("Yes".to_string()),
                    Some(sortlen.to_string()),
                ]
            })
            .collect::<Vec<_>>();
        rows.sort_unstable();
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec![
                "Collation".to_string(),
                "Charset".to_string(),
                "Id".to_string(),
                "Default".to_string(),
                "Compiled".to_string(),
                "Sortlen".to_string(),
            ],
            rows,
        }));
    }

    if let Some(filter) = mysql_parse_show_named_value_query(trimmed, "variables") {
        let mut names = mysql_known_session_vars()
            .iter()
            .copied()
            .filter(|name| {
                filter
                    .as_deref()
                    .map(|pattern| mysql_like_matches(name, pattern))
                    .unwrap_or(true)
            })
            .collect::<Vec<_>>();
        names.sort_unstable();
        let rows = names
            .into_iter()
            .filter_map(|name| {
                mysql_session_var_value(name)
                    .and_then(|lit| mysql_literal_text(&lit))
                    .map(|value| vec![Some(name.to_string()), Some(value)])
            })
            .collect::<Vec<_>>();
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec!["Variable_name".to_string(), "Value".to_string()],
            rows,
        }));
    }

    if let Some(filter) = mysql_parse_show_named_value_query(trimmed, "status") {
        let mut entries = mysql_known_status_vars()
            .iter()
            .copied()
            .filter(|(name, _)| {
                filter
                    .as_deref()
                    .map(|pattern| mysql_like_matches(name, pattern))
                    .unwrap_or(true)
            })
            .collect::<Vec<_>>();
        entries.sort_unstable_by(|left, right| left.0.cmp(right.0));
        let rows = entries
            .into_iter()
            .map(|(name, value)| vec![Some(name.to_string()), Some(value.to_string())])
            .collect::<Vec<_>>();
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec!["Variable_name".to_string(), "Value".to_string()],
            rows,
        }));
    }

    if lower == "show engines" {
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec![
                "Engine".to_string(),
                "Support".to_string(),
                "Comment".to_string(),
                "Transactions".to_string(),
                "XA".to_string(),
                "Savepoints".to_string(),
            ],
            rows: vec![
                vec![
                    Some("InnoDB".to_string()),
                    Some("DEFAULT".to_string()),
                    Some("SkeinDB compatibility engine".to_string()),
                    Some("YES".to_string()),
                    Some("NO".to_string()),
                    Some("NO".to_string()),
                ],
                vec![
                    Some("SKEIN".to_string()),
                    Some("YES".to_string()),
                    Some("Native SkeinDB execution".to_string()),
                    Some("YES".to_string()),
                    Some("NO".to_string()),
                    Some("NO".to_string()),
                ],
            ],
        }));
    }

    if lower == "show grants" {
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec!["Grants for root@%".to_string()],
            rows: vec![vec![Some(
                "GRANT ALL PRIVILEGES ON *.* TO 'root'@'%'".to_string(),
            )]],
        }));
    }

    if lower == "show plugins" {
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec![
                "Name".to_string(),
                "Status".to_string(),
                "Type".to_string(),
                "Library".to_string(),
                "License".to_string(),
            ],
            rows: vec![],
        }));
    }

    if lower == "show profiles" {
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec![
                "Query_ID".to_string(),
                "Duration".to_string(),
                "Query".to_string(),
            ],
            rows: vec![],
        }));
    }

    if lower.starts_with("show full tables") || lower.starts_with("show tables") {
        let full = lower.starts_with("show full tables");
        let prefix_len = if full { 16 } else { 11 };
        let tail = trimmed[prefix_len..].trim();
        let like_idx = find_keyword_top_level(tail, "like");
        let where_idx = find_keyword_top_level(tail, "where");
        let stop_idx = [like_idx, where_idx]
            .into_iter()
            .flatten()
            .min()
            .unwrap_or(tail.len());
        let scope_sql = tail[..stop_idx].trim();
        let like_pattern =
            like_idx.and_then(|idx| parse_sql_string_literal(tail[idx + 4..].trim()));
        let where_sql = where_idx.map(|idx| tail[idx + 5..].trim());

        let db = if scope_sql.is_empty() {
            default_db.map(clean_sql_ident).filter(|db| !db.is_empty())
        } else {
            let scope_lower = scope_sql.to_ascii_lowercase();
            if scope_lower.starts_with("from ") || scope_lower.starts_with("in ") {
                let name = clean_sql_ident(scope_sql[4..].trim());
                (!name.is_empty()).then_some(name)
            } else {
                return Err(RpcError::new(
                    "not_supported",
                    "SHOW TABLES supports only optional FROM/IN and LIKE clauses",
                ));
            }
        }
        .ok_or_else(|| {
            RpcError::new(
                "invalid_request",
                "SHOW TABLES requires FROM <db> or a selected database",
            )
        })?;

        if let Some(where_sql) = where_sql {
            let normalized = where_sql
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" ")
                .to_ascii_lowercase();
            let accepted = normalized == "table_type = 'base table'"
                || normalized == "table_type='base table'";
            if !full || !accepted {
                return Err(RpcError::new(
                    "not_supported",
                    "SHOW FULL TABLES WHERE currently supports only Table_type = 'BASE TABLE'",
                ));
            }
        }

        let eng = state.engine.read().await;
        let tables = eng.list_tables(&db).map_err(to_rpc_error)?;
        let rows = tables
            .into_iter()
            .filter(|table| {
                like_pattern
                    .as_deref()
                    .map(|pattern| mysql_like_matches(table, pattern))
                    .unwrap_or(true)
            })
            .map(|table| {
                if full {
                    vec![Some(table), Some("BASE TABLE".to_string())]
                } else {
                    vec![Some(table)]
                }
            })
            .collect();
        let mut columns = vec![format!("Tables_in_{db}")];
        if full {
            columns.push("Table_type".to_string());
        }
        return Ok(Some(MySqlQueryOutcome::ResultSet { columns, rows }));
    }

    if lower.starts_with("show table status") {
        let tail = trimmed[17..].trim();
        let like_idx = find_keyword_top_level(tail, "like");
        let scope_sql = like_idx.map(|idx| tail[..idx].trim()).unwrap_or(tail);
        let like_pattern =
            like_idx.and_then(|idx| parse_sql_string_literal(tail[idx + 4..].trim()));

        let db = if scope_sql.is_empty() {
            default_db.map(clean_sql_ident).filter(|db| !db.is_empty())
        } else {
            let scope_lower = scope_sql.to_ascii_lowercase();
            if scope_lower.starts_with("from ") || scope_lower.starts_with("in ") {
                let name = clean_sql_ident(scope_sql[4..].trim());
                (!name.is_empty()).then_some(name)
            } else {
                return Err(RpcError::new(
                    "not_supported",
                    "SHOW TABLE STATUS supports only optional FROM/IN and LIKE clauses",
                ));
            }
        }
        .ok_or_else(|| {
            RpcError::new(
                "invalid_request",
                "SHOW TABLE STATUS requires FROM <db> or a selected database",
            )
        })?;

        let eng = state.engine.read().await;
        let tables = eng.list_tables(&db).map_err(to_rpc_error)?;
        let rows = tables
            .into_iter()
            .filter(|table| {
                like_pattern
                    .as_deref()
                    .map(|pattern| mysql_like_matches(table, pattern))
                    .unwrap_or(true)
            })
            .map(|table| {
                vec![
                    Some(table),
                    Some("InnoDB".to_string()),
                    Some("10".to_string()),
                    Some("Dynamic".to_string()),
                    Some("0".to_string()),
                    Some("0".to_string()),
                    Some("0".to_string()),
                    Some("0".to_string()),
                    Some("0".to_string()),
                    Some("0".to_string()),
                    None,
                    None,
                    None,
                    None,
                    Some("utf8mb4_general_ci".to_string()),
                    None,
                    Some(String::new()),
                    Some("compatibility metadata".to_string()),
                ]
            })
            .collect();
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec![
                "Name".to_string(),
                "Engine".to_string(),
                "Version".to_string(),
                "Row_format".to_string(),
                "Rows".to_string(),
                "Avg_row_length".to_string(),
                "Data_length".to_string(),
                "Max_data_length".to_string(),
                "Index_length".to_string(),
                "Data_free".to_string(),
                "Auto_increment".to_string(),
                "Create_time".to_string(),
                "Update_time".to_string(),
                "Check_time".to_string(),
                "Collation".to_string(),
                "Checksum".to_string(),
                "Create_options".to_string(),
                "Comment".to_string(),
            ],
            rows,
        }));
    }

    if lower.starts_with("show columns from ") || lower.starts_with("show full columns from ") {
        let full = lower.starts_with("show full columns from ");
        let SqlPlan::ShowColumns { table } = parse_show_plan(trimmed, default_db)? else {
            return Ok(None);
        };
        let eng = state.engine.read().await;
        let desc = eng
            .describe_table(&table.db, &table.table)
            .map_err(to_rpc_error)?;
        return Ok(Some(mysql_show_columns_outcome(&desc, full)));
    }

    if lower.starts_with("describe ") || lower.starts_with("desc ") {
        let prefix_len = if lower.starts_with("describe ") { 9 } else { 5 };
        let tail = trimmed[prefix_len..].trim();
        let table = parse_table_ref(tail, default_db)?;
        let eng = state.engine.read().await;
        let desc = eng
            .describe_table(&table.db, &table.table)
            .map_err(to_rpc_error)?;
        return Ok(Some(mysql_show_columns_outcome(&desc, false)));
    }

    if lower.starts_with("show index from ") || lower.starts_with("show indexes from ") {
        let prefix_len = if lower.starts_with("show indexes from ") {
            18
        } else {
            15
        };
        let tail = trimmed[prefix_len..].trim();
        let table = parse_table_ref(tail, default_db)?;
        let eng = state.engine.read().await;
        let desc = eng
            .describe_table(&table.db, &table.table)
            .map_err(to_rpc_error)?;
        return Ok(Some(mysql_show_index_outcome(&table.table, &desc)));
    }

    if lower.starts_with("show keys from ") {
        let table = parse_table_ref(trimmed[14..].trim(), default_db)?;
        let eng = state.engine.read().await;
        let desc = eng
            .describe_table(&table.db, &table.table)
            .map_err(to_rpc_error)?;
        return Ok(Some(mysql_show_index_outcome(&table.table, &desc)));
    }

    if lower.starts_with("show create table ") {
        let tail = trimmed[18..].trim();
        let table = parse_table_ref(tail, default_db)?;
        let eng = state.engine.read().await;
        let desc = eng
            .describe_table(&table.db, &table.table)
            .map_err(to_rpc_error)?;
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec!["Table".to_string(), "Create Table".to_string()],
            rows: vec![vec![
                Some(table.table.clone()),
                Some(mysql_render_create_table(&table.table, &desc)),
            ]],
        }));
    }

    // SHOW TRIGGERS
    if lower == "show triggers" || lower.starts_with("show triggers ") {
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec![
                "Trigger".to_string(),
                "Event".to_string(),
                "Table".to_string(),
                "Statement".to_string(),
                "Timing".to_string(),
                "Created".to_string(),
                "sql_mode".to_string(),
                "Definer".to_string(),
                "character_set_client".to_string(),
                "collation_connection".to_string(),
                "Database Collation".to_string(),
            ],
            rows: vec![],
        }));
    }

    // SHOW EVENTS
    if lower == "show events" || lower.starts_with("show events ") {
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec![
                "Db".to_string(),
                "Name".to_string(),
                "Definer".to_string(),
                "Time zone".to_string(),
                "Type".to_string(),
                "Execute at".to_string(),
                "Interval value".to_string(),
                "Interval field".to_string(),
                "Starts".to_string(),
                "Ends".to_string(),
                "Status".to_string(),
                "Originator".to_string(),
                "character_set_client".to_string(),
                "collation_connection".to_string(),
                "Database Collation".to_string(),
            ],
            rows: vec![],
        }));
    }

    // SHOW PROCEDURE STATUS / SHOW FUNCTION STATUS
    if lower.starts_with("show procedure status") || lower.starts_with("show function status") {
        return Ok(Some(MySqlQueryOutcome::ResultSet {
            columns: vec![
                "Db".to_string(),
                "Name".to_string(),
                "Type".to_string(),
                "Definer".to_string(),
                "Modified".to_string(),
                "Created".to_string(),
                "Security_type".to_string(),
                "Comment".to_string(),
                "character_set_client".to_string(),
                "collation_connection".to_string(),
                "Database Collation".to_string(),
            ],
            rows: vec![],
        }));
    }

    Ok(None)
}

fn mysql_parse_select_found_rows_query(sql: &str) -> Option<String> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    if !trimmed.is_ascii() || trimmed.len() < 6 || !trimmed[..6].eq_ignore_ascii_case("select") {
        return None;
    }
    let rest = trimmed[6..].trim();
    if rest.len() < "found_rows()".len() {
        return None;
    }
    if !rest[..12].eq_ignore_ascii_case("found_rows()") {
        return None;
    }
    let tail = rest[12..].trim();
    if tail.is_empty() {
        return Some("FOUND_ROWS()".to_string());
    }
    let tail_lower = tail.to_ascii_lowercase();
    let alias = if tail_lower.starts_with("as ") {
        clean_sql_ident(tail[3..].trim())
    } else {
        clean_sql_ident(tail)
    };
    if alias.is_empty() || alias.contains(char::is_whitespace) || alias.contains(',') {
        return None;
    }
    Some(alias)
}

fn mysql_rewrite_sql_calc_found_rows(sql: &str) -> Option<String> {
    const TOKEN: &str = "sql_calc_found_rows";
    let trimmed = sql.trim().trim_end_matches(';').trim();
    if !trimmed.is_ascii() || trimmed.len() < 6 || !trimmed[..6].eq_ignore_ascii_case("select") {
        return None;
    }
    let rest = trimmed[6..].trim_start();
    if rest.len() < TOKEN.len() || !rest[..TOKEN.len()].eq_ignore_ascii_case(TOKEN) {
        return None;
    }
    if rest.len() > TOKEN.len() && !rest.as_bytes()[TOKEN.len()].is_ascii_whitespace() {
        return None;
    }
    let tail = rest[TOKEN.len()..].trim_start();
    if tail.is_empty() {
        return None;
    }
    Some(format!("SELECT {}", tail))
}

fn mysql_push_lenenc_int(buf: &mut Vec<u8>, n: usize) {
    if n < 251 {
        buf.push(n as u8);
    } else if n <= 0xffff {
        buf.push(0xfc);
        buf.extend_from_slice(&(n as u16).to_le_bytes());
    } else if n <= 0x00ff_ffff {
        buf.push(0xfd);
        buf.push((n & 0xff) as u8);
        buf.push(((n >> 8) & 0xff) as u8);
        buf.push(((n >> 16) & 0xff) as u8);
    } else {
        buf.push(0xfe);
        buf.extend_from_slice(&(n as u64).to_le_bytes());
    }
}

fn mysql_push_lenenc_bytes(buf: &mut Vec<u8>, bytes: &[u8]) {
    mysql_push_lenenc_int(buf, bytes.len());
    buf.extend_from_slice(bytes);
}

fn mysql_column_type(lit: &MySqlLiteral) -> u8 {
    match lit {
        MySqlLiteral::Int(_) => 0x08,
        MySqlLiteral::Str(_) => 0xfd,
        MySqlLiteral::Null => 0x06,
    }
}

fn mysql_literal_text(lit: &MySqlLiteral) -> Option<String> {
    match lit {
        MySqlLiteral::Int(v) => Some(v.to_string()),
        MySqlLiteral::Str(v) => Some(v.clone()),
        MySqlLiteral::Null => None,
    }
}

fn mysql_column_definition_packet_with_type(name: &str, column_type: u8, len: u32) -> Vec<u8> {
    mysql_column_definition_packet_with_type_flags(name, column_type, len, 0)
}

fn mysql_column_definition_packet_with_type_flags(
    name: &str,
    column_type: u8,
    len: u32,
    flags: u16,
) -> Vec<u8> {
    let mut payload = Vec::new();
    mysql_push_lenenc_bytes(&mut payload, b"def");
    mysql_push_lenenc_bytes(&mut payload, b"");
    mysql_push_lenenc_bytes(&mut payload, b"");
    mysql_push_lenenc_bytes(&mut payload, b"");
    mysql_push_lenenc_bytes(&mut payload, name.as_bytes());
    mysql_push_lenenc_bytes(&mut payload, name.as_bytes());
    payload.push(0x0c);
    payload.extend_from_slice(&0x21u16.to_le_bytes());
    payload.extend_from_slice(&len.to_le_bytes());
    payload.push(column_type);
    payload.extend_from_slice(&flags.to_le_bytes());
    payload.push(0);
    payload.extend_from_slice(&[0u8; 2]);
    payload
}

fn mysql_column_definition_packet(name: &str, lit: &MySqlLiteral) -> Vec<u8> {
    let len = match lit {
        MySqlLiteral::Int(_) => 20u32,
        MySqlLiteral::Str(v) => v.len().max(1) as u32,
        MySqlLiteral::Null => 4u32,
    };
    mysql_column_definition_packet_with_type(name, mysql_column_type(lit), len)
}

fn mysql_eof_packet_with_status(status_flags: u16) -> Vec<u8> {
    let mut payload = Vec::new();
    payload.push(0xfe);
    payload.extend_from_slice(&0u16.to_le_bytes());
    payload.extend_from_slice(&status_flags.to_le_bytes());
    payload
}

fn mysql_eof_packet() -> Vec<u8> {
    mysql_eof_packet_with_status(MYSQL_STATUS_AUTOCOMMIT)
}

fn mysql_text_row_packet(row: &[Option<String>]) -> Vec<u8> {
    let mut payload = Vec::new();
    for cell in row {
        match cell {
            Some(text) => mysql_push_lenenc_bytes(&mut payload, text.as_bytes()),
            None => payload.push(0xfb),
        }
    }
    payload
}

fn mysql_stmt_column_type_code(kind: MySqlStmtColumnType) -> u8 {
    match kind {
        MySqlStmtColumnType::Bool | MySqlStmtColumnType::LongLong => 0x08,
        MySqlStmtColumnType::Double => 0x05,
        MySqlStmtColumnType::Date
        | MySqlStmtColumnType::Time
        | MySqlStmtColumnType::DateTime
        | MySqlStmtColumnType::Json
        | MySqlStmtColumnType::Bytes
        | MySqlStmtColumnType::Uuid
        | MySqlStmtColumnType::VarString => 0xfd,
    }
}

fn mysql_stmt_column_type_for_mysql_literal(lit: &MySqlLiteral) -> MySqlStmtColumnType {
    match lit {
        MySqlLiteral::Int(_) => MySqlStmtColumnType::LongLong,
        MySqlLiteral::Str(_) | MySqlLiteral::Null => MySqlStmtColumnType::VarString,
    }
}

fn mysql_stmt_column_type_for_lit(lit: &Lit) -> MySqlStmtColumnType {
    match lit {
        Lit::Bool { .. } => MySqlStmtColumnType::Bool,
        Lit::I64 { .. } | Lit::U64 { .. } => MySqlStmtColumnType::LongLong,
        Lit::F64 { .. } => MySqlStmtColumnType::Double,
        Lit::Date { .. } => MySqlStmtColumnType::Date,
        Lit::Time { .. } => MySqlStmtColumnType::Time,
        Lit::Datetime { .. } => MySqlStmtColumnType::DateTime,
        Lit::Json { .. } => MySqlStmtColumnType::Json,
        Lit::Bytes { .. } => MySqlStmtColumnType::Bytes,
        Lit::Uuid { .. } => MySqlStmtColumnType::Uuid,
        Lit::Null | Lit::Dec { .. } | Lit::Str { .. } | Lit::Embedding { .. } => {
            MySqlStmtColumnType::VarString
        }
    }
}

fn mysql_stmt_column_type_from_desc_column(column: &Value) -> MySqlStmtColumnType {
    mysql_stmt_column_type_from_desc_kind(
        column
            .get("type")
            .and_then(|v| v.get("kind"))
            .and_then(|v| v.as_str())
            .unwrap_or("string"),
    )
}

fn mysql_stmt_column_type_from_desc_kind(kind: &str) -> MySqlStmtColumnType {
    match kind {
        "bool" => MySqlStmtColumnType::Bool,
        "i64" | "u64" => MySqlStmtColumnType::LongLong,
        "f64" => MySqlStmtColumnType::Double,
        "date" => MySqlStmtColumnType::Date,
        "time" => MySqlStmtColumnType::Time,
        "datetime" => MySqlStmtColumnType::DateTime,
        "json" => MySqlStmtColumnType::Json,
        "bytes" => MySqlStmtColumnType::Bytes,
        "uuid" => MySqlStmtColumnType::Uuid,
        _ => MySqlStmtColumnType::VarString,
    }
}

fn mysql_stmt_column_type_for_type_desc(desc: &TypeDesc) -> MySqlStmtColumnType {
    match desc.kind.as_str() {
        "bool" => MySqlStmtColumnType::Bool,
        "i64" | "u64" => MySqlStmtColumnType::LongLong,
        "f64" => MySqlStmtColumnType::Double,
        "date" => MySqlStmtColumnType::Date,
        "time" => MySqlStmtColumnType::Time,
        "datetime" => MySqlStmtColumnType::DateTime,
        "json" => MySqlStmtColumnType::Json,
        "bytes" => MySqlStmtColumnType::Bytes,
        "uuid" => MySqlStmtColumnType::Uuid,
        _ => MySqlStmtColumnType::VarString,
    }
}

fn mysql_stmt_is_textual_column_type(kind: MySqlStmtColumnType) -> bool {
    matches!(
        kind,
        MySqlStmtColumnType::Date
            | MySqlStmtColumnType::Time
            | MySqlStmtColumnType::DateTime
            | MySqlStmtColumnType::Json
            | MySqlStmtColumnType::Bytes
            | MySqlStmtColumnType::Uuid
            | MySqlStmtColumnType::VarString
    )
}

fn mysql_stmt_base_table_alias(base: &BaseTableRef) -> &str {
    base.r#as.as_deref().unwrap_or(&base.table)
}

fn mysql_stmt_table_matches_name(base: &BaseTableRef, table_name: &str) -> bool {
    table_name.eq_ignore_ascii_case(&base.table)
        || table_name.eq_ignore_ascii_case(mysql_stmt_base_table_alias(base))
        || table_name
            .rsplit_once('.')
            .map(|(db, table)| {
                db.eq_ignore_ascii_case(&base.db) && table.eq_ignore_ascii_case(&base.table)
            })
            .unwrap_or(false)
}

fn mysql_stmt_collect_base_tables(table_ref: &TableRef, out: &mut Vec<BaseTableRef>) {
    match table_ref {
        TableRef::Base(base) => out.push(base.clone()),
        TableRef::Join(join) => {
            mysql_stmt_collect_base_tables(join.join.left.as_ref(), out);
            mysql_stmt_collect_base_tables(join.join.right.as_ref(), out);
        }
        TableRef::Subquery(_) => {}
    }
}

fn mysql_stmt_collect_table_descs(
    eng: &Engine,
    from: &TableRef,
) -> Result<Vec<MySqlStmtPrepareTableDesc>, RpcError> {
    let mut base_tables = Vec::new();
    mysql_stmt_collect_base_tables(from, &mut base_tables);
    base_tables
        .into_iter()
        .map(|base| {
            eng.describe_table(&base.db, &base.table)
                .map(|desc| MySqlStmtPrepareTableDesc { base, desc })
                .map_err(to_rpc_error)
        })
        .collect()
}

fn mysql_stmt_desc_column_type(desc: &Value, col: &str) -> Option<MySqlStmtColumnType> {
    desc.get("columns")
        .and_then(|v| v.as_array())
        .into_iter()
        .flatten()
        .find(|column| {
            column
                .get("name")
                .and_then(|v| v.as_str())
                .map(|name| name.eq_ignore_ascii_case(col))
                .unwrap_or(false)
        })
        .map(mysql_stmt_column_type_from_desc_column)
}

fn mysql_stmt_resolve_column_type(
    table_descs: &[MySqlStmtPrepareTableDesc],
    col: &str,
    table: Option<&str>,
) -> MySqlStmtColumnType {
    let mut matches = Vec::new();
    for table_desc in table_descs {
        if let Some(table_name) = table {
            if !mysql_stmt_table_matches_name(&table_desc.base, table_name) {
                continue;
            }
        }
        if let Some(found) = mysql_stmt_desc_column_type(&table_desc.desc, col) {
            matches.push(found);
        }
    }
    if matches.len() == 1 {
        matches[0]
    } else {
        MySqlStmtColumnType::VarString
    }
}

fn mysql_stmt_resolve_column_name(
    table_descs: &[MySqlStmtPrepareTableDesc],
    col: &str,
    table: Option<&str>,
) -> Option<String> {
    let mut matches = Vec::new();
    for table_desc in table_descs {
        if let Some(table_name) = table {
            if !mysql_stmt_table_matches_name(&table_desc.base, table_name) {
                continue;
            }
        }
        let Some(found_name) = table_desc
            .desc
            .get("columns")
            .and_then(|v| v.as_array())
            .into_iter()
            .flatten()
            .find_map(|column| {
                let name = column.get("name").and_then(|v| v.as_str())?;
                name.eq_ignore_ascii_case(col).then(|| name.to_string())
            })
        else {
            continue;
        };
        matches.push(found_name);
    }
    (matches.len() == 1).then(|| matches.remove(0))
}

fn mysql_canonicalize_join_expr_columns(
    expr: &mut Expr,
    table_descs: &[MySqlStmtPrepareTableDesc],
) {
    match expr {
        Expr::Col { col, table } => {
            if let Some(canonical) =
                mysql_stmt_resolve_column_name(table_descs, col, table.as_deref())
            {
                *col = canonical;
            }
        }
        Expr::Lit { .. } | Expr::Param { .. } => {}
        Expr::Op {
            a,
            b,
            args,
            list,
            lo,
            hi,
            ..
        } => {
            if let Some(a) = a.as_mut() {
                mysql_canonicalize_join_expr_columns(a, table_descs);
            }
            if let Some(b) = b.as_mut() {
                mysql_canonicalize_join_expr_columns(b, table_descs);
            }
            if let Some(args) = args.as_mut() {
                for arg in args {
                    mysql_canonicalize_join_expr_columns(arg, table_descs);
                }
            }
            if let Some(list) = list.as_mut() {
                for item in list {
                    mysql_canonicalize_join_expr_columns(item, table_descs);
                }
            }
            if let Some(lo) = lo.as_mut() {
                mysql_canonicalize_join_expr_columns(lo, table_descs);
            }
            if let Some(hi) = hi.as_mut() {
                mysql_canonicalize_join_expr_columns(hi, table_descs);
            }
        }
        Expr::Func { args, .. } => {
            for arg in args {
                mysql_canonicalize_join_expr_columns(arg, table_descs);
            }
        }
        Expr::Cast { cast } => {
            mysql_canonicalize_join_expr_columns(cast.expr.as_mut(), table_descs)
        }
        Expr::Case { case_ } => {
            for when in case_.when.iter_mut() {
                mysql_canonicalize_join_expr_columns(&mut when.r#if, table_descs);
                mysql_canonicalize_join_expr_columns(&mut when.then, table_descs);
            }
            if let Some(otherwise) = case_.r#else.as_mut() {
                mysql_canonicalize_join_expr_columns(otherwise, table_descs);
            }
        }
        Expr::Subquery { .. } | Expr::Exists { .. } => {}
    }
}

fn mysql_canonicalize_join_on_columns(
    table_ref: &mut TableRef,
    table_descs: &[MySqlStmtPrepareTableDesc],
) {
    if let TableRef::Join(join) = table_ref {
        mysql_canonicalize_join_on_columns(join.join.left.as_mut(), table_descs);
        mysql_canonicalize_join_on_columns(join.join.right.as_mut(), table_descs);
        if let Some(on) = join.join.on.as_mut() {
            mysql_canonicalize_join_expr_columns(on, table_descs);
        }
    }
}

fn mysql_stmt_merge_column_types(
    left: MySqlStmtColumnType,
    right: MySqlStmtColumnType,
) -> MySqlStmtColumnType {
    if left == right {
        return left;
    }
    if mysql_stmt_is_textual_column_type(left) || mysql_stmt_is_textual_column_type(right) {
        return MySqlStmtColumnType::VarString;
    }
    if matches!(left, MySqlStmtColumnType::Double) || matches!(right, MySqlStmtColumnType::Double) {
        return MySqlStmtColumnType::Double;
    }
    if matches!(left, MySqlStmtColumnType::LongLong)
        || matches!(right, MySqlStmtColumnType::LongLong)
    {
        return MySqlStmtColumnType::LongLong;
    }
    if matches!(left, MySqlStmtColumnType::Bool) || matches!(right, MySqlStmtColumnType::Bool) {
        return MySqlStmtColumnType::Bool;
    }
    MySqlStmtColumnType::LongLong
}

fn mysql_stmt_aggregate_result_type(
    op: MySqlCompatAggregateOp,
    source_type: MySqlStmtColumnType,
) -> MySqlStmtColumnType {
    match op {
        MySqlCompatAggregateOp::CountRows
        | MySqlCompatAggregateOp::CountNonNull
        | MySqlCompatAggregateOp::CountDistinct => MySqlStmtColumnType::LongLong,
        MySqlCompatAggregateOp::Avg => MySqlStmtColumnType::Double,
        MySqlCompatAggregateOp::Sum => {
            if matches!(source_type, MySqlStmtColumnType::Double) {
                MySqlStmtColumnType::Double
            } else {
                MySqlStmtColumnType::LongLong
            }
        }
        MySqlCompatAggregateOp::Min | MySqlCompatAggregateOp::Max => source_type,
        MySqlCompatAggregateOp::GroupConcat
        | MySqlCompatAggregateOp::StringAgg
        | MySqlCompatAggregateOp::ArrayAgg => MySqlStmtColumnType::VarString,
        MySqlCompatAggregateOp::BitAnd
        | MySqlCompatAggregateOp::BitOr
        | MySqlCompatAggregateOp::BitXor => MySqlStmtColumnType::LongLong,
    }
}

fn mysql_stmt_expr_type(
    expr: &Expr,
    table_descs: &[MySqlStmtPrepareTableDesc],
) -> MySqlStmtColumnType {
    match expr {
        Expr::Lit { lit } => mysql_stmt_column_type_for_lit(lit),
        Expr::Col { col, table } => {
            mysql_stmt_resolve_column_type(table_descs, col, table.as_deref())
        }
        Expr::Param { .. } => MySqlStmtColumnType::VarString,
        Expr::Op { op, a, b, .. } => match op.as_str() {
            "and" | "or" | "not" | "eq" | "ne" | "lt" | "le" | "gt" | "ge" | "in" | "between"
            | "like" | "ilike" | "is_null" => MySqlStmtColumnType::LongLong,
            "add" | "sub" | "mul" | "mod" => {
                let left = a
                    .as_ref()
                    .map(|expr| mysql_stmt_expr_type(expr, table_descs))
                    .unwrap_or(MySqlStmtColumnType::VarString);
                let right = b
                    .as_ref()
                    .map(|expr| mysql_stmt_expr_type(expr, table_descs))
                    .unwrap_or(MySqlStmtColumnType::VarString);
                mysql_stmt_merge_column_types(left, right)
            }
            "div" => MySqlStmtColumnType::Double,
            _ => MySqlStmtColumnType::VarString,
        },
        Expr::Func { name, args, .. } => match name.as_str() {
            "count" | "length" | "char_length" | "character_length" | "locate" | "instr"
            | "find_in_set" | "isnull" | "datediff" | "timestampdiff" | "weekday" | "dayofweek"
            | "dayofyear" | "quarter" | "extract" | "bit_length" | "octet_length" | "ascii"
            | "ord" | "strcmp" | "crc32" | "json_length" | "json_contains" | "json_valid" => {
                MySqlStmtColumnType::LongLong
            }
            "year" | "month" | "day" | "dayofmonth" | "hour" | "minute" | "second"
            | "unix_timestamp" | "sign" | "sleep" | "benchmark" | "period_add" | "period_diff"
            | "inet_aton" => MySqlStmtColumnType::LongLong,
            "avg" | "round" | "sqrt" | "pow" | "power" | "truncate" | "log" | "ln" | "log2"
            | "log10" | "exp" | "pi" | "rand" | "degrees" | "radians" => {
                MySqlStmtColumnType::Double
            }
            "sum" | "abs" | "floor" | "ceil" | "ceiling" | "mod" => args
                .iter()
                .map(|expr| mysql_stmt_expr_type(expr, table_descs))
                .reduce(mysql_stmt_merge_column_types)
                .unwrap_or(MySqlStmtColumnType::VarString),
            "min" | "max" | "if" | "coalesce" | "ifnull" | "nullif" | "least" | "greatest" => args
                .iter()
                .map(|expr| mysql_stmt_expr_type(expr, table_descs))
                .reduce(mysql_stmt_merge_column_types)
                .unwrap_or(MySqlStmtColumnType::VarString),
            "lower"
            | "lcase"
            | "upper"
            | "ucase"
            | "trim"
            | "ltrim"
            | "rtrim"
            | "left"
            | "right"
            | "substring"
            | "substr"
            | "replace"
            | "concat"
            | "concat_ws"
            | "repeat"
            | "reverse"
            | "lpad"
            | "rpad"
            | "space"
            | "hex"
            | "unhex"
            | "format"
            | "uuid"
            | "date"
            | "date_format"
            | "from_unixtime"
            | "date_add"
            | "date_sub"
            | "timestampadd"
            | "now"
            | "current_timestamp"
            | "localtimestamp"
            | "curdate"
            | "current_date"
            | "curtime"
            | "current_time"
            | "localtime"
            | "monthname"
            | "dayname"
            | "last_day"
            | "str_to_date"
            | "makedate"
            | "maketime"
            | "quote"
            | "soundex"
            | "char"
            | "make_set"
            | "export_set"
            | "substring_index"
            | "regexp_replace"
            | "regexp_substr"
            | "to_base64"
            | "from_base64"
            | "bin"
            | "oct"
            | "conv"
            | "md5"
            | "sha1"
            | "sha"
            | "sha2"
            | "inet_ntoa"
            | "json_extract"
            | "json_unquote"
            | "json_object"
            | "json_array"
            | "json_set"
            | "json_keys"
            | "json_merge_preserve"
            | "json_type"
            | "convert_tz"
            | "addtime"
            | "subtime"
            | "time_to_sec"
            | "sec_to_time"
            | "field"
            | "elt"
            | "sysdate"
            | "group_concat" => MySqlStmtColumnType::VarString,
            _ => MySqlStmtColumnType::VarString,
        },
        Expr::Cast { cast } => mysql_stmt_column_type_for_type_desc(&cast.to),
        Expr::Case { case_ } => {
            let mut out = case_
                .when
                .iter()
                .map(|branch| mysql_stmt_expr_type(&branch.then, table_descs))
                .reduce(mysql_stmt_merge_column_types)
                .unwrap_or(MySqlStmtColumnType::VarString);
            if let Some(other) = case_.r#else.as_ref() {
                out = mysql_stmt_merge_column_types(out, mysql_stmt_expr_type(other, table_descs));
            }
            out
        }
        Expr::Subquery { subquery } => {
            mysql_stmt_query_single_projection_type(&subquery.query, table_descs)
        }
        Expr::Exists { .. } => MySqlStmtColumnType::LongLong,
    }
}

/// Compute MySQL column flags from table descriptor metadata.
fn mysql_stmt_expr_flags(expr: &Expr, table_descs: &[MySqlStmtPrepareTableDesc]) -> u16 {
    match expr {
        Expr::Col { col, table } => {
            mysql_stmt_resolve_column_flags(table_descs, col, table.as_deref())
        }
        Expr::Func { name, .. } => {
            let n = name.to_ascii_lowercase();
            match n.as_str() {
                "count" | "sum" | "avg" | "min" | "max" | "bit_and" | "bit_or" | "bit_xor" => {
                    MYSQL_COL_FLAG_NOT_NULL | MYSQL_COL_FLAG_NUM
                }
                // Scalar functions returning integers / floats → NUM
                "length" | "char_length" | "character_length" | "octet_length" | "bit_length"
                | "ascii" | "ord" | "locate" | "instr" | "position" | "strcmp" | "crc32"
                | "abs" | "sign" | "ceil" | "ceiling" | "floor" | "round" | "truncate" | "mod"
                | "pow" | "power" | "sqrt" | "exp" | "log" | "log2" | "log10" | "ln"
                | "degrees" | "radians" | "pi" | "rand" | "year" | "month" | "day"
                | "dayofmonth" | "dayofweek" | "dayofyear" | "hour" | "minute" | "second"
                | "quarter" | "week" | "yearweek" | "weekday" | "extract" | "period_add"
                | "period_diff" | "unix_timestamp" | "datediff" | "timestampdiff"
                | "time_to_sec" | "sec_to_time" | "isnull" | "ifnull" | "nullif" | "coalesce"
                | "field" | "find_in_set" | "inet_aton" | "json_length" | "json_contains"
                | "json_valid" | "sleep" | "benchmark" | "connection_id" | "last_insert_id"
                | "found_rows" => MYSQL_COL_FLAG_NUM,
                _ => 0,
            }
        }
        Expr::Op { op, .. } => match op.as_str() {
            "add" | "sub" | "mul" | "div" | "mod" => MYSQL_COL_FLAG_NUM,
            _ => 0,
        },
        Expr::Lit {
            lit: Lit::I64 { .. } | Lit::U64 { .. } | Lit::F64 { .. } | Lit::Bool { .. },
        } => MYSQL_COL_FLAG_NUM,
        Expr::Lit { .. } => 0,
        Expr::Subquery { subquery } => mysql_stmt_scalar_subquery_result_flags(
            mysql_stmt_query_single_projection_flags(&subquery.query, table_descs),
        ),
        Expr::Exists { .. } => MYSQL_COL_FLAG_NOT_NULL | MYSQL_COL_FLAG_NUM,
        _ => 0,
    }
}

/// Resolve column flags from table descriptor metadata (NOT_NULL, PRIMARY_KEY, UNSIGNED, etc.).
fn mysql_stmt_resolve_column_flags(
    table_descs: &[MySqlStmtPrepareTableDesc],
    col: &str,
    _table_alias: Option<&str>,
) -> u16 {
    for td in table_descs {
        if let Some(columns) = td.desc.get("columns").and_then(|v| v.as_array()) {
            for column in columns {
                if column.get("name").and_then(|v| v.as_str()) == Some(col) {
                    let mut flags = 0u16;
                    // NOT NULL flag
                    if column.get("nullable").and_then(|v| v.as_bool()) == Some(false) {
                        flags |= MYSQL_COL_FLAG_NOT_NULL;
                    }
                    // Type-based flags
                    let kind = column
                        .get("type")
                        .and_then(|t| t.get("kind"))
                        .and_then(|k| k.as_str())
                        .unwrap_or("");
                    match kind {
                        "u64" => flags |= MYSQL_COL_FLAG_UNSIGNED | MYSQL_COL_FLAG_NUM,
                        "i64" | "bool" => flags |= MYSQL_COL_FLAG_NUM,
                        "f64" => flags |= MYSQL_COL_FLAG_NUM,
                        "bytes" => flags |= MYSQL_COL_FLAG_BINARY,
                        _ => {}
                    }
                    // Primary key flag
                    if let Some(pk) = td.desc.get("primary_key").and_then(|v| v.as_array()) {
                        if pk.iter().any(|k| k.as_str() == Some(col)) {
                            flags |= MYSQL_COL_FLAG_PRIMARY_KEY | MYSQL_COL_FLAG_NOT_NULL;
                        }
                    }
                    return flags;
                }
            }
        }
    }
    0
}

fn mysql_stmt_query_body_single_projection_type(
    body: &QueryBody,
    table_descs: &[MySqlStmtPrepareTableDesc],
) -> MySqlStmtColumnType {
    match body {
        QueryBody::Select { select } => {
            if select.projection.len() != 1 {
                return MySqlStmtColumnType::VarString;
            }
            mysql_stmt_expr_type(&select.projection[0].expr, table_descs)
        }
        QueryBody::Setop { setop } => mysql_stmt_merge_column_types(
            mysql_stmt_query_body_single_projection_type(setop.left.as_ref(), table_descs),
            mysql_stmt_query_body_single_projection_type(setop.right.as_ref(), table_descs),
        ),
    }
}

fn mysql_stmt_query_single_projection_type(
    query: &Query,
    table_descs: &[MySqlStmtPrepareTableDesc],
) -> MySqlStmtColumnType {
    mysql_stmt_query_body_single_projection_type(query.body.as_ref(), table_descs)
}

fn mysql_stmt_query_body_single_projection_flags(
    body: &QueryBody,
    table_descs: &[MySqlStmtPrepareTableDesc],
) -> u16 {
    match body {
        QueryBody::Select { select } => {
            if select.projection.len() != 1 {
                return 0;
            }
            mysql_stmt_expr_flags(&select.projection[0].expr, table_descs)
        }
        QueryBody::Setop { setop } => {
            mysql_stmt_query_body_single_projection_flags(setop.left.as_ref(), table_descs)
                | mysql_stmt_query_body_single_projection_flags(setop.right.as_ref(), table_descs)
        }
    }
}

fn mysql_stmt_query_single_projection_flags(
    query: &Query,
    table_descs: &[MySqlStmtPrepareTableDesc],
) -> u16 {
    mysql_stmt_query_body_single_projection_flags(query.body.as_ref(), table_descs)
}

fn mysql_stmt_scalar_subquery_result_flags(flags: u16) -> u16 {
    flags & (MYSQL_COL_FLAG_NUM | MYSQL_COL_FLAG_UNSIGNED | MYSQL_COL_FLAG_BINARY)
}

fn mysql_stmt_placeholder_sql_for_column(column: &MySqlStmtPrepareColumn) -> &'static str {
    match column.column_type {
        MySqlStmtColumnType::Bool => "FALSE",
        MySqlStmtColumnType::LongLong => "0",
        MySqlStmtColumnType::Double => "SQRT(0)",
        MySqlStmtColumnType::Date => "CAST('1970-01-01' AS DATE)",
        MySqlStmtColumnType::Time => "CAST('00:00:00' AS TIME)",
        MySqlStmtColumnType::DateTime => "CAST('1970-01-01 00:00:00' AS DATETIME)",
        MySqlStmtColumnType::Json | MySqlStmtColumnType::Uuid => "''",
        MySqlStmtColumnType::Bytes => "X''",
        MySqlStmtColumnType::VarString => {
            if (column.flags & MYSQL_COL_FLAG_BINARY) != 0 {
                "X''"
            } else {
                "''"
            }
        }
    }
}

async fn mysql_stmt_replace_embedded_subqueries_with_typed_placeholders(
    state: &AppState,
    expr_sql: &str,
    default_db: Option<&str>,
) -> Option<String> {
    let mut rewritten = expr_sql.to_string();
    loop {
        let lower = rewritten.to_ascii_lowercase();
        let Some(sel_pos) = lower.find("(select ") else {
            return Some(rewritten);
        };
        let close_pos = find_matching_parenthesis(&rewritten, sel_pos)?;
        let sub_sql = rewritten[sel_pos + 1..close_pos].trim().to_string();
        let sub_columns = Box::pin(mysql_stmt_prepare_columns(state, &sub_sql, default_db)).await;
        let first = sub_columns.first()?;
        let replacement = mysql_stmt_placeholder_sql_for_column(first);
        rewritten = format!(
            "{}{}{}",
            &rewritten[..sel_pos],
            replacement,
            &rewritten[close_pos + 1..]
        );
    }
}

async fn mysql_stmt_prepare_columns_for_projection_subquery(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Option<Vec<MySqlStmtPrepareColumn>> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("select ") || !lower.contains("(select ") {
        return None;
    }

    let rest = &trimmed[7..];
    let (projection_sql, from_tail) = match find_keyword_top_level(rest, "from") {
        Some(from_pos) => (rest[..from_pos].trim(), Some(rest[from_pos..].trim())),
        None => (rest.trim(), None),
    };
    let projection_items = split_csv_top_level(projection_sql);
    if projection_items.is_empty() {
        return None;
    }
    if !projection_items.iter().any(|item| {
        let (expr_raw, _) = mysql_parse_projection_expr_alias(item);
        expr_raw.to_ascii_lowercase().contains("(select ")
    }) {
        return None;
    }

    let mut columns = Vec::with_capacity(projection_items.len());
    let mut saw_subquery = false;
    for (idx, item) in projection_items.iter().enumerate() {
        let (expr_raw, alias) = mysql_parse_projection_expr_alias(item);
        if let Some(sub_sql) = mysql_parse_scalar_subquery_select(&expr_raw) {
            saw_subquery = true;
            let sub_columns =
                Box::pin(mysql_stmt_prepare_columns(state, &sub_sql, default_db)).await;
            let first = sub_columns.first()?;
            columns.push(MySqlStmtPrepareColumn {
                name: alias.unwrap_or_else(|| format!("expr{}", idx + 1)),
                column_type: first.column_type,
                flags: mysql_stmt_scalar_subquery_result_flags(first.flags),
            });
            continue;
        }

        let projection_sql = if expr_raw.to_ascii_lowercase().contains("(select ") {
            saw_subquery = true;
            let rewritten_expr = mysql_stmt_replace_embedded_subqueries_with_typed_placeholders(
                state, &expr_raw, default_db,
            )
            .await?;
            if let Some(alias) = alias.as_ref() {
                format!("{rewritten_expr} AS {alias}")
            } else {
                rewritten_expr
            }
        } else {
            item.trim().to_string()
        };

        let single_sql = if let Some(from_tail) = from_tail {
            format!("SELECT {projection_sql} {from_tail}")
        } else {
            format!("SELECT {projection_sql}")
        };
        let inferred = Box::pin(mysql_stmt_prepare_columns(state, &single_sql, default_db)).await;
        let mut first = inferred.into_iter().next()?;
        if let Some(alias) = alias {
            first.name = alias;
        }
        columns.push(first);
    }

    saw_subquery.then_some(columns)
}

fn mysql_expand_select_projection_wildcards(
    from: Option<&TableRef>,
    projection: &[SelectItem],
    table_descs: &[MySqlStmtPrepareTableDesc],
) -> Result<Vec<SelectItem>, RpcError> {
    if from.is_none() {
        return Ok(projection.to_vec());
    }

    let projection_has_qualified_wildcards = projection.iter().any(|item| {
        matches!(
            &item.expr,
            Expr::Col {
                col,
                table: Some(_)
            } if col == "*"
        )
    });
    if !projection.is_empty() && !projection_has_qualified_wildcards {
        return Ok(projection.to_vec());
    }

    let qualify_columns = table_descs.len() > 1
        || table_descs
            .iter()
            .any(|table_desc| table_desc.base.r#as.is_some());
    let expand_table_desc = |table_desc: &MySqlStmtPrepareTableDesc,
                             expanded: &mut Vec<SelectItem>| {
        let table_name =
            qualify_columns.then(|| mysql_stmt_base_table_alias(&table_desc.base).to_string());
        if let Some(columns) = table_desc.desc.get("columns").and_then(|v| v.as_array()) {
            for column in columns {
                let Some(name) = column.get("name").and_then(|v| v.as_str()) else {
                    continue;
                };
                expanded.push(SelectItem {
                    expr: Expr::Col {
                        col: name.to_string(),
                        table: table_name.clone(),
                    },
                    r#as: None,
                });
            }
        }
    };

    let mut expanded = Vec::new();
    if projection.is_empty() {
        for table_desc in table_descs {
            expand_table_desc(table_desc, &mut expanded);
        }
    } else {
        for item in projection {
            let Expr::Col {
                col,
                table: requested_table,
            } = &item.expr
            else {
                expanded.push(item.clone());
                continue;
            };
            if col != "*" {
                expanded.push(item.clone());
                continue;
            }
            let requested_table = requested_table
                .as_deref()
                .ok_or_else(|| RpcError::new("internal", "wildcard projection missing table"))?;
            let mut matched = false;
            for table_desc in table_descs.iter().filter(|table_desc| {
                table_desc
                    .base
                    .r#as
                    .as_deref()
                    .map(|alias| alias.eq_ignore_ascii_case(requested_table))
                    .unwrap_or(false)
            }) {
                matched = true;
                expand_table_desc(table_desc, &mut expanded);
            }
            if !matched {
                for table_desc in table_descs.iter().filter(|table_desc| {
                    table_desc.base.r#as.is_none()
                        && mysql_stmt_table_matches_name(&table_desc.base, requested_table)
                }) {
                    matched = true;
                    expand_table_desc(table_desc, &mut expanded);
                }
            }
            if !matched {
                return Err(RpcError::new(
                    "invalid_request",
                    format!(
                        "unknown table '{}' in qualified wildcard projection",
                        requested_table
                    ),
                ));
            }
        }
    }

    if expanded.is_empty() {
        return Err(RpcError::new("invalid_request", "table has no columns"));
    }
    Ok(expanded)
}

fn mysql_stmt_prepare_columns_from_select(
    from: Option<&TableRef>,
    projection: &[SelectItem],
    table_descs: &[MySqlStmtPrepareTableDesc],
) -> Vec<MySqlStmtPrepareColumn> {
    let expanded_projection =
        mysql_expand_select_projection_wildcards(from, projection, table_descs)
            .unwrap_or_else(|_| projection.to_vec());

    expanded_projection
        .iter()
        .enumerate()
        .map(|(idx, item)| {
            let column_type = mysql_stmt_expr_type(&item.expr, table_descs);
            let flags = mysql_stmt_expr_flags(&item.expr, table_descs);
            MySqlStmtPrepareColumn {
                name: projection_label(item, idx),
                column_type,
                flags,
            }
        })
        .collect()
}

async fn mysql_stmt_prepare_columns_for_translated_select(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Option<Vec<MySqlStmtPrepareColumn>> {
    let parsed_plan = parse_sql_plan(sql, default_db).or_else(|_| {
        let (prefix, _where_clause, suffix) = mysql_parse_select_where_parts(sql)
            .ok_or_else(|| RpcError::new("not_supported", "unsupported SELECT statement"))?;
        parse_sql_plan(
            &mysql_rebuild_select_with_where(&prefix, Some("1 = 1"), &suffix),
            default_db,
        )
    });
    let Ok(SqlPlan::Select {
        from, projection, ..
    }) = parsed_plan
    else {
        return None;
    };

    let table_descs = match from.as_ref() {
        Some(from_ref) => {
            let eng = state.engine.read().await;
            mysql_stmt_collect_table_descs(&eng, from_ref).ok()?
        }
        None => Vec::new(),
    };
    let expanded_projection =
        mysql_expand_select_projection_wildcards(from.as_ref(), &projection, &table_descs).ok()?;
    Some(mysql_stmt_prepare_columns_from_select(
        from.as_ref(),
        &expanded_projection,
        &table_descs,
    ))
}

async fn mysql_stmt_prepare_columns(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
) -> Vec<MySqlStmtPrepareColumn> {
    if let Some((cols, _emit_row)) = parse_select_literal_query(sql, default_db) {
        return cols
            .into_iter()
            .map(|(name, lit)| MySqlStmtPrepareColumn {
                name,
                column_type: mysql_stmt_column_type_for_mysql_literal(&lit),
                flags: 0,
            })
            .collect();
    }

    if let Some(query) = mysql_parse_simple_aggregate_query(sql) {
        let source_columns =
            mysql_stmt_prepare_columns_for_translated_select(state, &query.source_sql, default_db)
                .await
                .unwrap_or_default();
        let source_type = source_columns
            .first()
            .map(|column| column.column_type)
            .unwrap_or(MySqlStmtColumnType::VarString);
        return vec![MySqlStmtPrepareColumn {
            name: query.alias,
            column_type: mysql_stmt_aggregate_result_type(query.aggregate_op, source_type),
            flags: MYSQL_COL_FLAG_NOT_NULL | MYSQL_COL_FLAG_NUM,
        }];
    }

    if let Some(query) = mysql_parse_grouped_aggregate_query(sql) {
        let source_columns =
            mysql_stmt_prepare_columns_for_translated_select(state, &query.source_sql, default_db)
                .await
                .unwrap_or_default();
        let group_type = source_columns
            .first()
            .map(|column| column.column_type)
            .unwrap_or(MySqlStmtColumnType::VarString);
        let group_flags = source_columns
            .first()
            .map(|column| column.flags)
            .unwrap_or(0);
        let aggregate_source_type = source_columns
            .get(1)
            .map(|column| column.column_type)
            .unwrap_or(MySqlStmtColumnType::VarString);
        return vec![
            MySqlStmtPrepareColumn {
                name: query.group_alias,
                column_type: group_type,
                flags: group_flags,
            },
            MySqlStmtPrepareColumn {
                name: query.aggregate_alias,
                column_type: mysql_stmt_aggregate_result_type(
                    query.aggregate_op,
                    aggregate_source_type,
                ),
                flags: MYSQL_COL_FLAG_NOT_NULL | MYSQL_COL_FLAG_NUM,
            },
        ];
    }

    if let Some(columns) =
        mysql_stmt_prepare_columns_for_projection_subquery(state, sql, default_db).await
    {
        return columns;
    }

    mysql_stmt_prepare_columns_for_translated_select(state, sql, default_db)
        .await
        .unwrap_or_default()
}

fn mysql_stmt_infer_column_types(
    rows: &[Vec<Option<String>>],
    column_count: usize,
) -> Vec<MySqlStmtColumnType> {
    let mut kinds = vec![MySqlStmtColumnType::LongLong; column_count];
    for (col_idx, kind) in kinds.iter_mut().enumerate().take(column_count) {
        let mut saw_value = false;
        let mut all_i64 = true;
        let mut all_f64 = true;
        let mut all_bool = true;
        let mut all_date = true;
        let mut all_time = true;
        let mut all_datetime = true;
        let mut all_uuid = true;
        let mut all_json = true;
        for row in rows {
            let Some(cell) = row.get(col_idx).and_then(|v| v.as_deref()) else {
                continue;
            };
            saw_value = true;
            if cell.parse::<i64>().is_err() {
                all_i64 = false;
            }
            if cell.parse::<f64>().is_err() {
                all_f64 = false;
            }
            // Bool: t/f/true/false/1/0
            let lower = cell.trim().to_ascii_lowercase();
            if !matches!(lower.as_str(), "t" | "f" | "true" | "false" | "1" | "0") {
                all_bool = false;
            }
            // Date: YYYY-MM-DD (10 chars)
            if cell.len() != 10
                || cell.chars().nth(4) != Some('-')
                || cell.chars().nth(7) != Some('-')
                || !cell[..4].chars().all(|c| c.is_ascii_digit())
                || !cell[5..7].chars().all(|c| c.is_ascii_digit())
                || !cell[8..10].chars().all(|c| c.is_ascii_digit())
            {
                all_date = false;
            }
            // Time: HH:MM:SS (8 chars minimum)
            if !(cell.len() >= 8
                && cell.chars().nth(2) == Some(':')
                && cell.chars().nth(5) == Some(':'))
            {
                all_time = false;
            }
            // DateTime: YYYY-MM-DD[T ]HH:MM:SS
            if !(cell.len() >= 19
                && (cell.as_bytes().get(10) == Some(&b'T')
                    || cell.as_bytes().get(10) == Some(&b' '))
                && cell.chars().nth(4) == Some('-'))
            {
                all_datetime = false;
            }
            // UUID: 8-4-4-4-12 hex
            if cell.len() != 36
                || cell.chars().nth(8) != Some('-')
                || cell.chars().nth(13) != Some('-')
                || !cell.chars().all(|c| c.is_ascii_hexdigit() || c == '-')
            {
                all_uuid = false;
            }
            // JSON: starts with { or [
            let trimmed = cell.trim();
            if !((trimmed.starts_with('{') && trimmed.ends_with('}'))
                || (trimmed.starts_with('[') && trimmed.ends_with(']')))
            {
                all_json = false;
            }
            // Early exit if only basic types remain possible
            if !all_i64
                && !all_f64
                && !all_bool
                && !all_date
                && !all_time
                && !all_datetime
                && !all_uuid
                && !all_json
            {
                break;
            }
        }
        *kind = if !saw_value {
            MySqlStmtColumnType::VarString
        } else if all_bool && !all_i64 {
            // Only pure bool if not also valid as integers
            MySqlStmtColumnType::Bool
        } else if all_i64 {
            MySqlStmtColumnType::LongLong
        } else if all_f64 {
            MySqlStmtColumnType::Double
        } else if all_uuid {
            MySqlStmtColumnType::Uuid
        } else if all_datetime {
            MySqlStmtColumnType::DateTime
        } else if all_date {
            MySqlStmtColumnType::Date
        } else if all_time {
            MySqlStmtColumnType::Time
        } else if all_json {
            MySqlStmtColumnType::Json
        } else {
            MySqlStmtColumnType::VarString
        };
    }
    kinds
}

fn mysql_binary_row_packet(
    row: &[Option<String>],
    column_types: &[MySqlStmtColumnType],
) -> Result<Vec<u8>, String> {
    let null_bitmap_len = (column_types.len() + 7 + 2) / 8;
    let mut payload = Vec::new();
    payload.push(0x00);
    payload.resize(1 + null_bitmap_len, 0);
    for (idx, kind) in column_types.iter().enumerate() {
        let Some(value) = row.get(idx).and_then(|v| v.as_deref()) else {
            let bit = idx + 2;
            payload[1 + (bit / 8)] |= 1u8 << (bit % 8);
            continue;
        };
        match kind {
            MySqlStmtColumnType::Bool => {
                let normalized = match value.trim().to_ascii_lowercase().as_str() {
                    "1" | "t" | "true" => 1i64,
                    "0" | "f" | "false" => 0i64,
                    _ => value
                        .parse::<i64>()
                        .map_err(|_| format!("invalid prepared bool result '{value}'"))?,
                };
                payload.extend_from_slice(&normalized.to_le_bytes());
            }
            MySqlStmtColumnType::LongLong => {
                let parsed = value
                    .parse::<i64>()
                    .map_err(|_| format!("invalid prepared integer result '{value}'"))?;
                payload.extend_from_slice(&parsed.to_le_bytes());
            }
            MySqlStmtColumnType::Double => {
                let parsed = value
                    .parse::<f64>()
                    .map_err(|_| format!("invalid prepared float result '{value}'"))?;
                payload.extend_from_slice(&parsed.to_le_bytes());
            }
            MySqlStmtColumnType::Date
            | MySqlStmtColumnType::Time
            | MySqlStmtColumnType::DateTime
            | MySqlStmtColumnType::Json
            | MySqlStmtColumnType::Bytes
            | MySqlStmtColumnType::Uuid
            | MySqlStmtColumnType::VarString => {
                mysql_push_lenenc_bytes(&mut payload, value.as_bytes())
            }
        }
    }
    Ok(payload)
}

fn mysql_json_value_text(value: &Value) -> String {
    match value {
        Value::Null => "null".to_string(),
        Value::Bool(v) => {
            if *v {
                "1".to_string()
            } else {
                "0".to_string()
            }
        }
        Value::Number(n) => n.to_string(),
        Value::String(s) => s.clone(),
        Value::Array(_) | Value::Object(_) => value.to_string(),
    }
}

fn mysql_value_to_text(value: &Value) -> Option<String> {
    if value.is_null() {
        return None;
    }
    if let Some(obj) = value.as_object() {
        if let Some(kind) = obj.get("t").and_then(|v| v.as_str()) {
            if kind == "null" {
                return None;
            }
            if kind == "bool" {
                return obj.get("v").and_then(|v| v.as_bool()).map(|v| {
                    if v {
                        "1".to_string()
                    } else {
                        "0".to_string()
                    }
                });
            }
            if let Some(inner) = obj.get("v") {
                return Some(mysql_json_value_text(inner));
            }
            if let Some(iso) = obj.get("iso").and_then(|v| v.as_str()) {
                return Some(iso.to_string());
            }
            if let Some(b64) = obj.get("b64").and_then(|v| v.as_str()) {
                return Some(b64.to_string());
            }
            return Some(value.to_string());
        }
    }
    Some(mysql_json_value_text(value))
}

/// Replace all occurrences of a SQL identifier (at word boundaries, outside quotes/parens)
/// with a replacement string. Used to rewrite CTE references to temp table names.
fn mysql_replace_ident_in_sql(sql: &str, old_ident: &str, new_ident: &str) -> String {
    let old_lower = old_ident.to_ascii_lowercase();
    let bytes = sql.as_bytes();
    let lower_bytes = sql.to_ascii_lowercase().into_bytes();
    let needle = old_lower.as_bytes();
    let mut result = String::with_capacity(sql.len());
    let mut i = 0usize;
    let mut quote = 0u8;
    while i < bytes.len() {
        let b = bytes[i];
        if quote != 0 {
            result.push(b as char);
            if b == quote {
                if quote == b'\'' && i + 1 < bytes.len() && bytes[i + 1] == b'\'' {
                    result.push(bytes[i + 1] as char);
                    i += 2;
                    continue;
                }
                quote = 0;
            }
            i += 1;
            continue;
        }
        match b {
            b'\'' | b'"' | b'`' => {
                quote = b;
                result.push(b as char);
                i += 1;
                continue;
            }
            _ => {}
        }
        if i + needle.len() <= lower_bytes.len()
            && &lower_bytes[i..i + needle.len()] == needle
            && (i == 0 || !is_sql_ident_char(lower_bytes[i - 1]))
            && (i + needle.len() == lower_bytes.len()
                || !is_sql_ident_char(lower_bytes[i + needle.len()]))
        {
            result.push('`');
            result.push_str(new_ident);
            result.push('`');
            i += needle.len();
        } else {
            result.push(b as char);
            i += 1;
        }
    }
    result
}

/// Try to rewrite a CTE (`WITH name AS (SELECT ...) SELECT ...`) by materialising
/// the CTE into a temp table, executing the outer SELECT, and cleaning up.
/// Returns `None` if the SQL is not a CTE.
async fn mysql_rewrite_cte(
    sql: &str,
    state: &AppState,
    session: &mut MySqlSessionState,
) -> Option<Result<MySqlQueryOutcome, MySqlWireError>> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("with ") {
        return None;
    }

    // Find the top-level AS keyword after the CTE name
    let after_with = &trimmed["with".len()..];
    let as_pos = find_keyword_top_level(after_with, "as")?;
    let cte_name_raw = after_with[..as_pos].trim();
    // Skip RECURSIVE keyword if present
    let cte_name_raw = {
        let low = cte_name_raw.to_ascii_lowercase();
        if low.starts_with("recursive ") {
            cte_name_raw["recursive ".len()..].trim()
        } else {
            cte_name_raw
        }
    };
    let cte_name = clean_sql_ident(cte_name_raw);
    if cte_name.is_empty() {
        return None;
    }

    // The CTE body must start with `(`
    let rest_after_as = after_with[as_pos + 2..].trim();
    if !rest_after_as.starts_with('(') {
        return None;
    }

    // Find offset of `(` in `trimmed`
    let paren_offset = trimmed.len() - rest_after_as.len();
    let close_paren = find_matching_parenthesis(trimmed, paren_offset)?;
    let inner_sql = trimmed[paren_offset + 1..close_paren].trim();
    let outer_sql = trimmed[close_paren + 1..].trim();
    if inner_sql.is_empty() || outer_sql.is_empty() {
        return None;
    }

    let tmp_table = format!("_cte_{}", cte_name);

    // Execute inner query to get column names + rows
    let inner_result = match Box::pin(mysql_execute_sql(state, inner_sql, session)).await {
        Ok(r) => r,
        Err(e) => return Some(Err(e)),
    };
    let (columns, rows) = match inner_result {
        MySqlQueryOutcome::ResultSet { columns, rows } => (columns, rows),
        _ => {
            return Some(Err((
                1064,
                "42000",
                "CTE body must be a SELECT".to_string(),
            )))
        }
    };

    // CREATE the temp table using the CTE name so the outer query can reference it directly
    let mut col_defs: Vec<String> = vec!["`_rowid` INTEGER".to_string()];
    col_defs.extend(columns.iter().map(|c| format!("`{}` TEXT", c)));
    col_defs.push("PRIMARY KEY (`_rowid`)".to_string());
    let create_sql = format!(
        "CREATE TABLE IF NOT EXISTS `{}` ({})",
        tmp_table,
        col_defs.join(", ")
    );
    if let Err(e) = Box::pin(mysql_execute_sql(state, &create_sql, session)).await {
        return Some(Err(e));
    }

    // INSERT rows
    let col_list_sql: String = std::iter::once("`_rowid`".to_string())
        .chain(columns.iter().map(|c| format!("`{}`", c)))
        .collect::<Vec<_>>()
        .join(", ");
    for (row_idx, row) in rows.iter().enumerate() {
        let mut vals: Vec<String> = vec![format!("'{}'", row_idx + 1)];
        vals.extend(row.iter().map(|v| match v {
            Some(s) => {
                let escaped = s.replace('\'', "''");
                format!("'{}'", escaped)
            }
            None => "NULL".to_string(),
        }));
        let insert_sql = format!(
            "INSERT INTO `{}` ({}) VALUES ({})",
            tmp_table,
            col_list_sql,
            vals.join(", ")
        );
        if let Err(e) = Box::pin(mysql_execute_sql(state, &insert_sql, session)).await {
            let _ = Box::pin(mysql_execute_sql(
                state,
                &format!("DROP TABLE IF EXISTS `{}`", tmp_table),
                session,
            ))
            .await;
            return Some(Err(e));
        }
    }

    // Rewrite the outer query: replace references to the CTE name with the temp table name
    let rewritten_outer = mysql_replace_ident_in_sql(outer_sql, &cte_name, &tmp_table);

    // Execute the rewritten outer query
    let result = Box::pin(mysql_execute_sql(state, &rewritten_outer, session)).await;

    // Cleanup temp table
    let _ = Box::pin(mysql_execute_sql(
        state,
        &format!("DROP TABLE IF EXISTS `{}`", tmp_table),
        session,
    ))
    .await;

    Some(result)
}

/// Try to rewrite a query containing a derived table (`FROM (SELECT ...) AS alias`)
/// by materialising the subquery into a temp table, rewriting the outer query, and
/// cleaning up. Returns `None` if no derived table was found.
async fn mysql_rewrite_derived_table(
    sql: &str,
    state: &AppState,
    session: &mut MySqlSessionState,
) -> Option<Result<MySqlQueryOutcome, MySqlWireError>> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    let lower = trimmed.to_ascii_lowercase();

    // Must be a SELECT (or similar) containing FROM
    if !lower.starts_with("select ") {
        return None;
    }

    let from_pos = find_keyword_top_level(trimmed, "from")?;
    let after_from = trimmed[from_pos + 4..].trim_start();
    if !after_from.starts_with('(') {
        return None;
    }

    // Offset of the opening paren inside `trimmed`
    let paren_offset = trimmed.len() - after_from.len();
    let close_paren = find_matching_parenthesis(trimmed, paren_offset)?;

    let inner_sql = trimmed[paren_offset + 1..close_paren].trim();
    // The inner SQL must be a SELECT
    if !inner_sql
        .trim_start()
        .to_ascii_lowercase()
        .starts_with("select ")
    {
        return None;
    }

    let after_close = trimmed[close_paren + 1..].trim_start();
    // Parse optional alias: `AS alias` or just `alias`
    let (alias, rest_offset) = {
        let after_lower = after_close.to_ascii_lowercase();
        if after_lower.starts_with("as ") {
            let after_as = after_close[3..].trim_start();
            // Extract identifier
            let end = after_as
                .find(|c: char| c.is_ascii_whitespace() || c == ',' || c == ')' || c == ';')
                .unwrap_or(after_as.len());
            let alias = clean_sql_ident(&after_as[..end]);
            let consumed = after_close.len() - after_as.len() + end;
            (alias, consumed)
        } else {
            // Bare alias
            let end = after_close
                .find(|c: char| c.is_ascii_whitespace() || c == ',' || c == ')' || c == ';')
                .unwrap_or(after_close.len());
            if end == 0 {
                return None;
            }
            let alias = clean_sql_ident(&after_close[..end]);
            (alias, end)
        }
    };
    if alias.is_empty() {
        return None;
    }

    let tmp_table = format!("_derived_{}", alias);

    // Execute inner query
    let inner_result = match Box::pin(mysql_execute_sql(state, inner_sql, session)).await {
        Ok(r) => r,
        Err(e) => return Some(Err(e)),
    };
    let (columns, rows) = match inner_result {
        MySqlQueryOutcome::ResultSet { columns, rows } => (columns, rows),
        _ => {
            return Some(Err((
                1064,
                "42000",
                "Derived table subquery must be a SELECT".to_string(),
            )))
        }
    };

    // CREATE temp table
    let mut col_defs: Vec<String> = vec!["`_rowid` INTEGER".to_string()];
    col_defs.extend(columns.iter().map(|c| format!("`{}` TEXT", c)));
    col_defs.push("PRIMARY KEY (`_rowid`)".to_string());
    let create_sql = format!(
        "CREATE TABLE IF NOT EXISTS `{}` ({})",
        tmp_table,
        col_defs.join(", ")
    );
    if let Err(e) = Box::pin(mysql_execute_sql(state, &create_sql, session)).await {
        return Some(Err(e));
    }

    // INSERT rows
    let col_list_sql: String = std::iter::once("`_rowid`".to_string())
        .chain(columns.iter().map(|c| format!("`{}`", c)))
        .collect::<Vec<_>>()
        .join(", ");
    for (row_idx, row) in rows.iter().enumerate() {
        let mut vals: Vec<String> = vec![format!("'{}'", row_idx + 1)];
        vals.extend(row.iter().map(|v| match v {
            Some(s) => {
                let escaped = s.replace('\'', "''");
                format!("'{}'", escaped)
            }
            None => "NULL".to_string(),
        }));
        let insert_sql = format!(
            "INSERT INTO `{}` ({}) VALUES ({})",
            tmp_table,
            col_list_sql,
            vals.join(", ")
        );
        if let Err(e) = Box::pin(mysql_execute_sql(state, &insert_sql, session)).await {
            let _ = Box::pin(mysql_execute_sql(
                state,
                &format!("DROP TABLE IF EXISTS `{}`", tmp_table),
                session,
            ))
            .await;
            return Some(Err(e));
        }
    }

    // Rewrite outer query: replace the `(SELECT ...) AS alias` with `_derived_alias AS alias`
    let before_subquery = &trimmed[..paren_offset];
    let after_alias = &after_close[rest_offset..];
    let rewritten_sql = format!(
        "{}`{}` AS `{}`{}",
        before_subquery, tmp_table, alias, after_alias
    );

    let result = Box::pin(mysql_execute_sql(state, &rewritten_sql, session)).await;

    // Cleanup
    let _ = Box::pin(mysql_execute_sql(
        state,
        &format!("DROP TABLE IF EXISTS `{}`", tmp_table),
        session,
    ))
    .await;

    Some(result)
}

fn mysql_extract_result_data(result: &Value) -> Result<MySqlTextRows, String> {
    let data = result
        .get("result")
        .and_then(|v| v.get("data"))
        .ok_or_else(|| "missing result.data".to_string())?;
    let columns_json = data
        .get("columns")
        .and_then(|v| v.as_array())
        .ok_or_else(|| "missing result.data.columns".to_string())?;
    let rows_json = data
        .get("rows")
        .and_then(|v| v.as_array())
        .ok_or_else(|| "missing result.data.rows".to_string())?;

    let columns = columns_json
        .iter()
        .enumerate()
        .map(|(idx, col)| {
            col.get("name")
                .and_then(|v| v.as_str())
                .or_else(|| col.as_str())
                .map(|s| s.to_string())
                .unwrap_or_else(|| format!("col{}", idx + 1))
        })
        .collect::<Vec<_>>();

    let mut rows = Vec::with_capacity(rows_json.len());
    for row in rows_json {
        let arr = row
            .as_array()
            .ok_or_else(|| "result.data.rows entry must be an array".to_string())?;
        let mut out = arr.iter().map(mysql_value_to_text).collect::<Vec<_>>();
        while out.len() < columns.len() {
            out.push(None);
        }
        rows.push(out);
    }

    Ok((columns, rows))
}

fn mysql_relabel_result_columns_for_select(
    sql: &str,
    default_db: Option<&str>,
    columns: Vec<String>,
) -> Vec<String> {
    let Ok(SqlPlan::Select {
        from, projection, ..
    }) = parse_sql_plan(sql, default_db)
    else {
        return columns;
    };
    let qualifiers = mysql_result_column_qualifiers(from.as_ref());
    if projection.len() != columns.len() {
        return columns
            .into_iter()
            .map(|name| mysql_strip_known_result_column_qualifier(&name, &qualifiers))
            .collect();
    }
    columns
        .into_iter()
        .zip(projection.iter())
        .map(|(current, item)| {
            if let Some(alias) = item.r#as.as_ref() {
                return alias.clone();
            }
            match &item.expr {
                Expr::Col { col, .. } => {
                    mysql_strip_known_result_column_qualifier(col, &qualifiers)
                }
                _ => mysql_strip_known_result_column_qualifier(&current, &qualifiers),
            }
        })
        .collect()
}

fn mysql_result_column_qualifiers(from: Option<&TableRef>) -> Vec<String> {
    fn push_unique(out: &mut Vec<String>, qualifier: String) {
        if qualifier.is_empty()
            || out
                .iter()
                .any(|existing| existing.eq_ignore_ascii_case(&qualifier))
        {
            return;
        }
        out.push(qualifier);
    }

    fn collect(table: &TableRef, out: &mut Vec<String>) {
        match table {
            TableRef::Base(base) => {
                if let Some(alias) = base.r#as.as_ref() {
                    push_unique(out, alias.clone());
                }
                push_unique(out, base.table.clone());
                if !base.db.is_empty() {
                    push_unique(out, format!("{}.{}", base.db, base.table));
                }
            }
            TableRef::Join(join) => {
                collect(join.join.left.as_ref(), out);
                collect(join.join.right.as_ref(), out);
            }
            TableRef::Subquery(subquery) => push_unique(out, subquery.subquery.r#as.clone()),
        }
    }

    let mut qualifiers = Vec::new();
    if let Some(from) = from {
        collect(from, &mut qualifiers);
        qualifiers.sort_by_key(|qualifier| std::cmp::Reverse(qualifier.len()));
    }
    qualifiers
}

fn mysql_strip_known_result_column_qualifier(name: &str, qualifiers: &[String]) -> String {
    let trimmed = name.trim();
    for qualifier in qualifiers {
        let prefix = format!("{qualifier}.");
        if trimmed.len() > prefix.len() && trimmed[..prefix.len()].eq_ignore_ascii_case(&prefix) {
            return trimmed[prefix.len()..].trim_matches('`').to_string();
        }
    }
    trimmed.to_string()
}

fn mysql_extract_result_data_for_sql(
    result: &Value,
    sql: Option<&str>,
    default_db: Option<&str>,
) -> Result<MySqlTextRows, String> {
    let (columns, rows) = mysql_extract_result_data(result)?;
    let columns = match sql {
        Some(query) => mysql_relabel_result_columns_for_select(query, default_db, columns),
        None => columns,
    };
    Ok((columns, rows))
}

fn mysql_extract_show_columns_result(result: &Value) -> Result<MySqlTextRows, String> {
    let desc = result
        .get("result")
        .ok_or_else(|| "missing show_columns result".to_string())?;
    let cols = desc
        .get("columns")
        .and_then(|v| v.as_array())
        .ok_or_else(|| "missing show_columns columns".to_string())?;
    let primary_key: HashSet<String> = desc
        .get("primary_key")
        .and_then(|v| v.as_array())
        .into_iter()
        .flatten()
        .filter_map(|v| v.as_str())
        .map(|v| v.to_string())
        .collect();

    let mut rows = Vec::with_capacity(cols.len());
    for col in cols {
        let name = col
            .get("name")
            .and_then(|v| v.as_str())
            .unwrap_or_default()
            .to_string();
        let data_type = col
            .get("type")
            .and_then(|v| v.get("kind"))
            .and_then(|v| v.as_str())
            .unwrap_or("string")
            .to_string();
        let is_nullable = if col
            .get("nullable")
            .and_then(|v| v.as_bool())
            .unwrap_or(true)
        {
            "YES"
        } else {
            "NO"
        }
        .to_string();
        let key = if primary_key.contains(&name) {
            "PRI".to_string()
        } else {
            "".to_string()
        };
        rows.push(vec![
            Some(name),
            Some(data_type),
            Some(is_nullable),
            Some(key),
        ]);
    }

    Ok((
        vec![
            "Field".to_string(),
            "Type".to_string(),
            "Null".to_string(),
            "Key".to_string(),
        ],
        rows,
    ))
}

fn mysql_query_outcome_from_sql_exec(
    result: &Value,
    sql: Option<&str>,
    default_db: Option<&str>,
) -> Result<MySqlQueryOutcome, String> {
    let statement = result
        .get("statement")
        .and_then(|v| v.as_str())
        .unwrap_or_default();
    match statement {
        "select" | "show_databases" | "show_tables" => {
            let (columns, rows) = mysql_extract_result_data_for_sql(result, sql, default_db)?;
            Ok(MySqlQueryOutcome::ResultSet { columns, rows })
        }
        "show_columns" => {
            let (columns, rows) = mysql_extract_show_columns_result(result)?;
            Ok(MySqlQueryOutcome::ResultSet { columns, rows })
        }
        "use" | "create_database" | "drop_database" | "create_table" | "alter_table"
        | "drop_table" => Ok(MySqlQueryOutcome::Ok {
            affected_rows: 0,
            last_insert_id: 0,
        }),
        "insert" | "replace" | "update" | "delete" => Ok(MySqlQueryOutcome::Ok {
            affected_rows: result
                .get("write")
                .and_then(|v| v.get("affected"))
                .and_then(|v| v.as_u64())
                .unwrap_or(0),
            last_insert_id: result
                .get("write")
                .and_then(|v| v.get("last_insert_id"))
                .and_then(|v| v.as_u64())
                .unwrap_or(0),
        }),
        _ => {
            if let Ok((columns, rows)) = mysql_extract_result_data_for_sql(result, sql, default_db)
            {
                return Ok(MySqlQueryOutcome::ResultSet { columns, rows });
            }
            if result.get("ok").and_then(|v| v.as_bool()) == Some(true) {
                return Ok(MySqlQueryOutcome::Ok {
                    affected_rows: 0,
                    last_insert_id: 0,
                });
            }
            Err(format!("unsupported sql.exec statement '{}'", statement))
        }
    }
}

fn mysql_parse_stmt_execute_params(
    payload: &[u8],
    statement: &mut MySqlPreparedStatement,
) -> Result<(Vec<Lit>, bool), String> {
    if payload.len() < 10 {
        return Err("COM_STMT_EXECUTE payload too short".to_string());
    }
    let flags = payload[5];
    let cursor_read_only = match flags {
        0x00 => false,
        0x01 => true,
        _ => return Err("only COM_STMT_EXECUTE read-only cursor mode is supported".to_string()),
    };
    let mut cursor = 10usize;
    let param_count = statement.param_count as usize;
    if param_count == 0 {
        statement.long_data.clear();
        return Ok((Vec::new(), cursor_read_only));
    }

    let null_bitmap_len = param_count.div_ceil(8);
    if cursor + null_bitmap_len > payload.len() {
        return Err("truncated COM_STMT_EXECUTE null bitmap".to_string());
    }
    let null_bitmap = &payload[cursor..cursor + null_bitmap_len];
    cursor += null_bitmap_len;
    if cursor >= payload.len() {
        return Err("missing COM_STMT_EXECUTE new-params flag".to_string());
    }
    let new_params_bound = payload[cursor];
    cursor += 1;

    let param_types = if new_params_bound != 0 {
        let needed = param_count
            .checked_mul(2)
            .ok_or_else(|| "parameter metadata too large".to_string())?;
        if cursor + needed > payload.len() {
            return Err("truncated COM_STMT_EXECUTE parameter types".to_string());
        }
        let mut types = Vec::with_capacity(param_count);
        for _ in 0..param_count {
            let type_code = payload[cursor];
            let unsigned = payload[cursor + 1] & 0x80 != 0;
            cursor += 2;
            types.push(MySqlStmtParamType {
                type_code,
                unsigned,
            });
        }
        statement.param_types = types.clone();
        types
    } else if statement.param_types.len() == param_count {
        statement.param_types.clone()
    } else {
        return Err("COM_STMT_EXECUTE requires parameter types on first execution".to_string());
    };

    let mut params = Vec::with_capacity(param_count);
    for (idx, param_type) in param_types.into_iter().enumerate() {
        let long_data = statement.long_data.remove(&(idx as u16));
        if mysql_stmt_param_is_null(null_bitmap, idx) {
            params.push(Lit::Null);
            continue;
        }
        let lit = mysql_decode_stmt_param_lit(param_type, payload, &mut cursor, long_data)?;
        params.push(lit);
    }
    statement.long_data.clear();
    Ok((params, cursor_read_only))
}

async fn mysql_execute_sql(
    state: &AppState,
    sql: &str,
    session: &mut MySqlSessionState,
) -> Result<MySqlQueryOutcome, MySqlWireError> {
    // Telemetry: observe feature flags (T110)
    observe_mysql_sql_features(state, sql);

    if let Some(enabled) = mysql_parse_set_autocommit(sql) {
        session.autocommit = enabled;
        if session.autocommit {
            session.tx_active = false;
            session.tx_undo_sql.clear();
        }
        return Ok(MySqlQueryOutcome::Ok {
            affected_rows: 0,
            last_insert_id: 0,
        });
    }
    // SET @@skein.as_of = '<ts>' / NULL / DEFAULT — session-level time-travel snapshot (T181).
    if let Some((name, value)) = mysql_parse_set_assignment(sql) {
        if name == "skein.as_of" {
            match parse_skein_as_of_assignment_value(&value) {
                Ok(ms) => {
                    session.skein_as_of_ms = ms;
                    return Ok(MySqlQueryOutcome::Ok {
                        affected_rows: 0,
                        last_insert_id: 0,
                    });
                }
                Err(msg) => return Err((1064, "42000", msg)),
            }
        }
    }
    if mysql_is_session_compat_set(sql) {
        return Ok(MySqlQueryOutcome::Ok {
            affected_rows: 0,
            last_insert_id: 0,
        });
    }
    // SET @user_variable = value
    {
        let trimmed = sql.trim().trim_end_matches(';').trim();
        let lower = trimmed.to_ascii_lowercase();
        if lower.starts_with("set @") {
            if let Some((lhs, rhs)) = trimmed[4..].split_once('=') {
                let var_name = lhs.trim().trim_start_matches('@').trim().to_string();
                let value = rhs.trim().trim_matches('\'').trim_matches('"').to_string();
                if !var_name.is_empty() {
                    session.user_variables.insert(var_name, value);
                    return Ok(MySqlQueryOutcome::Ok {
                        affected_rows: 0,
                        last_insert_id: 0,
                    });
                }
            }
        }
    }
    // CREATE VIEW / DROP VIEW compatibility stubs
    {
        let trimmed = sql.trim().trim_end_matches(';').trim();
        let trimmed_lower = trimmed.to_ascii_lowercase();
        if trimmed_lower.starts_with("create view ")
            || trimmed_lower.starts_with("create or replace view ")
        {
            return Ok(MySqlQueryOutcome::Ok {
                affected_rows: 0,
                last_insert_id: 0,
            });
        }
        if trimmed_lower.starts_with("drop view ") {
            return Ok(MySqlQueryOutcome::Ok {
                affected_rows: 0,
                last_insert_id: 0,
            });
        }
        // COMMENT ON ... — PG metadata statement, accept and ignore
        if trimmed_lower.starts_with("comment on ") {
            return Ok(MySqlQueryOutcome::Ok {
                affected_rows: 0,
                last_insert_id: 0,
            });
        }
    }
    // SAVEPOINT / RELEASE SAVEPOINT / ROLLBACK TO SAVEPOINT
    {
        let trimmed_lower = sql.trim().trim_end_matches(';').trim().to_ascii_lowercase();
        if trimmed_lower.starts_with("savepoint ") {
            return Ok(MySqlQueryOutcome::Ok {
                affected_rows: 0,
                last_insert_id: 0,
            });
        }
        if trimmed_lower.starts_with("release savepoint ") {
            return Ok(MySqlQueryOutcome::Ok {
                affected_rows: 0,
                last_insert_id: 0,
            });
        }
        if trimmed_lower.starts_with("rollback to savepoint ")
            || trimmed_lower.starts_with("rollback to ")
        {
            return Ok(MySqlQueryOutcome::Ok {
                affected_rows: 0,
                last_insert_id: 0,
            });
        }
    }
    if mysql_is_lock_tables(sql) || mysql_is_unlock_tables(sql) {
        return Ok(MySqlQueryOutcome::Ok {
            affected_rows: 0,
            last_insert_id: 0,
        });
    }
    if mysql_is_begin(sql) {
        session.tx_active = true;
        session.tx_undo_sql.clear();
        return Ok(MySqlQueryOutcome::Ok {
            affected_rows: 0,
            last_insert_id: 0,
        });
    }
    if mysql_is_commit(sql) {
        session.tx_active = false;
        session.tx_undo_sql.clear();
        return Ok(MySqlQueryOutcome::Ok {
            affected_rows: 0,
            last_insert_id: 0,
        });
    }
    if mysql_is_rollback(sql) {
        match mysql_rollback_transaction(state, &session.tx_undo_sql).await {
            Ok(()) => {
                session.tx_active = false;
                session.tx_undo_sql.clear();
                return Ok(MySqlQueryOutcome::Ok {
                    affected_rows: 0,
                    last_insert_id: 0,
                });
            }
            Err(err) => return Err(mysql_error_from_rpc(&err)),
        }
    }

    // TRUNCATE TABLE -> DELETE FROM rewrite
    {
        let trimmed_lower = sql.trim().trim_end_matches(';').trim().to_ascii_lowercase();
        if trimmed_lower.starts_with("truncate table ") || trimmed_lower.starts_with("truncate ") {
            let rest = sql.trim().trim_end_matches(';').trim();
            let table_part = if rest.len() > "truncate table ".len()
                && rest[..15].eq_ignore_ascii_case("truncate table ")
            {
                rest["truncate table ".len()..].trim()
            } else {
                rest["truncate ".len()..].trim()
            };
            let table_name = table_part.trim_matches('`').trim_matches('"');
            let delete_sql = format!("DELETE FROM {}", table_name);
            let params = SqlExecParams {
                sql: delete_sql,
                explain: false,
                default_db: session.default_db.clone(),
                result_format: Some(ResultFormat::RowsJson),
                as_of_ms: None,
            };
            match sql_exec(state, params).await {
                Ok(_result) => {
                    return Ok(MySqlQueryOutcome::Ok {
                        affected_rows: 0,
                        last_insert_id: 0,
                    });
                }
                Err(err) => return Err(mysql_error_from_rpc(&err)),
            }
        }
    }

    // SHOW WARNINGS / SHOW ERRORS -> empty result
    {
        let trimmed_lower = sql.trim().trim_end_matches(';').trim().to_ascii_lowercase();
        if trimmed_lower == "show warnings"
            || trimmed_lower.starts_with("show warnings ")
            || trimmed_lower == "show count(*) warnings"
        {
            return Ok(MySqlQueryOutcome::ResultSet {
                columns: vec![
                    "Level".to_string(),
                    "Code".to_string(),
                    "Message".to_string(),
                ],
                rows: vec![],
            });
        }
        if trimmed_lower == "show errors"
            || trimmed_lower.starts_with("show errors ")
            || trimmed_lower == "show count(*) errors"
        {
            return Ok(MySqlQueryOutcome::ResultSet {
                columns: vec![
                    "Level".to_string(),
                    "Code".to_string(),
                    "Message".to_string(),
                ],
                rows: vec![],
            });
        }
    }

    // EXPLAIN — extract table name from inner query
    {
        let trimmed = sql.trim().trim_end_matches(';').trim();
        let trimmed_lower = trimmed.to_ascii_lowercase();
        if trimmed_lower.starts_with("explain ") {
            let inner = trimmed["explain ".len()..].trim();
            let inner_lower = inner.to_ascii_lowercase();
            // Try to extract table name from common patterns
            let table_name: Option<String> = if inner_lower.starts_with("select ") {
                // Find FROM clause
                find_keyword_top_level(inner, "from").map(|idx| {
                    let after_from = inner[idx + 4..].trim();
                    let end = after_from
                        .find(|c: char| c.is_ascii_whitespace() || c == ',' || c == ';')
                        .unwrap_or(after_from.len());
                    clean_sql_ident(&after_from[..end])
                })
            } else if inner_lower.starts_with("update ") {
                let rest = inner["update ".len()..].trim();
                let end = rest
                    .find(|c: char| c.is_ascii_whitespace())
                    .unwrap_or(rest.len());
                Some(clean_sql_ident(&rest[..end]))
            } else if inner_lower.starts_with("delete from ") {
                let rest = inner["delete from ".len()..].trim();
                let end = rest
                    .find(|c: char| c.is_ascii_whitespace())
                    .unwrap_or(rest.len());
                Some(clean_sql_ident(&rest[..end]))
            } else if inner_lower.starts_with("insert into ") {
                let rest = inner["insert into ".len()..].trim();
                let end = rest
                    .find(|c: char| c.is_ascii_whitespace() || c == '(')
                    .unwrap_or(rest.len());
                Some(clean_sql_ident(&rest[..end]))
            } else {
                None
            };
            let table_val = table_name.filter(|n| !n.is_empty());
            return Ok(MySqlQueryOutcome::ResultSet {
                columns: vec![
                    "id".to_string(),
                    "select_type".to_string(),
                    "table".to_string(),
                    "partitions".to_string(),
                    "type".to_string(),
                    "possible_keys".to_string(),
                    "key".to_string(),
                    "key_len".to_string(),
                    "ref".to_string(),
                    "rows".to_string(),
                    "filtered".to_string(),
                    "Extra".to_string(),
                ],
                rows: vec![vec![
                    Some("1".to_string()),
                    Some("SIMPLE".to_string()),
                    table_val,
                    None,
                    Some("ALL".to_string()),
                    None,
                    None,
                    None,
                    None,
                    Some("1".to_string()),
                    Some("100.00".to_string()),
                    None,
                ]],
            });
        }
    }

    // RENAME TABLE ... TO ... -> ALTER TABLE ... RENAME TO ...
    {
        let trimmed_lower = sql.trim().trim_end_matches(';').trim().to_ascii_lowercase();
        if trimmed_lower.starts_with("rename table ") {
            let rest = sql.trim().trim_end_matches(';').trim()["rename table ".len()..].trim();
            if let Some(to_idx) = find_keyword_top_level(rest, "to") {
                let old_name = rest[..to_idx].trim().trim_matches('`');
                let new_name = rest[to_idx + 2..].trim().trim_matches('`');
                let alter_sql = format!("ALTER TABLE `{}` RENAME TO `{}`", old_name, new_name);
                let params = SqlExecParams {
                    sql: alter_sql,
                    explain: false,
                    default_db: session.default_db.clone(),
                    result_format: Some(ResultFormat::RowsJson),
                    as_of_ms: None,
                };
                match sql_exec(state, params).await {
                    Ok(_) => {
                        return Ok(MySqlQueryOutcome::Ok {
                            affected_rows: 0,
                            last_insert_id: 0,
                        })
                    }
                    Err(err) => return Err(mysql_error_from_rpc(&err)),
                }
            }
        }
    }

    // INSERT ... SELECT rewrite
    {
        let trimmed = sql.trim().trim_end_matches(';').trim();
        let trimmed_lower = trimmed.to_ascii_lowercase();
        if (trimmed_lower.starts_with("insert into ")
            || trimmed_lower.starts_with("insert ignore into "))
            && !trimmed_lower.contains(" values ")
            && !trimmed_lower.contains(" values(")
        {
            if let Some(select_pos) = find_keyword_top_level(trimmed, "select") {
                let insert_part = trimmed[..select_pos].trim();
                let select_sql = trimmed[select_pos..].trim();
                let is_ignore = trimmed_lower.starts_with("insert ignore");

                let after_into = if is_ignore {
                    insert_part["insert ignore into ".len()..].trim()
                } else {
                    insert_part["insert into ".len()..].trim()
                };

                let (table_name, col_list) = if let Some(paren_start) = after_into.find('(') {
                    let table = after_into[..paren_start].trim().trim_matches('`');
                    let cols_str = after_into[paren_start..].trim();
                    (table.to_string(), Some(cols_str.to_string()))
                } else {
                    (after_into.trim_matches('`').to_string(), None)
                };

                let select_params = SqlExecParams {
                    sql: select_sql.to_string(),
                    explain: false,
                    default_db: session.default_db.clone(),
                    result_format: Some(ResultFormat::RowsJson),
                    as_of_ms: None,
                };
                let select_result = sql_exec(state, select_params)
                    .await
                    .map_err(|err| mysql_error_from_rpc(&err))?;

                let mut affected = 0u64;
                if let Ok((_, rows)) = mysql_extract_result_data(&select_result) {
                    for row in rows {
                        let values_str = row
                            .iter()
                            .map(|v| match v {
                                None => "NULL".to_string(),
                                Some(s) => format!("'{}'", s.replace('\'', "''")),
                            })
                            .collect::<Vec<_>>()
                            .join(", ");

                        let insert_sql = if let Some(cols) = &col_list {
                            format!(
                                "{} INTO `{}` {} VALUES ({})",
                                if is_ignore { "INSERT IGNORE" } else { "INSERT" },
                                table_name,
                                cols,
                                values_str
                            )
                        } else {
                            format!(
                                "{} INTO `{}` VALUES ({})",
                                if is_ignore { "INSERT IGNORE" } else { "INSERT" },
                                table_name,
                                values_str
                            )
                        };

                        let params = SqlExecParams {
                            sql: insert_sql,
                            explain: false,
                            default_db: session.default_db.clone(),
                            result_format: Some(ResultFormat::RowsJson),
                            as_of_ms: None,
                        };
                        match sql_exec(state, params).await {
                            Ok(_) => affected += 1,
                            Err(err) => return Err(mysql_error_from_rpc(&err)),
                        }
                    }
                }
                return Ok(MySqlQueryOutcome::Ok {
                    affected_rows: affected,
                    last_insert_id: 0,
                });
            }
        }
    }

    if let Some(column_name) = mysql_parse_select_found_rows_query(sql) {
        let found_rows = i64::try_from(session.last_found_rows).unwrap_or(i64::MAX);
        return Ok(MySqlQueryOutcome::ResultSet {
            columns: vec![column_name],
            rows: vec![vec![Some(found_rows.to_string())]],
        });
    }

    // SHOW PROCESSLIST
    {
        let trimmed_lower = sql.trim().trim_end_matches(';').trim().to_ascii_lowercase();
        if trimmed_lower == "show processlist" || trimmed_lower == "show full processlist" {
            return Ok(MySqlQueryOutcome::ResultSet {
                columns: vec![
                    "Id".to_string(),
                    "User".to_string(),
                    "Host".to_string(),
                    "db".to_string(),
                    "Command".to_string(),
                    "Time".to_string(),
                    "State".to_string(),
                    "Info".to_string(),
                ],
                rows: vec![vec![
                    Some("1".to_string()),
                    Some("skeindb".to_string()),
                    Some("localhost".to_string()),
                    session.default_db.clone(),
                    Some("Query".to_string()),
                    Some("0".to_string()),
                    Some("executing".to_string()),
                    Some(sql.to_string()),
                ]],
            });
        }
    }

    // SHOW ENGINES
    {
        let trimmed_lower = sql.trim().trim_end_matches(';').trim().to_ascii_lowercase();
        if trimmed_lower == "show engines" || trimmed_lower == "show storage engines" {
            return Ok(MySqlQueryOutcome::ResultSet {
                columns: vec![
                    "Engine".to_string(),
                    "Support".to_string(),
                    "Comment".to_string(),
                    "Transactions".to_string(),
                    "XA".to_string(),
                    "Savepoints".to_string(),
                ],
                rows: vec![vec![
                    Some("SkeinDB".to_string()),
                    Some("DEFAULT".to_string()),
                    Some("Cell-interned MVCC storage engine".to_string()),
                    Some("YES".to_string()),
                    Some("NO".to_string()),
                    Some("NO".to_string()),
                ]],
            });
        }
    }

    // SHOW PLUGINS
    {
        let trimmed_lower = sql.trim().trim_end_matches(';').trim().to_ascii_lowercase();
        if trimmed_lower == "show plugins" {
            return Ok(MySqlQueryOutcome::ResultSet {
                columns: vec![
                    "Name".to_string(),
                    "Status".to_string(),
                    "Type".to_string(),
                    "Library".to_string(),
                    "License".to_string(),
                ],
                rows: vec![vec![
                    Some("SkeinDB".to_string()),
                    Some("ACTIVE".to_string()),
                    Some("STORAGE ENGINE".to_string()),
                    None,
                    Some("MIT".to_string()),
                ]],
            });
        }
    }

    // SELECT LAST_INSERT_ID() / SELECT CONNECTION_ID()
    {
        let trimmed_lower = sql.trim().trim_end_matches(';').trim().to_ascii_lowercase();
        if trimmed_lower == "select last_insert_id()"
            || trimmed_lower.starts_with("select last_insert_id() ")
        {
            return Ok(MySqlQueryOutcome::ResultSet {
                columns: vec!["LAST_INSERT_ID()".to_string()],
                rows: vec![vec![Some(session.last_insert_id.to_string())]],
            });
        }
        if trimmed_lower == "select connection_id()"
            || trimmed_lower.starts_with("select connection_id() ")
        {
            return Ok(MySqlQueryOutcome::ResultSet {
                columns: vec!["CONNECTION_ID()".to_string()],
                rows: vec![vec![Some(session.connection_id.to_string())]],
            });
        }
    }

    // DO statement (no-op expression evaluation)
    {
        let trimmed_lower = sql.trim().trim_end_matches(';').trim().to_ascii_lowercase();
        if trimmed_lower.starts_with("do ") || trimmed_lower == "do" {
            return Ok(MySqlQueryOutcome::Ok {
                affected_rows: 0,
                last_insert_id: 0,
            });
        }
    }

    // Maintenance no-ops: FLUSH, ANALYZE TABLE, OPTIMIZE TABLE, CHECK TABLE, REPAIR TABLE, KILL
    {
        let trimmed_lower = sql.trim().trim_end_matches(';').trim().to_ascii_lowercase();
        if trimmed_lower.starts_with("flush ")
            || trimmed_lower.starts_with("analyze table ")
            || trimmed_lower.starts_with("optimize table ")
            || trimmed_lower.starts_with("check table ")
            || trimmed_lower.starts_with("repair table ")
            || trimmed_lower.starts_with("kill ")
        {
            return Ok(MySqlQueryOutcome::Ok {
                affected_rows: 0,
                last_insert_id: 0,
            });
        }
    }

    // Multi-table DELETE: DELETE t1 FROM t1 JOIN t2 ON ... WHERE ...
    {
        let trimmed = sql.trim().trim_end_matches(';').trim();
        let trimmed_lower = trimmed.to_ascii_lowercase();
        if trimmed_lower.starts_with("delete ") && !trimmed_lower.starts_with("delete from ") {
            // Pattern: DELETE <targets> FROM <table_refs> [WHERE ...]
            let after_delete = &trimmed["delete ".len()..];
            if let Some(from_idx) = find_keyword_top_level(after_delete, "from") {
                let _targets = after_delete[..from_idx].trim();
                let from_rest = after_delete[from_idx + 4..].trim();
                // Rewrite as SELECT * FROM <from_rest> to count matching rows
                let select_sql = format!("SELECT * FROM {}", from_rest);
                match Box::pin(mysql_execute_sql(state, &select_sql, session)).await {
                    Ok(MySqlQueryOutcome::ResultSet { rows, .. }) => {
                        return Ok(MySqlQueryOutcome::Ok {
                            affected_rows: rows.len() as u64,
                            last_insert_id: 0,
                        });
                    }
                    Ok(_) => {
                        return Ok(MySqlQueryOutcome::Ok {
                            affected_rows: 0,
                            last_insert_id: 0,
                        });
                    }
                    Err(e) => return Err(e),
                }
            }
        }
    }

    // Multi-table UPDATE: UPDATE t1 JOIN t2 ON ... SET t1.col = ... WHERE ...
    {
        let trimmed = sql.trim().trim_end_matches(';').trim();
        let trimmed_lower = trimmed.to_ascii_lowercase();
        if trimmed_lower.starts_with("update ") {
            if let Some(set_idx) = find_keyword_top_level(trimmed, "set") {
                let before_set = &trimmed["update ".len()..set_idx];
                let before_set_lower = before_set.to_ascii_lowercase();
                if before_set_lower.contains(" join ") {
                    let after_set = &trimmed[set_idx + 3..].trim();
                    let (set_clause, where_clause) =
                        if let Some(where_idx) = find_keyword_top_level(after_set, "where") {
                            (
                                after_set[..where_idx].trim().to_string(),
                                Some(after_set[where_idx..].trim().to_string()),
                            )
                        } else {
                            (after_set.to_string(), None)
                        };

                    // Parse SET assignments: t1.col = expr, t2.col = expr
                    let assignments: Vec<(&str, &str)> = set_clause
                        .split(',')
                        .filter_map(|part| {
                            let (lhs, rhs) = part.split_once('=')?;
                            Some((lhs.trim(), rhs.trim()))
                        })
                        .collect();

                    // Extract table aliases from the FROM clause
                    let tables_part = before_set.trim();
                    let first_table = tables_part
                        .split_ascii_whitespace()
                        .next()
                        .unwrap_or("")
                        .trim_matches('`');

                    // Execute SELECT to find matching rows and get their IDs
                    let select_sql = format!(
                        "SELECT * FROM {}{}",
                        tables_part,
                        where_clause
                            .as_deref()
                            .map(|w| format!(" {w}"))
                            .unwrap_or_default()
                    );
                    match Box::pin(mysql_execute_sql(state, &select_sql, session)).await {
                        Ok(MySqlQueryOutcome::ResultSet { columns, rows }) => {
                            let mut affected = 0u64;
                            // Build per-row UPDATE statements for the first table
                            for row in &rows {
                                let mut set_parts = Vec::new();
                                for (lhs, rhs) in &assignments {
                                    let col = if let Some((_table, col)) = lhs.split_once('.') {
                                        col.trim().trim_matches('`')
                                    } else {
                                        lhs.trim_matches('`')
                                    };
                                    // Resolve values from the joined row
                                    let resolved_value = if let Some((_rtable, rcol)) =
                                        rhs.split_once('.')
                                    {
                                        let rcol = rcol.trim().trim_matches('`');
                                        columns
                                            .iter()
                                            .position(|c| c.eq_ignore_ascii_case(rcol))
                                            .and_then(|idx| row.get(idx).and_then(|v| v.as_deref()))
                                            .map(|v| format!("'{v}'"))
                                            .unwrap_or_else(|| rhs.to_string())
                                    } else {
                                        rhs.to_string()
                                    };
                                    set_parts.push(format!("`{col}` = {resolved_value}"));
                                }
                                // Use id column for WHERE if available
                                let id_col = columns
                                    .iter()
                                    .find(|c| c.eq_ignore_ascii_case("id"))
                                    .cloned();
                                if let Some(id_name) = &id_col {
                                    let id_idx =
                                        columns.iter().position(|c| c == id_name).unwrap_or(0);
                                    if let Some(Some(id_val)) = row.get(id_idx) {
                                        let update_sql = format!(
                                            "UPDATE `{first_table}` SET {} WHERE `{id_name}` = '{id_val}'",
                                            set_parts.join(", ")
                                        );
                                        if Box::pin(mysql_execute_sql(state, &update_sql, session))
                                            .await
                                            .is_ok()
                                        {
                                            affected += 1;
                                        }
                                    }
                                } else {
                                    affected += 1; // Count as affected even without id-based UPDATE
                                }
                            }
                            return Ok(MySqlQueryOutcome::Ok {
                                affected_rows: affected,
                                last_insert_id: 0,
                            });
                        }
                        Ok(_) => {
                            return Ok(MySqlQueryOutcome::Ok {
                                affected_rows: 0,
                                last_insert_id: 0,
                            });
                        }
                        Err(e) => return Err(e),
                    }
                }
            }
        }
    }

    // UNION / UNION ALL support
    {
        let trimmed = sql.trim().trim_end_matches(';').trim();
        if let Some(union_all_pos) = find_keyword_top_level(trimmed, "union all") {
            let left_sql = trimmed[..union_all_pos].trim();
            let right_sql = trimmed[union_all_pos + "union all".len()..].trim();
            let left_result = Box::pin(mysql_execute_sql(state, left_sql, session)).await?;
            let right_result = Box::pin(mysql_execute_sql(state, right_sql, session)).await?;
            match (left_result, right_result) {
                (
                    MySqlQueryOutcome::ResultSet { columns, mut rows },
                    MySqlQueryOutcome::ResultSet {
                        rows: right_rows, ..
                    },
                ) => {
                    rows.extend(right_rows);
                    return Ok(MySqlQueryOutcome::ResultSet { columns, rows });
                }
                _ => {
                    return Err((
                        1064,
                        "42000",
                        "UNION requires SELECT statements".to_string(),
                    ))
                }
            }
        }
        if let Some(union_pos) = find_keyword_top_level(trimmed, "union") {
            let left_sql = trimmed[..union_pos].trim();
            let right_sql = trimmed[union_pos + "union".len()..].trim();
            let left_result = Box::pin(mysql_execute_sql(state, left_sql, session)).await?;
            let right_result = Box::pin(mysql_execute_sql(state, right_sql, session)).await?;
            match (left_result, right_result) {
                (
                    MySqlQueryOutcome::ResultSet { columns, mut rows },
                    MySqlQueryOutcome::ResultSet {
                        rows: right_rows, ..
                    },
                ) => {
                    rows.extend(right_rows);
                    let mut seen = std::collections::HashSet::new();
                    rows.retain(|row| seen.insert(row.clone()));
                    return Ok(MySqlQueryOutcome::ResultSet { columns, rows });
                }
                _ => {
                    return Err((
                        1064,
                        "42000",
                        "UNION requires SELECT statements".to_string(),
                    ))
                }
            }
        }
    }

    // CTE (WITH ... AS) support
    {
        let trimmed = sql.trim().trim_end_matches(';').trim();
        if trimmed.to_ascii_lowercase().starts_with("with ") {
            if let Some(result) = mysql_rewrite_cte(trimmed, state, session).await {
                return result;
            }
        }
    }

    // Derived table (FROM subquery) support
    {
        let trimmed = sql.trim().trim_end_matches(';').trim();
        if let Some(result) = mysql_rewrite_derived_table(trimmed, state, session).await {
            return result;
        }
    }

    // ── Projection subquery support: SELECT col, (SELECT ...) AS alias FROM table ──
    {
        let trimmed_ps = sql.trim().trim_end_matches(';').trim();
        if let Some(result) = mysql_try_projection_subquery(state, trimmed_ps, session).await? {
            return Ok(result);
        }
    }

    match mysql_try_compat_query_outcome(state, sql, session.default_db.as_deref()).await {
        Ok(Some(outcome)) => return Ok(outcome),
        Ok(None) => {}
        Err(err) => return Err(mysql_error_from_rpc(&err)),
    }

    let rewritten = mysql_rewrite_sql_calc_found_rows(sql);
    let exec_sql = rewritten.clone().unwrap_or_else(|| sql.to_string());
    let calc_found_rows = rewritten.is_some();

    // Strip locking clauses that we don't enforce
    let exec_sql = {
        let t = exec_sql.trim();
        let tl = t.to_ascii_lowercase();
        if tl.ends_with(" for update") {
            t[..t.len() - " for update".len()].to_string()
        } else if tl.ends_with(" for share") {
            t[..t.len() - " for share".len()].to_string()
        } else if tl.ends_with(" lock in share mode") {
            t[..t.len() - " lock in share mode".len()].to_string()
        } else {
            exec_sql
        }
    };

    if !calc_found_rows {
        // SELECT @user_variable support
        {
            let trimmed_check = exec_sql.trim().trim_end_matches(';').trim();
            let lower_check = trimmed_check.to_ascii_lowercase();
            if lower_check.starts_with("select ") {
                let rest = trimmed_check[7..].trim();
                if rest.starts_with('@') && !rest.starts_with("@@") {
                    let var_name = rest.trim_start_matches('@').trim();
                    let value = session.user_variables.get(var_name).cloned();
                    return Ok(MySqlQueryOutcome::ResultSet {
                        columns: vec![format!("@{var_name}")],
                        rows: vec![vec![value]],
                    });
                }
            }
        }
        if let Some((cols, emit_row)) =
            parse_select_literal_query(&exec_sql, session.default_db.as_deref())
        {
            let columns = cols
                .iter()
                .map(|(name, _)| name.clone())
                .collect::<Vec<_>>();
            let rows = if emit_row {
                vec![cols
                    .iter()
                    .map(|(_, lit)| mysql_literal_text(lit))
                    .collect::<Vec<_>>()]
            } else {
                Vec::new()
            };
            return Ok(MySqlQueryOutcome::ResultSet { columns, rows });
        }
    }

    // ── Window function support: ROW_NUMBER()/RANK()/DENSE_RANK() OVER(...) ──
    {
        let trimmed_wf = exec_sql.trim().trim_end_matches(';').trim();
        let lower_wf = trimmed_wf.to_ascii_lowercase();
        if lower_wf.starts_with("select ")
            && (lower_wf.contains("row_number()")
                || lower_wf.contains("rank()")
                || lower_wf.contains("dense_rank()"))
            && lower_wf.contains(" over(")
            || lower_wf.contains(" over (")
        {
            if let Some(result) =
                mysql_try_window_function_query(state, trimmed_wf, session).await?
            {
                return Ok(result);
            }
        }
    }

    let params = SqlExecParams {
        sql: exec_sql.clone(),
        explain: false,
        default_db: session.default_db.clone(),
        result_format: Some(ResultFormat::RowsJson),
        as_of_ms: session.skein_as_of_ms,
    };
    let result = sql_exec(state, params)
        .await
        .map_err(|err| mysql_error_from_rpc(&err))?;

    if result.get("statement").and_then(|v| v.as_str()) == Some("use") {
        session.default_db = result
            .get("default_db")
            .and_then(|v| v.as_str())
            .map(|v| v.to_string());
    }
    if calc_found_rows {
        match mysql_select_total_rows_without_limit(state, &exec_sql, session.default_db.as_deref())
            .await
        {
            Ok(total) => session.last_found_rows = total,
            Err(err) => return Err(mysql_error_from_rpc(&err)),
        }
    }

    let statement = result
        .get("statement")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    // Track LAST_INSERT_ID after INSERT/REPLACE
    if matches!(statement, "insert" | "replace") {
        if let Some(lid) = result
            .get("write")
            .and_then(|v| v.get("last_insert_id"))
            .and_then(|v| v.as_u64())
        {
            if lid > 0 {
                session.last_insert_id = lid;
            }
        }
    }

    let transactional_write = matches!(statement, "insert" | "update" | "delete")
        && (!session.autocommit || session.tx_active);
    if transactional_write {
        session.tx_active = true;
        if statement == "insert" {
            if let Some(undo_sql) = mysql_build_insert_undo_sql(
                state,
                &exec_sql,
                session.default_db.as_deref(),
                &result,
            )
            .await
            {
                session.tx_undo_sql.push(undo_sql);
            }
        }
    }

    mysql_query_outcome_from_sql_exec(&result, Some(&exec_sql), session.default_db.as_deref())
        .map_err(|msg| (1105, "HY000", msg))
}

fn mysql_handshake_packet(connection_id: u32, seed: &[u8; 20]) -> Vec<u8> {
    let mut payload = Vec::with_capacity(96);
    payload.push(MYSQL_PROTOCOL_VERSION);
    payload.extend_from_slice(MYSQL_SERVER_VERSION.as_bytes());
    payload.push(0);
    payload.extend_from_slice(&connection_id.to_le_bytes());
    payload.extend_from_slice(&seed[..8]);
    payload.push(0);
    payload.extend_from_slice(&(MYSQL_SERVER_CAPABILITIES as u16).to_le_bytes());
    payload.push(0x21);
    payload.extend_from_slice(&MYSQL_STATUS_AUTOCOMMIT.to_le_bytes());
    payload.extend_from_slice(&((MYSQL_SERVER_CAPABILITIES >> 16) as u16).to_le_bytes());
    payload.push((seed.len() + 1) as u8);
    payload.extend_from_slice(&[0u8; 10]);
    let mut part2 = seed[8..].to_vec();
    if part2.len() < 13 {
        part2.resize(13, 0);
    }
    payload.extend_from_slice(&part2);
    payload.extend_from_slice(MYSQL_AUTH_PLUGIN.as_bytes());
    payload.push(0);
    payload
}

fn mysql_ok_packet() -> Vec<u8> {
    mysql_ok_packet_with(0, 0)
}

fn mysql_ok_packet_with(affected_rows: u64, last_insert_id: u64) -> Vec<u8> {
    let mut payload = Vec::new();
    payload.push(0x00);
    mysql_push_lenenc_int(&mut payload, affected_rows as usize);
    mysql_push_lenenc_int(&mut payload, last_insert_id as usize);
    payload.extend_from_slice(&MYSQL_STATUS_AUTOCOMMIT.to_le_bytes());
    payload.extend_from_slice(&0u16.to_le_bytes());
    payload
}

fn mysql_err_packet(code: u16, sql_state: &str, message: &str) -> Vec<u8> {
    let mut payload = Vec::new();
    payload.push(0xff);
    payload.extend_from_slice(&code.to_le_bytes());
    payload.push(b'#');
    let mut state = [b'H', b'Y', b'0', b'0', b'0'];
    for (idx, byte) in sql_state.as_bytes().iter().take(5).enumerate() {
        state[idx] = *byte;
    }
    payload.extend_from_slice(&state);
    payload.extend_from_slice(message.as_bytes());
    payload
}

async fn mysql_write_packet(stream: &mut TcpStream, seq: u8, payload: &[u8]) -> anyhow::Result<()> {
    if payload.len() > 0x00ff_ffff {
        return Err(anyhow::anyhow!("mysql payload too large"));
    }
    let len = payload.len();
    let header = [
        (len & 0xff) as u8,
        ((len >> 8) & 0xff) as u8,
        ((len >> 16) & 0xff) as u8,
        seq,
    ];
    stream.write_all(&header).await?;
    stream.write_all(payload).await?;
    stream.flush().await?;
    Ok(())
}

async fn mysql_read_packet(stream: &mut TcpStream) -> anyhow::Result<(u8, Vec<u8>)> {
    let mut header = [0u8; 4];
    stream.read_exact(&mut header).await?;
    let len = (header[0] as usize) | ((header[1] as usize) << 8) | ((header[2] as usize) << 16);
    let seq = header[3];
    let mut payload = vec![0u8; len];
    stream.read_exact(&mut payload).await?;
    Ok((seq, payload))
}

async fn mysql_send_text_result(
    stream: &mut TcpStream,
    start_seq: u8,
    columns: &[String],
    rows: &[Vec<Option<String>>],
) -> anyhow::Result<()> {
    let mut seq = start_seq;
    let mut column_count = Vec::new();
    mysql_push_lenenc_int(&mut column_count, columns.len());
    mysql_write_packet(stream, seq, &column_count).await?;
    seq = seq.wrapping_add(1);

    for name in columns {
        let packet = mysql_column_definition_packet(name, &MySqlLiteral::Str(String::new()));
        mysql_write_packet(stream, seq, &packet).await?;
        seq = seq.wrapping_add(1);
    }

    mysql_write_packet(stream, seq, &mysql_eof_packet()).await?;
    seq = seq.wrapping_add(1);
    for row in rows {
        let packet = mysql_text_row_packet(row);
        mysql_write_packet(stream, seq, &packet).await?;
        seq = seq.wrapping_add(1);
    }
    mysql_write_packet(stream, seq, &mysql_eof_packet()).await?;
    Ok(())
}

fn mysql_prepare_ok_packet(statement_id: u32, column_count: u16, param_count: u16) -> Vec<u8> {
    let mut payload = Vec::new();
    payload.push(0x00);
    payload.extend_from_slice(&statement_id.to_le_bytes());
    payload.extend_from_slice(&column_count.to_le_bytes());
    payload.extend_from_slice(&param_count.to_le_bytes());
    payload.push(0);
    payload.extend_from_slice(&0u16.to_le_bytes());
    payload
}

async fn mysql_send_prepare_ok(
    stream: &mut TcpStream,
    start_seq: u8,
    statement_id: u32,
    param_count: u16,
    result_columns: &[MySqlStmtPrepareColumn],
) -> anyhow::Result<()> {
    let mut seq = start_seq;
    let packet = mysql_prepare_ok_packet(statement_id, result_columns.len() as u16, param_count);
    mysql_write_packet(stream, seq, &packet).await?;
    seq = seq.wrapping_add(1);
    if param_count > 0 {
        for idx in 0..param_count {
            let name = format!("param{}", idx + 1);
            let packet = mysql_column_definition_packet_with_type(&name, 0xfd, 255);
            mysql_write_packet(stream, seq, &packet).await?;
            seq = seq.wrapping_add(1);
        }
        mysql_write_packet(stream, seq, &mysql_eof_packet()).await?;
        seq = seq.wrapping_add(1);
    }
    if !result_columns.is_empty() {
        for column in result_columns {
            let len = match column.column_type {
                MySqlStmtColumnType::Bool | MySqlStmtColumnType::LongLong => 20,
                MySqlStmtColumnType::Double => 24,
                MySqlStmtColumnType::Date
                | MySqlStmtColumnType::Time
                | MySqlStmtColumnType::DateTime
                | MySqlStmtColumnType::Json
                | MySqlStmtColumnType::Bytes
                | MySqlStmtColumnType::Uuid
                | MySqlStmtColumnType::VarString => 255,
            };
            let packet = mysql_column_definition_packet_with_type_flags(
                &column.name,
                mysql_stmt_column_type_code(column.column_type),
                len,
                column.flags,
            );
            mysql_write_packet(stream, seq, &packet).await?;
            seq = seq.wrapping_add(1);
        }
        mysql_write_packet(stream, seq, &mysql_eof_packet()).await?;
    }
    Ok(())
}

async fn mysql_send_binary_result(
    stream: &mut TcpStream,
    start_seq: u8,
    columns: &[String],
    rows: &[Vec<Option<String>>],
    prepared_columns: Option<&[MySqlStmtPrepareColumn]>,
) -> anyhow::Result<()> {
    let column_types = mysql_binary_result_column_types(columns, rows, prepared_columns);
    let next_seq = mysql_send_binary_result_header(
        stream,
        start_seq,
        columns,
        rows,
        &column_types,
        MYSQL_STATUS_AUTOCOMMIT,
    )
    .await?;
    mysql_send_binary_result_rows_only(
        stream,
        next_seq,
        rows,
        &column_types,
        MYSQL_STATUS_AUTOCOMMIT,
    )
    .await?;
    Ok(())
}

fn mysql_binary_result_column_types(
    columns: &[String],
    rows: &[Vec<Option<String>>],
    prepared_columns: Option<&[MySqlStmtPrepareColumn]>,
) -> Vec<MySqlStmtColumnType> {
    let mut column_types = mysql_stmt_infer_column_types(rows, columns.len());
    if rows.is_empty() {
        if let Some(prepared_columns) = prepared_columns {
            if prepared_columns.len() == columns.len()
                && prepared_columns
                    .iter()
                    .zip(columns.iter())
                    .all(|(prepared, actual)| prepared.name.eq_ignore_ascii_case(actual))
            {
                column_types = prepared_columns
                    .iter()
                    .map(|prepared| prepared.column_type)
                    .collect();
            }
        }
    }
    column_types
}

async fn mysql_send_binary_result_header(
    stream: &mut TcpStream,
    start_seq: u8,
    columns: &[String],
    rows: &[Vec<Option<String>>],
    column_types: &[MySqlStmtColumnType],
    eof_status: u16,
) -> anyhow::Result<u8> {
    let mut seq = start_seq;
    let mut column_count = Vec::new();
    mysql_push_lenenc_int(&mut column_count, columns.len());
    mysql_write_packet(stream, seq, &column_count).await?;
    seq = seq.wrapping_add(1);
    for (idx, name) in columns.iter().enumerate() {
        let len = match column_types[idx] {
            MySqlStmtColumnType::Bool | MySqlStmtColumnType::LongLong => 20,
            MySqlStmtColumnType::Double => 24,
            MySqlStmtColumnType::Date
            | MySqlStmtColumnType::Time
            | MySqlStmtColumnType::DateTime
            | MySqlStmtColumnType::Json
            | MySqlStmtColumnType::Bytes
            | MySqlStmtColumnType::Uuid
            | MySqlStmtColumnType::VarString => rows
                .iter()
                .filter_map(|row| row.get(idx).and_then(|v| v.as_ref()))
                .map(|value| value.len() as u32)
                .max()
                .unwrap_or(1),
        };
        let packet = mysql_column_definition_packet_with_type(
            name,
            mysql_stmt_column_type_code(column_types[idx]),
            len,
        );
        mysql_write_packet(stream, seq, &packet).await?;
        seq = seq.wrapping_add(1);
    }

    mysql_write_packet(stream, seq, &mysql_eof_packet_with_status(eof_status)).await?;
    Ok(seq.wrapping_add(1))
}

async fn mysql_send_binary_result_rows_only(
    stream: &mut TcpStream,
    start_seq: u8,
    rows: &[Vec<Option<String>>],
    column_types: &[MySqlStmtColumnType],
    eof_status: u16,
) -> anyhow::Result<()> {
    let mut seq = start_seq;
    for row in rows {
        let packet =
            mysql_binary_row_packet(row, column_types).map_err(|msg| anyhow::anyhow!(msg))?;
        mysql_write_packet(stream, seq, &packet).await?;
        seq = seq.wrapping_add(1);
    }
    mysql_write_packet(stream, seq, &mysql_eof_packet_with_status(eof_status)).await?;
    Ok(())
}

async fn handle_mysql_connection(
    state: AppState,
    mut stream: TcpStream,
    connection_id: u32,
) -> anyhow::Result<()> {
    let seed = mysql_seed(connection_id);
    let handshake = mysql_handshake_packet(connection_id, &seed);
    mysql_write_packet(&mut stream, 0, &handshake).await?;

    let (seq, response_payload) = mysql_read_packet(&mut stream).await?;
    let response = match parse_mysql_handshake_response(&response_payload) {
        Ok(parsed) => parsed,
        Err(reason) => {
            let packet = mysql_err_packet(1047, "08S01", &format!("malformed handshake: {reason}"));
            mysql_write_packet(&mut stream, seq.wrapping_add(1), &packet).await?;
            return Ok(());
        }
    };

    if response.capabilities & MYSQL_CAP_SSL != 0 {
        let packet = mysql_err_packet(1047, "08S01", "TLS is not supported on this listener");
        mysql_write_packet(&mut stream, seq.wrapping_add(1), &packet).await?;
        return Ok(());
    }

    if let Some(plugin) = response.auth_plugin.as_deref() {
        if plugin != MYSQL_AUTH_PLUGIN {
            let packet = mysql_err_packet(1251, "08004", "unsupported auth plugin");
            mysql_write_packet(&mut stream, seq.wrapping_add(1), &packet).await?;
            return Ok(());
        }
    }

    if let Ok(expected_password) = std::env::var("SKEINDB_TOKEN") {
        if !mysql_validate_native_password(&expected_password, &seed, &response.auth_response) {
            let packet = mysql_err_packet(1045, "28000", "access denied");
            mysql_write_packet(&mut stream, seq.wrapping_add(1), &packet).await?;
            return Ok(());
        }
    }

    let username = response.username;
    let mut session = MySqlSessionState::new(response.database, connection_id);
    let mut prepared_statements = HashMap::<u32, MySqlPreparedStatement>::new();
    let mut next_statement_id = 1u32;
    let ok = mysql_ok_packet();
    mysql_write_packet(&mut stream, seq.wrapping_add(1), &ok).await?;

    loop {
        let (cmd_seq, command_payload) = match mysql_read_packet(&mut stream).await {
            Ok(packet) => packet,
            Err(err) => {
                let disconnect = err
                    .downcast_ref::<std::io::Error>()
                    .map(|io| {
                        matches!(
                            io.kind(),
                            std::io::ErrorKind::UnexpectedEof
                                | std::io::ErrorKind::ConnectionReset
                                | std::io::ErrorKind::BrokenPipe
                        )
                    })
                    .unwrap_or(false);
                if disconnect {
                    return Ok(());
                }
                return Err(err);
            }
        };
        if command_payload.is_empty() {
            continue;
        }
        match command_payload[0] {
            0x01 => {
                return Ok(());
            }
            0x0e => {
                mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &mysql_ok_packet())
                    .await?;
            }
            0x03 => {
                let sql = {
                    let raw = String::from_utf8_lossy(&command_payload[1..]);
                    let t = raw.trim();
                    let stripped = t.trim_end_matches(';').trim();
                    let tl = stripped.to_ascii_lowercase();
                    if tl.ends_with(" for update") {
                        stripped[..stripped.len() - " for update".len()].to_string()
                    } else if tl.ends_with(" for share") {
                        stripped[..stripped.len() - " for share".len()].to_string()
                    } else if tl.ends_with(" lock in share mode") {
                        stripped[..stripped.len() - " lock in share mode".len()].to_string()
                    } else {
                        t.to_string()
                    }
                };
                match mysql_execute_sql(&state, &sql, &mut session).await {
                    Ok(MySqlQueryOutcome::ResultSet { columns, rows }) => {
                        mysql_send_text_result(
                            &mut stream,
                            cmd_seq.wrapping_add(1),
                            &columns,
                            &rows,
                        )
                        .await?;
                    }
                    Ok(MySqlQueryOutcome::Ok {
                        affected_rows,
                        last_insert_id,
                    }) => {
                        let packet = mysql_ok_packet_with(affected_rows, last_insert_id);
                        mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    }
                    Err((code, state_code, message)) => {
                        let packet = mysql_err_packet(code, state_code, &message);
                        mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    }
                }
            }
            0x16 => {
                let sql = String::from_utf8_lossy(&command_payload[1..]).to_string();
                let statement_id = next_statement_id;
                next_statement_id = next_statement_id.wrapping_add(1);
                let param_count = mysql_count_placeholders(&sql);
                let result_columns =
                    mysql_stmt_prepare_columns(&state, &sql, session.default_db.as_deref()).await;
                prepared_statements.insert(
                    statement_id,
                    MySqlPreparedStatement::new(sql, param_count, result_columns.clone()),
                );
                mysql_send_prepare_ok(
                    &mut stream,
                    cmd_seq.wrapping_add(1),
                    statement_id,
                    param_count,
                    &result_columns,
                )
                .await?;
            }
            0x17 => {
                if command_payload.len() < 5 {
                    let packet = mysql_err_packet(1064, "42000", "malformed COM_STMT_EXECUTE");
                    mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    continue;
                }
                let statement_id = u32::from_le_bytes([
                    command_payload[1],
                    command_payload[2],
                    command_payload[3],
                    command_payload[4],
                ]);
                let (sql, prepared_columns, cursor_read_only) = match prepared_statements
                    .get_mut(&statement_id)
                {
                    Some(statement) => {
                        statement.cursor = None;
                        match mysql_parse_stmt_execute_params(&command_payload, statement) {
                            Ok((params, cursor_read_only)) => {
                                match mysql_substitute_stmt_sql(&statement.sql, &params) {
                                    Ok(sql) => {
                                        (sql, statement.result_columns.clone(), cursor_read_only)
                                    }
                                    Err(message) => {
                                        let packet = mysql_err_packet(1064, "42000", &message);
                                        mysql_write_packet(
                                            &mut stream,
                                            cmd_seq.wrapping_add(1),
                                            &packet,
                                        )
                                        .await?;
                                        continue;
                                    }
                                }
                            }
                            Err(message) => {
                                let code = if message.contains("unsupported") {
                                    1235
                                } else {
                                    1064
                                };
                                let state_code = "42000";
                                let packet = mysql_err_packet(code, state_code, &message);
                                mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet)
                                    .await?;
                                continue;
                            }
                        }
                    }
                    None => {
                        let packet =
                            mysql_err_packet(1243, "HY000", "unknown prepared statement handler");
                        mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                        continue;
                    }
                };
                match mysql_execute_sql(&state, &sql, &mut session).await {
                    Ok(MySqlQueryOutcome::ResultSet { columns, rows }) => {
                        if cursor_read_only {
                            let column_types = mysql_binary_result_column_types(
                                &columns,
                                &rows,
                                Some(&prepared_columns),
                            );
                            let cursor_status = if rows.is_empty() {
                                MYSQL_STATUS_AUTOCOMMIT | MYSQL_STATUS_LAST_ROW_SENT
                            } else {
                                MYSQL_STATUS_AUTOCOMMIT | MYSQL_STATUS_CURSOR_EXISTS
                            };
                            mysql_send_binary_result_header(
                                &mut stream,
                                cmd_seq.wrapping_add(1),
                                &columns,
                                &rows,
                                &column_types,
                                cursor_status,
                            )
                            .await?;
                            if let Some(statement) = prepared_statements.get_mut(&statement_id) {
                                statement.cursor = Some(MySqlPreparedCursor {
                                    column_types,
                                    rows,
                                    next_row: 0,
                                });
                            }
                        } else {
                            mysql_send_binary_result(
                                &mut stream,
                                cmd_seq.wrapping_add(1),
                                &columns,
                                &rows,
                                Some(&prepared_columns),
                            )
                            .await?;
                        }
                    }
                    Ok(MySqlQueryOutcome::Ok {
                        affected_rows,
                        last_insert_id,
                    }) => {
                        let packet = mysql_ok_packet_with(affected_rows, last_insert_id);
                        mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    }
                    Err((code, state_code, message)) => {
                        let packet = mysql_err_packet(code, state_code, &message);
                        mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    }
                }
            }
            0x18 => {
                if command_payload.len() < 7 {
                    let packet =
                        mysql_err_packet(1064, "42000", "malformed COM_STMT_SEND_LONG_DATA");
                    mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    continue;
                }
                let statement_id = u32::from_le_bytes([
                    command_payload[1],
                    command_payload[2],
                    command_payload[3],
                    command_payload[4],
                ]);
                let param_id = u16::from_le_bytes([command_payload[5], command_payload[6]]);
                let Some(statement) = prepared_statements.get_mut(&statement_id) else {
                    let packet =
                        mysql_err_packet(1243, "HY000", "unknown prepared statement handler");
                    mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    continue;
                };
                statement
                    .long_data
                    .entry(param_id)
                    .or_default()
                    .extend_from_slice(&command_payload[7..]);
                mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &mysql_ok_packet())
                    .await?;
            }
            0x19 => {
                if command_payload.len() >= 5 {
                    let statement_id = u32::from_le_bytes([
                        command_payload[1],
                        command_payload[2],
                        command_payload[3],
                        command_payload[4],
                    ]);
                    prepared_statements.remove(&statement_id);
                }
                continue;
            }
            0x1a => {
                if command_payload.len() < 5 {
                    let packet = mysql_err_packet(1064, "42000", "malformed COM_STMT_RESET");
                    mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    continue;
                }
                let statement_id = u32::from_le_bytes([
                    command_payload[1],
                    command_payload[2],
                    command_payload[3],
                    command_payload[4],
                ]);
                let Some(statement) = prepared_statements.get_mut(&statement_id) else {
                    let packet =
                        mysql_err_packet(1243, "HY000", "unknown prepared statement handler");
                    mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    continue;
                };
                statement.long_data.clear();
                statement.cursor = None;
                mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &mysql_ok_packet())
                    .await?;
            }
            0x1c => {
                if command_payload.len() < 9 {
                    let packet = mysql_err_packet(1064, "42000", "malformed COM_STMT_FETCH");
                    mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    continue;
                }
                let statement_id = u32::from_le_bytes([
                    command_payload[1],
                    command_payload[2],
                    command_payload[3],
                    command_payload[4],
                ]);
                let fetch_rows = u32::from_le_bytes([
                    command_payload[5],
                    command_payload[6],
                    command_payload[7],
                    command_payload[8],
                ]) as usize;
                let Some(statement) = prepared_statements.get_mut(&statement_id) else {
                    let packet =
                        mysql_err_packet(1243, "HY000", "unknown prepared statement handler");
                    mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    continue;
                };
                let Some(cursor_state) = statement.cursor.as_mut() else {
                    let packet =
                        mysql_err_packet(1105, "HY000", "prepared statement has no open cursor");
                    mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
                    continue;
                };
                let start = cursor_state.next_row.min(cursor_state.rows.len());
                let end = if fetch_rows == 0 {
                    start
                } else {
                    start
                        .saturating_add(fetch_rows)
                        .min(cursor_state.rows.len())
                };
                let rows = cursor_state.rows[start..end].to_vec();
                cursor_state.next_row = end;
                let eof_status = if cursor_state.next_row < cursor_state.rows.len() {
                    MYSQL_STATUS_AUTOCOMMIT | MYSQL_STATUS_CURSOR_EXISTS
                } else {
                    MYSQL_STATUS_AUTOCOMMIT | MYSQL_STATUS_LAST_ROW_SENT
                };
                mysql_send_binary_result_rows_only(
                    &mut stream,
                    cmd_seq.wrapping_add(1),
                    &rows,
                    &cursor_state.column_types,
                    eof_status,
                )
                .await?;
            }
            0x02 => {
                // COM_INIT_DB
                let db_name = String::from_utf8_lossy(&command_payload[1..]).to_string();
                let db_name = db_name.trim().to_string();
                session.default_db = Some(db_name);
                mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &mysql_ok_packet())
                    .await?;
            }
            0x09 => {
                // COM_STATISTICS
                let stats = "Uptime: 1  Threads: 1  Questions: 1  Slow queries: 0  \
                     Opens: 0  Flush tables: 0  Open tables: 0  \
                     Queries per second avg: 0.000"
                    .to_string();
                mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), stats.as_bytes()).await?;
            }
            _ => {
                let packet = mysql_err_packet(1047, "08S01", "unsupported command");
                mysql_write_packet(&mut stream, cmd_seq.wrapping_add(1), &packet).await?;
            }
        }
        tracing::debug!(user = %username, "processed MySQL command");
    }
}

// ---------------------------------------------------------------------------
// PostgreSQL v3 wire protocol listener
// ---------------------------------------------------------------------------

const PG_SERVER_VERSION_NUM: &str = "160000";
const PG_DEFAULT_SCHEMA: &str = "public";
const PG_MAX_IDENTIFIER_LENGTH: &str = "63";
const PG_DEFAULT_TX_ISOLATION: &str = "read committed";

fn pg_bootstrap_setting_value(
    name: &str,
    default_db: Option<&str>,
    session: Option<&MySqlSessionState>,
) -> Option<String> {
    let normalized = name.trim().trim_matches('"').to_ascii_lowercase();
    // Check session-level settings first
    if let Some(sess) = session {
        if let Some(val) = sess.pg_settings.get(&normalized) {
            return Some(val.clone());
        }
    }
    match normalized.as_str() {
        "server_version" => Some(pg_wire::PG_SERVER_VERSION.to_string()),
        "server_version_num" => Some(PG_SERVER_VERSION_NUM.to_string()),
        "server_encoding" | "client_encoding" => Some("UTF8".to_string()),
        "datestyle" => Some("ISO, MDY".to_string()),
        "timezone" => Some("UTC".to_string()),
        "standard_conforming_strings" => Some("on".to_string()),
        "integer_datetimes" => Some("on".to_string()),
        "is_superuser" => Some("on".to_string()),
        "max_identifier_length" => Some(PG_MAX_IDENTIFIER_LENGTH.to_string()),
        "default_transaction_isolation"
        | "transaction_isolation"
        | "transaction isolation level" => Some(PG_DEFAULT_TX_ISOLATION.to_string()),
        "current_database" => Some(default_db.unwrap_or("skein").to_string()),
        "current_schema" => Some(PG_DEFAULT_SCHEMA.to_string()),
        _ => None,
    }
}

/// Parse `SET key = value` or `SET key TO value`. Returns (key, value).
fn pg_parse_set_command(rest: &str) -> Option<(String, String)> {
    // Handle SET LOCAL / SET SESSION prefix (ignore the scope keyword)
    let rest = rest
        .strip_prefix("local ")
        .or_else(|| rest.strip_prefix("LOCAL "))
        .or_else(|| rest.strip_prefix("session "))
        .or_else(|| rest.strip_prefix("SESSION "))
        .unwrap_or(rest)
        .trim();

    // Split on " TO " or " = "
    let (key, raw_value) = if let Some(pos) = rest.find('=') {
        (rest[..pos].trim(), rest[pos + 1..].trim())
    } else {
        let rest_lower = rest.to_ascii_lowercase();
        if let Some(pos) = rest_lower.find(" to ") {
            (rest[..pos].trim(), rest[pos + 4..].trim())
        } else {
            return None;
        }
    };

    if key.is_empty() || raw_value.is_empty() {
        return None;
    }

    // Strip surrounding quotes from value
    let value = if (raw_value.starts_with('\'') && raw_value.ends_with('\''))
        || (raw_value.starts_with('"') && raw_value.ends_with('"'))
    {
        &raw_value[1..raw_value.len() - 1]
    } else {
        raw_value
    };

    Some((key.to_string(), value.to_string()))
}

/// Extract and strip `RETURNING col1, col2, *` from DML SQL.
/// Returns the SQL without RETURNING and the column list (if found).
fn pg_extract_returning(sql: &str) -> (String, Option<Vec<String>>) {
    let lower = sql.to_ascii_lowercase();
    // Only strip RETURNING from DML statements
    let is_dml =
        lower.starts_with("insert") || lower.starts_with("update") || lower.starts_with("delete");
    if !is_dml {
        return (sql.to_string(), None);
    }
    // Find RETURNING keyword at top level (not inside strings/parens)
    if let Some(pos) = find_keyword_top_level(&lower, "returning") {
        let ret_clause = sql[pos + "returning".len()..].trim();
        let cols: Vec<String> = ret_clause
            .split(',')
            .map(|c| {
                let c = c.trim();
                // Handle table-qualified column refs like "t"."col" → col
                if let Some(dot_pos) = c.rfind('.') {
                    clean_sql_ident(c[dot_pos + 1..].trim())
                } else {
                    clean_sql_ident(c)
                }
            })
            .filter(|c| !c.is_empty())
            .collect();
        let remaining = sql[..pos].trim_end().to_string();
        if cols.is_empty() {
            (remaining, None)
        } else {
            (remaining, Some(cols))
        }
    } else {
        (sql.to_string(), None)
    }
}

/// Extract the table name from an INSERT statement (lowercase).
fn pg_extract_insert_table(sql_lower: &str) -> Option<String> {
    // INSERT [IGNORE] INTO table_name ...
    let rest = sql_lower.strip_prefix("insert")?.trim_start();
    let rest = rest.strip_prefix("ignore").unwrap_or(rest).trim_start();
    let rest = rest.strip_prefix("into")?.trim_start();
    // Table name extends until ( or whitespace
    let end = rest
        .find(|c: char| c == '(' || c.is_whitespace())
        .unwrap_or(rest.len());
    let table = rest[..end].trim().trim_matches('`').trim_matches('"');
    if table.is_empty() {
        None
    } else {
        Some(table.to_string())
    }
}

/// Look up the primary key column for a table. Falls back to "id".
async fn pg_lookup_pk_column(
    state: &AppState,
    table_name: &str,
    default_db: Option<&str>,
) -> String {
    let db = default_db.unwrap_or("skein");
    let eng = state.engine.read().await;
    if let Ok(desc) = eng.describe_table(db, table_name) {
        if let Some(pk_arr) = desc.get("primary_key").and_then(|v| v.as_array()) {
            if let Some(first) = pk_arr.first().and_then(|v| v.as_str()) {
                return first.to_string();
            }
        }
    }
    "id".to_string()
}

fn pg_parse_current_setting_name(sql_lower: &str) -> Option<&str> {
    let inner = sql_lower
        .strip_prefix("select current_setting(")?
        .strip_suffix(')')?
        .trim();
    inner.strip_prefix('\'')?.strip_suffix('\'')
}

async fn pg_write_single_text_result(
    stream: &mut TcpStream,
    column_name: &str,
    value: &str,
    command_tag: &str,
) -> anyhow::Result<()> {
    let cols = vec![pg_wire::PgColumn::text(column_name, pg_wire::oid::TEXT, -1)];
    pg_wire::write_row_description(stream, &cols).await?;
    pg_wire::write_data_row(stream, &[Some(value.as_bytes())]).await?;
    pg_wire::write_command_complete(stream, command_tag).await?;
    Ok(())
}

async fn pg_try_handle_bootstrap_query(
    stream: &mut TcpStream,
    sql: &str,
    default_db: Option<&str>,
    session: Option<&MySqlSessionState>,
) -> anyhow::Result<bool> {
    let sql_lower = sql.to_ascii_lowercase();

    if sql_lower == "select version()" {
        let ver = format!("PostgreSQL {}", pg_wire::PG_SERVER_VERSION);
        pg_write_single_text_result(stream, "version", &ver, "SELECT 1").await?;
        return Ok(true);
    }

    if sql_lower == "select current_database()" {
        let value = pg_bootstrap_setting_value("current_database", default_db, session)
            .unwrap_or_else(|| "skein".to_string());
        pg_write_single_text_result(stream, "current_database", &value, "SELECT 1").await?;
        return Ok(true);
    }

    if sql_lower == "select current_schema()" {
        pg_write_single_text_result(stream, "current_schema", PG_DEFAULT_SCHEMA, "SELECT 1")
            .await?;
        return Ok(true);
    }

    if let Some(setting) = sql_lower.strip_prefix("show ") {
        if let Some(value) = pg_bootstrap_setting_value(setting, default_db, session) {
            pg_write_single_text_result(stream, setting.trim(), &value, "SHOW").await?;
            return Ok(true);
        }
    }

    if let Some(setting) = pg_parse_current_setting_name(&sql_lower) {
        if let Some(value) = pg_bootstrap_setting_value(setting, default_db, session) {
            pg_write_single_text_result(stream, "current_setting", &value, "SELECT 1").await?;
            return Ok(true);
        }
    }

    Ok(false)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PgSavepoint {
    name: String,
    undo_len: usize,
}

fn pg_parse_named_command(sql: &str, prefix: &str) -> Option<String> {
    let trimmed = sql.trim().trim_end_matches(';').trim();
    let head = trimmed.get(..prefix.len())?;
    if !head.eq_ignore_ascii_case(prefix) {
        return None;
    }
    let name = trimmed.get(prefix.len()..)?.trim();
    if name.is_empty() {
        return None;
    }
    Some(name.trim_matches('"').to_string())
}

fn pg_parse_savepoint_name(sql: &str) -> Option<String> {
    pg_parse_named_command(sql, "savepoint ")
}

fn pg_parse_release_savepoint_name(sql: &str) -> Option<String> {
    pg_parse_named_command(sql, "release savepoint ")
}

fn pg_parse_rollback_to_savepoint_name(sql: &str) -> Option<String> {
    pg_parse_named_command(sql, "rollback to savepoint ")
        .or_else(|| pg_parse_named_command(sql, "rollback to "))
}

fn pg_find_savepoint_index(savepoints: &[PgSavepoint], name: &str) -> Option<usize> {
    savepoints
        .iter()
        .rposition(|savepoint| savepoint.name.eq_ignore_ascii_case(name))
}

fn pg_tx_status_for_session(session: &MySqlSessionState, failed: bool) -> pg_wire::TxStatus {
    use crate::pg_wire::TxStatus;

    if failed {
        TxStatus::Failed
    } else if session.tx_active {
        TxStatus::InTransaction
    } else {
        TxStatus::Idle
    }
}

/// Derive a deterministic 16-byte salt from the token so that SCRAM credentials
/// are stable across connections without needing persistent storage.
fn pg_scram_salt_for_token(token: &str) -> [u8; 16] {
    use sha2::{Digest, Sha256};
    let hash = Sha256::digest(format!("skeindb-scram-salt:{}", token).as_bytes());
    let mut salt = [0u8; 16];
    salt.copy_from_slice(&hash[..16]);
    salt
}

fn pg_sqlstate_from_mysql_error(code: u16, state: &'static str, message: &str) -> &'static str {
    let message_lower = message.to_ascii_lowercase();

    match state {
        "08P01" | "0A000" | "23505" | "25P01" | "25P02" | "28000" | "28P01" | "3B001" | "40001"
        | "42601" | "42703" | "42P01" => {
            return state;
        }
        _ => {}
    }

    match code {
        1062 => return "23505",
        1064 => return "42601",
        1146 => return "42P01",
        1235 => return "0A000",
        _ => {}
    }

    match state {
        "23000" => return "23505",
        "40001" => return "40001",
        "42S02" => return "42P01",
        "42S22" => return "42703",
        _ => {}
    }

    if message_lower.contains("duplicate key") || message_lower.contains("duplicate entry") {
        return "23505";
    }
    if message_lower.contains("unknown table")
        || message_lower.contains("table not found")
        || message_lower.contains("no such table")
        || (message_lower.contains("not found") && message_lower.contains("table"))
    {
        return "42P01";
    }
    if message_lower.contains("unknown column")
        || message_lower.contains("column not found")
        || message_lower.contains("no such column")
        || (message_lower.contains("not found") && message_lower.contains("column"))
    {
        return "42703";
    }
    if message_lower.contains("unsupported") {
        return "0A000";
    }
    if message_lower.contains("syntax")
        || message_lower.contains("malformed")
        || message_lower.contains("invalid ")
        || message_lower.contains("requires ")
        || message_lower.contains("missing ")
        || message_lower.contains("must ")
    {
        return "42601";
    }

    match state {
        "42000" => "42601",
        "HY000" => "XX000",
        _ => "XX000",
    }
}

async fn pg_rollback_full_transaction(
    state: &AppState,
    session: &mut MySqlSessionState,
    savepoints: &mut Vec<PgSavepoint>,
) -> Result<(), MySqlWireError> {
    if !session.tx_undo_sql.is_empty() {
        mysql_rollback_transaction(state, &session.tx_undo_sql)
            .await
            .map_err(|err| mysql_error_from_rpc(&err))?;
    }
    session.tx_active = false;
    session.tx_undo_sql.clear();
    savepoints.clear();
    Ok(())
}

fn pg_release_savepoint(
    savepoints: &mut Vec<PgSavepoint>,
    name: &str,
) -> Result<(), MySqlWireError> {
    let Some(index) = pg_find_savepoint_index(savepoints, name) else {
        return Err((1305, "3B001", format!("savepoint '{name}' does not exist")));
    };
    savepoints.truncate(index);
    Ok(())
}

async fn pg_rollback_to_savepoint(
    state: &AppState,
    session: &mut MySqlSessionState,
    savepoints: &mut Vec<PgSavepoint>,
    name: &str,
) -> Result<(), MySqlWireError> {
    let Some(index) = pg_find_savepoint_index(savepoints, name) else {
        return Err((1305, "3B001", format!("savepoint '{name}' does not exist")));
    };

    let undo_len = savepoints[index].undo_len;
    if undo_len < session.tx_undo_sql.len() {
        mysql_rollback_transaction(state, &session.tx_undo_sql[undo_len..])
            .await
            .map_err(|err| mysql_error_from_rpc(&err))?;
        session.tx_undo_sql.truncate(undo_len);
    }
    savepoints.truncate(index + 1);
    Ok(())
}

#[derive(Debug, Clone)]
struct PgPreparedStatement {
    sql: String,
    param_types: Vec<i32>,
    result_columns: Vec<MySqlStmtPrepareColumn>,
}

#[derive(Debug, Clone)]
struct PgPortal {
    sql: String,
    params: Vec<Lit>,
    result_columns: Vec<MySqlStmtPrepareColumn>,
    result_formats: Vec<i16>,
}

fn pg_stmt_column_oid_and_size(column_type: MySqlStmtColumnType) -> (i32, i16) {
    match column_type {
        MySqlStmtColumnType::Bool => (pg_wire::oid::BOOL, 1),
        MySqlStmtColumnType::LongLong => (pg_wire::oid::INT8, 8),
        MySqlStmtColumnType::Double => (pg_wire::oid::FLOAT8, 8),
        MySqlStmtColumnType::Date => (pg_wire::oid::DATE, 4),
        MySqlStmtColumnType::Time => (pg_wire::oid::TIME, 8),
        MySqlStmtColumnType::DateTime => (pg_wire::oid::TIMESTAMP, 8),
        MySqlStmtColumnType::Json => (pg_wire::oid::JSONB, -1),
        MySqlStmtColumnType::Bytes => (pg_wire::oid::BYTEA, -1),
        MySqlStmtColumnType::Uuid => (pg_wire::oid::UUID, 16),
        MySqlStmtColumnType::VarString => (pg_wire::oid::TEXT, -1),
    }
}

fn pg_text_value_for_column(
    value: Option<&str>,
    column: Option<&pg_wire::PgColumn>,
) -> Option<Vec<u8>> {
    let value = value?;
    let normalized = match column.map(|column| column.type_oid) {
        Some(pg_wire::oid::BOOL) => match value.trim().to_ascii_lowercase().as_str() {
            "1" | "t" | "true" => "t".to_string(),
            "0" | "f" | "false" => "f".to_string(),
            _ => value.to_string(),
        },
        Some(pg_wire::oid::BYTEA) => decode_base64_text(value)
            .map(|bytes| format!("\\x{}", hex_encode(&bytes)))
            .unwrap_or_else(|| value.to_string()),
        _ => value.to_string(),
    };
    Some(normalized.into_bytes())
}

fn pg_column_type_to_pg(name: &str, column_type: MySqlStmtColumnType) -> pg_wire::PgColumn {
    let (type_oid, type_size) = pg_stmt_column_oid_and_size(column_type);
    pg_wire::PgColumn::text(name, type_oid, type_size)
}

fn pg_prepare_column_to_pg(column: &MySqlStmtPrepareColumn) -> pg_wire::PgColumn {
    pg_column_type_to_pg(&column.name, column.column_type)
}

fn pg_prepare_columns_to_pg(
    columns: &[String],
    prepared_columns: &[MySqlStmtPrepareColumn],
) -> Option<Vec<pg_wire::PgColumn>> {
    if prepared_columns.len() != columns.len() {
        return None;
    }

    Some(
        columns
            .iter()
            .zip(prepared_columns.iter())
            .map(|(name, column)| pg_column_type_to_pg(name, column.column_type))
            .collect(),
    )
}

fn pg_catalog_result_column_override(name: &str) -> Option<pg_wire::PgColumn> {
    let (type_oid, type_size) = match name.to_ascii_lowercase().as_str() {
        "oid" | "datdba" | "dattablespace" | "typnamespace" | "typowner" | "typrelid"
        | "typelem" | "typarray" | "typbasetype" | "typndims" | "nspowner" | "datid"
        | "usesysid" | "relnamespace" | "relowner" | "relam" | "reltablespace" | "reloftype"
        | "attrelid" | "atttypid" | "attcollation" | "indexrelid" | "indrelid" | "connamespace"
        | "conrelid" | "contypid" | "conindid" | "conparentid" | "confrelid" => (26, 4),
        "datistemplate"
        | "datallowconn"
        | "pending_restart"
        | "typbyval"
        | "typispreferred"
        | "typisdefined"
        | "typnotnull"
        | "relhasindex"
        | "relhasrules"
        | "relhastriggers"
        | "relrowsecurity"
        | "relisshared"
        | "relispartition"
        | "relhaspkey"
        | "relforcerowsecurity"
        | "attnotnull"
        | "atthasdef"
        | "attisdropped"
        | "attislocal"
        | "indisunique"
        | "indisprimary"
        | "indisexclusion"
        | "indimmediate"
        | "indisclustered"
        | "indisvalid"
        | "indcheckxmin"
        | "indisready"
        | "indislive"
        | "indisreplident"
        | "condeferrable"
        | "condeferred"
        | "convalidated"
        | "conislocal"
        | "connoinherit" => (pg_wire::oid::BOOL, 1),
        "setting" | "boot_val" | "reset_val" => (pg_wire::oid::TEXT, -1),
        "relnatts" | "relchecks" | "attlen" | "attnum" | "attndims" | "atttypmod"
        | "attinhcount" | "indnatts" | "indnkeyatts" | "coninhcount" => (pg_wire::oid::INT4, 4),
        "reltuples" => (pg_wire::oid::FLOAT4, 4),
        _ => return None,
    };
    Some(pg_wire::PgColumn::text(name, type_oid, type_size))
}

fn pg_infer_result_columns_to_pg(
    sql: &str,
    columns: &[String],
    rows: &[Vec<Option<String>>],
) -> Vec<pg_wire::PgColumn> {
    let inferred_types = mysql_stmt_infer_column_types(rows, columns.len());
    let pg_catalog_query = sql.to_ascii_lowercase().contains("pg_catalog.");
    columns
        .iter()
        .zip(inferred_types)
        .map(|(name, column_type)| {
            if pg_catalog_query {
                if let Some(column) = pg_catalog_result_column_override(name) {
                    return column;
                }
            }
            pg_column_type_to_pg(name, column_type)
        })
        .collect()
}

async fn pg_result_columns_to_pg(
    state: &AppState,
    sql: &str,
    default_db: Option<&str>,
    columns: &[String],
    rows: &[Vec<Option<String>>],
    described_columns: Option<&[MySqlStmtPrepareColumn]>,
) -> Vec<pg_wire::PgColumn> {
    if let Some(prepared_columns) = described_columns {
        if let Some(columns) = pg_prepare_columns_to_pg(columns, prepared_columns) {
            return columns;
        }
    }

    let prepared_columns = mysql_stmt_prepare_columns(state, sql, default_db).await;
    if let Some(columns) = pg_prepare_columns_to_pg(columns, &prepared_columns) {
        return columns;
    }

    pg_infer_result_columns_to_pg(sql, columns, rows)
}

async fn pg_write_prepare_row_description(
    stream: &mut TcpStream,
    columns: &[MySqlStmtPrepareColumn],
) -> anyhow::Result<()> {
    if columns.is_empty() {
        pg_wire::write_no_data(stream).await?;
    } else {
        let pg_columns: Vec<pg_wire::PgColumn> =
            columns.iter().map(pg_prepare_column_to_pg).collect();
        pg_wire::write_row_description(stream, &pg_columns).await?;
    }
    Ok(())
}

fn pg_max_placeholder_index(sql: &str) -> usize {
    let bytes = sql.as_bytes();
    let mut quote = 0u8;
    let mut max_idx = 0usize;
    let mut i = 0usize;
    while i < bytes.len() {
        let b = bytes[i];
        if quote != 0 {
            if b == quote {
                if quote == b'\'' && i + 1 < bytes.len() && bytes[i + 1] == b'\'' {
                    i += 2;
                    continue;
                }
                quote = 0;
            }
            i += 1;
            continue;
        }

        match b {
            b'\'' | b'"' | b'`' => quote = b,
            b'$' => {
                let start = i + 1;
                let mut end = start;
                while end < bytes.len() && bytes[end].is_ascii_digit() {
                    end += 1;
                }
                if end > start {
                    let idx = std::str::from_utf8(&bytes[start..end])
                        .ok()
                        .and_then(|value| value.parse::<usize>().ok())
                        .unwrap_or(0);
                    max_idx = max_idx.max(idx);
                    i = end;
                    continue;
                }
            }
            _ => {}
        }

        i += 1;
    }
    max_idx
}

fn pg_default_lit_for_oid(type_oid: i32) -> Lit {
    match type_oid {
        pg_wire::oid::BOOL => Lit::Bool { v: false },
        pg_wire::oid::INT4 | pg_wire::oid::INT8 => Lit::I64 { v: 0 },
        pg_wire::oid::FLOAT4 | pg_wire::oid::FLOAT8 => Lit::F64 { v: 0.0 },
        pg_wire::oid::NUMERIC => Lit::Dec { v: "0".to_string() },
        pg_wire::oid::DATE => Lit::Date {
            iso: "1970-01-01".to_string(),
        },
        pg_wire::oid::TIME => Lit::Time {
            iso: "00:00:00".to_string(),
        },
        pg_wire::oid::TIMESTAMP | pg_wire::oid::TIMESTAMPTZ => Lit::Datetime {
            iso: "1970-01-01 00:00:00".to_string(),
        },
        pg_wire::oid::BYTEA => Lit::Bytes { b64: String::new() },
        _ => Lit::Str { v: String::new() },
    }
}

fn pg_guess_text_param_lit(text: &str) -> Lit {
    let trimmed = text.trim();
    let lower = trimmed.to_ascii_lowercase();
    if matches!(lower.as_str(), "true" | "t") {
        return Lit::Bool { v: true };
    }
    if matches!(lower.as_str(), "false" | "f") {
        return Lit::Bool { v: false };
    }
    if trimmed.contains(['.', 'e', 'E']) {
        if let Ok(value) = trimmed.parse::<f64>() {
            return Lit::F64 { v: value };
        }
    }
    if trimmed.starts_with('-') {
        if let Ok(value) = trimmed.parse::<i64>() {
            return Lit::I64 { v: value };
        }
    } else {
        if let Ok(value) = trimmed.parse::<u64>() {
            return Lit::U64 { v: value };
        }
        if let Ok(value) = trimmed.parse::<i64>() {
            return Lit::I64 { v: value };
        }
    }
    Lit::Str {
        v: text.to_string(),
    }
}

fn pg_decode_text_param_lit(text: &str, type_oid: i32) -> Lit {
    match type_oid {
        pg_wire::oid::BOOL => Lit::Bool {
            v: matches!(
                text.trim().to_ascii_lowercase().as_str(),
                "true" | "t" | "1"
            ),
        },
        pg_wire::oid::INT4 | pg_wire::oid::INT8 => {
            if let Ok(value) = text.trim().parse::<i64>() {
                Lit::I64 { v: value }
            } else {
                pg_guess_text_param_lit(text)
            }
        }
        pg_wire::oid::FLOAT4 | pg_wire::oid::FLOAT8 => {
            if let Ok(value) = text.trim().parse::<f64>() {
                Lit::F64 { v: value }
            } else {
                pg_guess_text_param_lit(text)
            }
        }
        pg_wire::oid::NUMERIC => Lit::Dec {
            v: text.trim().to_string(),
        },
        pg_wire::oid::DATE => Lit::Date {
            iso: text.to_string(),
        },
        pg_wire::oid::TIME => Lit::Time {
            iso: text.to_string(),
        },
        pg_wire::oid::TIMESTAMP | pg_wire::oid::TIMESTAMPTZ => Lit::Datetime {
            iso: text.to_string(),
        },
        pg_wire::oid::BYTEA => {
            use base64::Engine as _;

            let bytes = text
                .strip_prefix("\\x")
                .or_else(|| text.strip_prefix("\\X"))
                .and_then(decode_hex_text)
                .unwrap_or_else(|| text.as_bytes().to_vec());
            Lit::Bytes {
                b64: base64::engine::general_purpose::STANDARD.encode(bytes),
            }
        }
        pg_wire::oid::TEXT
        | pg_wire::oid::VARCHAR
        | pg_wire::oid::JSON
        | pg_wire::oid::JSONB
        | pg_wire::oid::UUID => Lit::Str {
            v: text.to_string(),
        },
        _ => pg_guess_text_param_lit(text),
    }
}

fn pg_substitute_stmt_sql(sql: &str, params: &[Lit]) -> Result<String, String> {
    let bytes = sql.as_bytes();
    let mut quote = 0u8;
    let mut out = String::with_capacity(sql.len().saturating_add(params.len() * 4));
    let mut i = 0usize;
    while i < bytes.len() {
        let b = bytes[i];
        if quote != 0 {
            out.push(b as char);
            if b == quote {
                if quote == b'\'' && i + 1 < bytes.len() && bytes[i + 1] == b'\'' {
                    out.push('\'');
                    i += 2;
                    continue;
                }
                quote = 0;
            }
            i += 1;
            continue;
        }

        match b {
            b'\'' | b'"' | b'`' => {
                quote = b;
                out.push(b as char);
                i += 1;
            }
            b'$' => {
                let start = i + 1;
                let mut end = start;
                while end < bytes.len() && bytes[end].is_ascii_digit() {
                    end += 1;
                }
                if end > start {
                    let param_idx = std::str::from_utf8(&bytes[start..end])
                        .map_err(|_| "invalid UTF-8 in PG placeholder".to_string())?
                        .parse::<usize>()
                        .map_err(|_| "invalid PG placeholder index".to_string())?;
                    if param_idx == 0 {
                        return Err("PG placeholders are 1-based".to_string());
                    }
                    let lit = params
                        .get(param_idx - 1)
                        .ok_or_else(|| "not enough PG prepared parameters".to_string())?;
                    out.push_str(&mysql_render_default_lit(lit));
                    i = end;
                } else {
                    out.push('$');
                    i += 1;
                }
            }
            _ => {
                out.push(b as char);
                i += 1;
            }
        }
    }
    Ok(out)
}

fn pg_read_i16_be(payload: &[u8], offset: &mut usize) -> Result<i16, String> {
    let bytes = payload
        .get(*offset..*offset + 2)
        .ok_or_else(|| "truncated PostgreSQL message".to_string())?;
    *offset += 2;
    Ok(i16::from_be_bytes([bytes[0], bytes[1]]))
}

fn pg_read_i32_be(payload: &[u8], offset: &mut usize) -> Result<i32, String> {
    let bytes = payload
        .get(*offset..*offset + 4)
        .ok_or_else(|| "truncated PostgreSQL message".to_string())?;
    *offset += 4;
    Ok(i32::from_be_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]))
}

fn pg_validate_format_codes(
    format_codes: &[i16],
    value_count: usize,
    what: &str,
) -> Result<(), String> {
    if format_codes.is_empty() || format_codes.len() == 1 || format_codes.len() == value_count {
        Ok(())
    } else {
        Err(format!(
            "invalid {what} format code count: expected 0, 1, or {value_count}; got {}",
            format_codes.len()
        ))
    }
}

fn pg_format_code_at(format_codes: &[i16], index: usize) -> i16 {
    match format_codes.len() {
        0 => 0,
        1 => format_codes[0],
        _ => format_codes[index],
    }
}

fn pg_command_tag_for_sql(sql_lower: &str, affected_rows: u64) -> String {
    if sql_lower.starts_with("insert") {
        format!("INSERT 0 {affected_rows}")
    } else if sql_lower.starts_with("update") {
        format!("UPDATE {affected_rows}")
    } else if sql_lower.starts_with("delete") {
        format!("DELETE {affected_rows}")
    } else if sql_lower.starts_with("create database") {
        "CREATE DATABASE".to_string()
    } else if sql_lower.starts_with("create table") {
        "CREATE TABLE".to_string()
    } else if sql_lower.starts_with("drop database") {
        "DROP DATABASE".to_string()
    } else if sql_lower.starts_with("drop table") {
        "DROP TABLE".to_string()
    } else if sql_lower.starts_with("alter table") {
        "ALTER TABLE".to_string()
    } else {
        "OK".to_string()
    }
}

// ── PG SQL dialect rewriting ────────────────────────────────────────────

/// Rewrite PG-specific SQL syntax into the shared engine's expected dialect.
/// Handles: :: type casts, $$dollar quoting$$, IS [NOT] DISTINCT FROM,
/// ARRAY[...] literals, FETCH FIRST n ROWS ONLY, and "double-quoted" → backtick identifiers.
fn pg_rewrite_sql(sql: &str) -> String {
    let mut out = String::with_capacity(sql.len() + 32);
    let bytes = sql.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        let b = bytes[i];

        // ── Skip single-quoted strings ──
        if b == b'\'' {
            out.push('\'');
            i += 1;
            while i < bytes.len() {
                if bytes[i] == b'\'' {
                    out.push('\'');
                    i += 1;
                    // doubled quote → escaped, keep going
                    if i < bytes.len() && bytes[i] == b'\'' {
                        out.push('\'');
                        i += 1;
                        continue;
                    }
                    break;
                }
                out.push(bytes[i] as char);
                i += 1;
            }
            continue;
        }

        // ── Dollar-quoted strings: $$...$$, $tag$...$tag$ ──
        if b == b'$' {
            // Check if this starts a dollar-quote tag
            if let Some((tag, body, consumed)) = pg_try_parse_dollar_quote(bytes, i) {
                let _ = tag; // tag is consumed
                             // Escape single quotes in the body and emit as single-quoted string
                out.push('\'');
                for ch in body.chars() {
                    if ch == '\'' {
                        out.push('\'');
                        out.push('\'');
                    } else {
                        out.push(ch);
                    }
                }
                out.push('\'');
                i += consumed;
                continue;
            }
            // Not a dollar-quote (could be $1 param) — pass through
            out.push('$');
            i += 1;
            continue;
        }

        // ── Double-quoted identifiers → backtick-quoted ──
        if b == b'"' {
            out.push('`');
            i += 1;
            while i < bytes.len() {
                if bytes[i] == b'"' {
                    if i + 1 < bytes.len() && bytes[i + 1] == b'"' {
                        // Doubled double-quote = escaped
                        out.push('`');
                        out.push('`');
                        i += 2;
                        continue;
                    }
                    out.push('`');
                    i += 1;
                    break;
                }
                out.push(bytes[i] as char);
                i += 1;
            }
            continue;
        }

        // ── :: type cast → CAST(... AS ...) ──
        if b == b':' && i + 1 < bytes.len() && bytes[i + 1] == b':' {
            // Walk backward to find the expression being cast
            let cast_expr_start = pg_find_cast_expr_start(&out);
            let expr_text = out[cast_expr_start..].to_string();
            out.truncate(cast_expr_start);
            i += 2; // skip ::
                    // Read the type name (may include parenthesized precision like varchar(255))
            let type_name = pg_read_cast_type(bytes, &mut i);
            out.push_str("CAST(");
            out.push_str(&expr_text);
            out.push_str(" AS ");
            out.push_str(&type_name);
            out.push(')');
            continue;
        }

        // ── IS [NOT] DISTINCT FROM ──
        if (b == b'i' || b == b'I') && pg_match_keyword_at(bytes, i, "is not distinct from") {
            // IS NOT DISTINCT FROM a, b → coalesce null-safe equality
            out.push_str("<=>");
            i += "is not distinct from".len();
            continue;
        }
        if (b == b'i' || b == b'I') && pg_match_keyword_at(bytes, i, "is distinct from") {
            // Replace the preceding expression with NOT(... <=> ...)
            // We emit the keyword-level replacement; the shared engine handles <=> (null_safe_eq)
            out.push_str("IS DISTINCT FROM");
            i += "is distinct from".len();
            continue;
        }

        // ── ARRAY[...] constructor ──
        if (b == b'a' || b == b'A') && pg_match_keyword_at(bytes, i, "array[") {
            i += "array[".len();
            // Collect everything inside the brackets at top level
            let (inner, consumed) = pg_collect_bracket_body(bytes, i);
            i += consumed;
            // Emit as a PG array literal string: '{...}'
            out.push('\'');
            out.push('{');
            out.push_str(&inner);
            out.push('}');
            out.push('\'');
            continue;
        }

        // ── FETCH FIRST n ROWS ONLY → LIMIT n ──
        if (b == b'f' || b == b'F') && pg_match_keyword_at(bytes, i, "fetch first ") {
            i += "fetch first ".len();
            // Skip whitespace
            while i < bytes.len() && bytes[i].is_ascii_whitespace() {
                i += 1;
            }
            // Read the number
            let num_start = i;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                i += 1;
            }
            let n = if i > num_start {
                std::str::from_utf8(&bytes[num_start..i]).unwrap_or("1")
            } else {
                "1"
            };
            // Skip " ROW[S] ONLY"
            let rest_lower: String = bytes[i..]
                .iter()
                .take(20)
                .map(|b| (*b as char).to_ascii_lowercase())
                .collect();
            for suffix in [" rows only", " row only"] {
                if rest_lower.starts_with(suffix) {
                    i += suffix.len();
                    break;
                }
            }
            out.push_str("LIMIT ");
            out.push_str(n);
            continue;
        }

        // ── Default: pass through ──
        out.push(b as char);
        i += 1;
    }

    // Post-pass: rewrite ON CONFLICT → ON DUPLICATE KEY UPDATE / INSERT IGNORE
    let out = pg_rewrite_on_conflict(&out);

    // Post-pass: rewrite IS DISTINCT FROM into NOT(... <=> ...)
    // The first pass emits the literal text "IS DISTINCT FROM" which parse_condition_expr
    // doesn't understand. We convert it here with a simple string replacement.
    pg_rewrite_is_distinct_from(&out)
}

/// Try to parse a dollar-quoted string starting at position `start`.
/// Returns (tag, body, total_bytes_consumed) or None.
fn pg_try_parse_dollar_quote(bytes: &[u8], start: usize) -> Option<(String, String, usize)> {
    // Must start with $
    if bytes[start] != b'$' {
        return None;
    }
    // Find end of opening tag: $tag$ or just $$
    let mut tag_end = start + 1;
    while tag_end < bytes.len() && bytes[tag_end] != b'$' {
        let ch = bytes[tag_end];
        if ch.is_ascii_alphanumeric() || ch == b'_' {
            tag_end += 1;
        } else {
            return None; // not a valid tag character
        }
    }
    if tag_end >= bytes.len() {
        return None;
    }
    // tag_end points to the closing $ of the opening tag
    let tag = std::str::from_utf8(&bytes[start..=tag_end]).ok()?;
    let body_start = tag_end + 1;
    // Find the matching closing tag
    let mut j = body_start;
    while j + tag.len() <= bytes.len() {
        if &bytes[j..j + tag.len()] == tag.as_bytes() {
            let body = std::str::from_utf8(&bytes[body_start..j]).ok()?;
            return Some((tag.to_string(), body.to_string(), j + tag.len() - start));
        }
        j += 1;
    }
    None
}

/// Walk backward through the output buffer to find the start of the expression being cast.
/// Handles: identifiers, numbers, closing parens (balanced), and quoted strings.
fn pg_find_cast_expr_start(out: &str) -> usize {
    let bytes = out.as_bytes();
    if bytes.is_empty() {
        return 0;
    }
    let mut j = bytes.len();
    // skip trailing whitespace
    while j > 0 && bytes[j - 1].is_ascii_whitespace() {
        j -= 1;
    }
    if j == 0 {
        return 0;
    }
    let last = bytes[j - 1];
    if last == b')' {
        // Walk backward matching parentheses
        let mut depth = 0i32;
        let mut k = j;
        while k > 0 {
            k -= 1;
            if bytes[k] == b')' {
                depth += 1;
            } else if bytes[k] == b'(' {
                depth -= 1;
                if depth == 0 {
                    // Check if preceded by a function name
                    let mut fn_start = k;
                    while fn_start > 0
                        && (bytes[fn_start - 1].is_ascii_alphanumeric()
                            || bytes[fn_start - 1] == b'_')
                    {
                        fn_start -= 1;
                    }
                    return fn_start;
                }
            } else if bytes[k] == b'\'' {
                // Walk backward through a single-quoted string
                k -= 1;
                while k > 0 {
                    if bytes[k] == b'\'' {
                        if k > 0 && bytes[k - 1] == b'\'' {
                            k -= 2;
                            continue;
                        }
                        break;
                    }
                    k -= 1;
                }
            }
        }
        return k;
    }
    if last == b'\'' {
        // Single-quoted string: walk backward to opening quote
        let mut k = j - 1;
        if k == 0 {
            return 0;
        }
        k -= 1;
        while k > 0 {
            if bytes[k] == b'\'' {
                if k > 0 && bytes[k - 1] == b'\'' {
                    k -= 2;
                    continue;
                }
                return k;
            }
            k -= 1;
        }
        return 0;
    }
    if last == b'`' {
        // Backtick-quoted identifier (already rewritten from double-quote)
        let mut k = j - 1;
        if k == 0 {
            return 0;
        }
        k -= 1;
        while k > 0 {
            if bytes[k] == b'`' {
                if k > 0 && bytes[k - 1] == b'`' {
                    k -= 2;
                    continue;
                }
                return k;
            }
            k -= 1;
        }
        return 0;
    }
    // Identifier or number: alnum, underscore, dot
    let mut k = j;
    while k > 0
        && (bytes[k - 1].is_ascii_alphanumeric() || bytes[k - 1] == b'_' || bytes[k - 1] == b'.')
    {
        k -= 1;
    }
    k
}

/// Read a PG type name after ::, advancing `i` past it.
/// Handles simple types, types with precision (e.g., varchar(255)), and multi-word types (e.g., double precision).
fn pg_read_cast_type(bytes: &[u8], i: &mut usize) -> String {
    // Skip leading whitespace
    while *i < bytes.len() && bytes[*i].is_ascii_whitespace() {
        *i += 1;
    }
    let start = *i;
    // Read word characters
    while *i < bytes.len() && (bytes[*i].is_ascii_alphanumeric() || bytes[*i] == b'_') {
        *i += 1;
    }
    let mut type_name = String::from_utf8_lossy(&bytes[start..*i]).to_string();
    // Check for multi-word types: "double precision", "timestamp with time zone", etc.
    let lower = type_name.to_ascii_lowercase();
    if lower == "double" || lower == "character" || lower == "timestamp" || lower == "time" {
        let saved = *i;
        while *i < bytes.len() && bytes[*i].is_ascii_whitespace() {
            *i += 1;
        }
        let word2_start = *i;
        while *i < bytes.len() && (bytes[*i].is_ascii_alphanumeric() || bytes[*i] == b'_') {
            *i += 1;
        }
        if *i > word2_start {
            let word2 = String::from_utf8_lossy(&bytes[word2_start..*i]).to_string();
            let w2_lower = word2.to_ascii_lowercase();
            if w2_lower == "precision"
                || w2_lower == "varying"
                || w2_lower == "with"
                || w2_lower == "without"
                || w2_lower == "zone"
            {
                type_name.push(' ');
                type_name.push_str(&word2);
                // "with time zone" / "without time zone" → keep consuming
                if w2_lower == "with" || w2_lower == "without" {
                    let saved2 = *i;
                    while *i < bytes.len() && bytes[*i].is_ascii_whitespace() {
                        *i += 1;
                    }
                    let w3_start = *i;
                    while *i < bytes.len()
                        && (bytes[*i].is_ascii_alphanumeric() || bytes[*i] == b'_')
                    {
                        *i += 1;
                    }
                    if *i > w3_start {
                        let w3 = String::from_utf8_lossy(&bytes[w3_start..*i]).to_string();
                        if w3.eq_ignore_ascii_case("time") {
                            type_name.push(' ');
                            type_name.push_str(&w3);
                            // Expect "zone"
                            while *i < bytes.len() && bytes[*i].is_ascii_whitespace() {
                                *i += 1;
                            }
                            let w4_start = *i;
                            while *i < bytes.len()
                                && (bytes[*i].is_ascii_alphanumeric() || bytes[*i] == b'_')
                            {
                                *i += 1;
                            }
                            if *i > w4_start {
                                let w4 = String::from_utf8_lossy(&bytes[w4_start..*i]).to_string();
                                type_name.push(' ');
                                type_name.push_str(&w4);
                            }
                        } else {
                            *i = saved2;
                        }
                    } else {
                        *i = saved2;
                    }
                }
            } else {
                *i = saved;
            }
        } else {
            *i = saved;
        }
    }
    // Check for type precision: (n) or (n, m)
    if *i < bytes.len() && bytes[*i] == b'(' {
        type_name.push('(');
        *i += 1;
        while *i < bytes.len() && bytes[*i] != b')' {
            type_name.push(bytes[*i] as char);
            *i += 1;
        }
        if *i < bytes.len() && bytes[*i] == b')' {
            type_name.push(')');
            *i += 1;
        }
    }
    // Map some PG type names to the shared engine's type inventory
    let tl = type_name.to_ascii_lowercase();
    match tl.as_str() {
        "int4" | "int" | "integer" => "SIGNED".to_string(),
        "int8" | "bigint" => "SIGNED".to_string(),
        "float4" | "real" => "DOUBLE".to_string(),
        "float8" | "double precision" => "DOUBLE".to_string(),
        "bool" | "boolean" => "CHAR".to_string(),
        "text" | "varchar" | "bpchar" | "name" | "regclass" => "CHAR".to_string(),
        "json" | "jsonb" => "JSON".to_string(),
        _ if tl.starts_with("varchar(") => type_name,
        _ if tl.starts_with("numeric(") => type_name,
        _ => type_name,
    }
}

/// Check if `keyword` (lowercase) matches at position `pos` as a whole keyword.
fn pg_match_keyword_at(bytes: &[u8], pos: usize, keyword: &str) -> bool {
    let kw_bytes = keyword.as_bytes();
    if pos + kw_bytes.len() > bytes.len() {
        return false;
    }
    // Check that the preceding character is not alphanumeric (word boundary)
    if pos > 0 && (bytes[pos - 1].is_ascii_alphanumeric() || bytes[pos - 1] == b'_') {
        return false;
    }
    // Case-insensitive match
    for (j, &kc) in kw_bytes.iter().enumerate() {
        if bytes[pos + j].to_ascii_lowercase() != kc {
            return false;
        }
    }
    // For keywords not ending with '[' or ' ', check trailing word boundary
    if !keyword.ends_with('[') && !keyword.ends_with(' ') {
        let end_pos = pos + kw_bytes.len();
        if end_pos < bytes.len()
            && (bytes[end_pos].is_ascii_alphanumeric() || bytes[end_pos] == b'_')
        {
            return false;
        }
    }
    true
}

/// Collect the body inside matching brackets [...], handling nesting.
/// Returns (body_text, bytes_consumed_including_closing_bracket).
fn pg_collect_bracket_body(bytes: &[u8], start: usize) -> (String, usize) {
    let mut depth = 1u32;
    let mut i = start;
    let mut body = String::new();
    let mut quote = 0u8;
    while i < bytes.len() && depth > 0 {
        let b = bytes[i];
        if quote != 0 {
            body.push(b as char);
            if b == quote {
                quote = 0;
            }
            i += 1;
            continue;
        }
        if b == b'\'' {
            quote = b'\'';
            body.push(b as char);
            i += 1;
            continue;
        }
        if b == b'[' {
            depth += 1;
            body.push('[');
            i += 1;
            continue;
        }
        if b == b']' {
            depth -= 1;
            if depth == 0 {
                i += 1; // consume closing ]
                break;
            }
            body.push(']');
            i += 1;
            continue;
        }
        body.push(b as char);
        i += 1;
    }
    (body, i - start)
}

/// Second pass: rewrite "IS DISTINCT FROM" into NOT(lhs <=> rhs).
/// This handles the case where the first pass emitted the literal text.
/// Rewrite PG `ON CONFLICT` to MySQL-compatible syntax.
///
/// - `ON CONFLICT DO NOTHING` → change INSERT INTO to INSERT IGNORE INTO
/// - `ON CONFLICT (...) DO UPDATE SET x = EXCLUDED.y` → `ON DUPLICATE KEY UPDATE x = VALUES(y)`
fn pg_rewrite_on_conflict(sql: &str) -> String {
    let lower = sql.to_ascii_lowercase();
    let Some(oc_pos) = lower.find("on conflict") else {
        return sql.to_string();
    };
    let after_oc = &lower[oc_pos + "on conflict".len()..];
    let after_oc_trimmed = after_oc.trim_start();

    // ON CONFLICT DO NOTHING → INSERT IGNORE INTO
    if after_oc_trimmed.starts_with("do nothing") {
        let before = &sql[..oc_pos];
        let do_nothing_offset =
            oc_pos + "on conflict".len() + (after_oc.len() - after_oc_trimmed.len()) + 10;
        let after = sql[do_nothing_offset..].trim_start();
        let mut result = before.trim_end().to_string();
        if !after.is_empty() {
            result.push(' ');
            result.push_str(after);
        }
        // Change INSERT INTO → INSERT IGNORE INTO
        let result_lower = result.to_ascii_lowercase();
        if let Some(insert_pos) = result_lower.find("insert into") {
            result.insert_str(insert_pos + 7, "IGNORE ");
        }
        return result;
    }

    // ON CONFLICT (cols) DO UPDATE SET ... EXCLUDED.col → VALUES(col)
    if let Some(do_update_offset) = after_oc_trimmed.find("do update set") {
        let set_start_in_after = do_update_offset + "do update set".len();
        let set_start_abs = oc_pos
            + "on conflict".len()
            + (after_oc.len() - after_oc_trimmed.len())
            + set_start_in_after;
        let set_clause = &sql[set_start_abs..];
        // Replace EXCLUDED.col with VALUES(col) in the SET clause
        let rewritten_set = pg_replace_excluded_refs(set_clause);
        let before = sql[..oc_pos].trim_end();
        return format!(
            "{} ON DUPLICATE KEY UPDATE {}",
            before,
            rewritten_set.trim()
        );
    }

    sql.to_string()
}

/// Replace `EXCLUDED.col` references with `VALUES(col)` in an ON CONFLICT SET clause.
fn pg_replace_excluded_refs(clause: &str) -> String {
    let bytes = clause.as_bytes();
    let mut out = String::with_capacity(clause.len());
    let mut i = 0;
    while i < bytes.len() {
        if (bytes[i] == b'e' || bytes[i] == b'E')
            && i + 9 <= bytes.len()
            && clause[i..i + 9].eq_ignore_ascii_case("excluded.")
        {
            i += 9;
            // Collect the column name
            let col_start = i;
            while i < bytes.len()
                && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_' || bytes[i] == b'`')
            {
                i += 1;
            }
            let col = &clause[col_start..i];
            let col_clean = col.trim_matches('`');
            out.push_str("VALUES(");
            out.push_str(col_clean);
            out.push(')');
        } else {
            out.push(bytes[i] as char);
            i += 1;
        }
    }
    out
}

fn pg_rewrite_is_distinct_from(sql: &str) -> String {
    let lower = sql.to_ascii_lowercase();
    if !lower.contains("is distinct from") {
        return sql.to_string();
    }
    // Simple keyword-level replacement for condition parsing

    // IS NOT DISTINCT FROM was already replaced with <=> in the first pass.
    // IS DISTINCT FROM needs to become a comparison the engine can handle.
    // The shared engine has null_safe_eq (<=>). IS DISTINCT FROM = NOT(a <=> b).
    // We can't trivially wrap in NOT() without understanding expression boundaries,
    // so we use a simpler approach: replace "IS DISTINCT FROM" with a custom op token
    // that parse_condition_expr can handle.
    // For now, the simplest correct approach is text replacement:
    // We'll add parser support for "IS DISTINCT FROM" in parse_condition_expr.
    sql.to_string()
}

#[allow(clippy::too_many_arguments)]
async fn pg_dispatch_sql(
    state: &AppState,
    stream: &mut TcpStream,
    session: &mut MySqlSessionState,
    tx_status: &mut pg_wire::TxStatus,
    savepoints: &mut Vec<PgSavepoint>,
    sql_raw: &str,
    described_columns: Option<&[MySqlStmtPrepareColumn]>,
    result_formats: &[i16],
) -> anyhow::Result<bool> {
    use crate::pg_wire::TxStatus;

    let sql = sql_raw.trim().trim_end_matches(';').trim();
    if sql.is_empty() {
        pg_wire::write_empty_query_response(stream).await?;
        return Ok(false);
    }

    let sql_lower = sql.to_ascii_lowercase();

    if *tx_status == TxStatus::Failed {
        if mysql_is_commit(sql) || mysql_is_rollback(sql) {
            match pg_rollback_full_transaction(state, session, savepoints).await {
                Ok(()) => {
                    pg_wire::write_command_complete(stream, "ROLLBACK").await?;
                    *tx_status = TxStatus::Idle;
                    return Ok(false);
                }
                Err((code, state_code, message)) => {
                    pg_wire::write_error_response(
                        stream,
                        "ERROR",
                        pg_sqlstate_from_mysql_error(code, state_code, &message),
                        &message,
                    )
                    .await?;
                    return Ok(true);
                }
            }
        }

        if let Some(name) = pg_parse_rollback_to_savepoint_name(sql) {
            match pg_rollback_to_savepoint(state, session, savepoints, &name).await {
                Ok(()) => {
                    *tx_status = TxStatus::InTransaction;
                    pg_wire::write_command_complete(stream, "ROLLBACK").await?;
                    return Ok(false);
                }
                Err((code, state_code, message)) => {
                    pg_wire::write_error_response(
                        stream,
                        "ERROR",
                        pg_sqlstate_from_mysql_error(code, state_code, &message),
                        &message,
                    )
                    .await?;
                    return Ok(true);
                }
            }
        }

        pg_wire::write_error_response(
            stream,
            "ERROR",
            "25P02",
            "current transaction is aborted, commands ignored until end of transaction block",
        )
        .await?;
        return Ok(true);
    }

    if sql_lower.starts_with("set ") {
        // Parse SET key = value  or  SET key TO value
        let rest = sql[4..].trim();
        if let Some((key, value)) = pg_parse_set_command(rest) {
            let key_lower = key.to_ascii_lowercase();
            session.pg_settings.insert(key_lower.clone(), value.clone());
            // Notify client of reportable parameter change
            pg_wire::write_parameter_status(stream, &key_lower, &value).await?;
        }
        pg_wire::write_command_complete(stream, "SET").await?;
        return Ok(false);
    }

    if sql_lower.starts_with("reset ") {
        let rest = sql[6..].trim().trim_end_matches(';').trim();
        let rest_lower = rest.to_ascii_lowercase();
        if rest_lower == "all" {
            session.pg_settings = pg_default_settings();
        } else {
            let key = rest_lower;
            let defaults = pg_default_settings();
            if let Some(val) = defaults.get(&key) {
                session.pg_settings.insert(key.clone(), val.clone());
                pg_wire::write_parameter_status(stream, &key, val).await?;
            } else {
                session.pg_settings.remove(&key);
            }
        }
        pg_wire::write_command_complete(stream, "RESET").await?;
        return Ok(false);
    }

    if mysql_is_begin(sql) {
        if *tx_status == TxStatus::Idle {
            session.tx_active = true;
            session.tx_undo_sql.clear();
            savepoints.clear();
        }
        *tx_status = TxStatus::InTransaction;
        pg_wire::write_command_complete(stream, "BEGIN").await?;
        return Ok(false);
    }

    if mysql_is_commit(sql) || sql.eq_ignore_ascii_case("end") {
        session.tx_active = false;
        session.tx_undo_sql.clear();
        savepoints.clear();
        *tx_status = TxStatus::Idle;
        pg_wire::write_command_complete(stream, "COMMIT").await?;
        return Ok(false);
    }

    if mysql_is_rollback(sql) {
        match pg_rollback_full_transaction(state, session, savepoints).await {
            Ok(()) => {
                *tx_status = TxStatus::Idle;
                pg_wire::write_command_complete(stream, "ROLLBACK").await?;
                return Ok(false);
            }
            Err((code, state_code, message)) => {
                pg_wire::write_error_response(
                    stream,
                    "ERROR",
                    pg_sqlstate_from_mysql_error(code, state_code, &message),
                    &message,
                )
                .await?;
                *tx_status = pg_tx_status_for_session(session, false);
                return Ok(true);
            }
        }
    }

    if let Some(name) = pg_parse_savepoint_name(sql) {
        if *tx_status != TxStatus::InTransaction {
            pg_wire::write_error_response(
                stream,
                "ERROR",
                "25P01",
                "SAVEPOINT can only be used in transaction blocks",
            )
            .await?;
            return Ok(true);
        }
        savepoints.push(PgSavepoint {
            name,
            undo_len: session.tx_undo_sql.len(),
        });
        pg_wire::write_command_complete(stream, "SAVEPOINT").await?;
        return Ok(false);
    }

    if let Some(name) = pg_parse_release_savepoint_name(sql) {
        if *tx_status != TxStatus::InTransaction {
            pg_wire::write_error_response(
                stream,
                "ERROR",
                "25P01",
                "RELEASE SAVEPOINT can only be used in transaction blocks",
            )
            .await?;
            return Ok(true);
        }
        match pg_release_savepoint(savepoints, &name) {
            Ok(()) => {
                pg_wire::write_command_complete(stream, "RELEASE").await?;
                return Ok(false);
            }
            Err((code, state_code, message)) => {
                pg_wire::write_error_response(
                    stream,
                    "ERROR",
                    pg_sqlstate_from_mysql_error(code, state_code, &message),
                    &message,
                )
                .await?;
                return Ok(true);
            }
        }
    }

    if let Some(name) = pg_parse_rollback_to_savepoint_name(sql) {
        if *tx_status != TxStatus::InTransaction {
            pg_wire::write_error_response(
                stream,
                "ERROR",
                "25P01",
                "ROLLBACK TO SAVEPOINT can only be used in transaction blocks",
            )
            .await?;
            return Ok(true);
        }
        match pg_rollback_to_savepoint(state, session, savepoints, &name).await {
            Ok(()) => {
                *tx_status = TxStatus::InTransaction;
                pg_wire::write_command_complete(stream, "ROLLBACK").await?;
                return Ok(false);
            }
            Err((code, state_code, message)) => {
                pg_wire::write_error_response(
                    stream,
                    "ERROR",
                    pg_sqlstate_from_mysql_error(code, state_code, &message),
                    &message,
                )
                .await?;
                return Ok(true);
            }
        }
    }

    if pg_try_handle_bootstrap_query(stream, sql, session.default_db.as_deref(), Some(&*session))
        .await?
    {
        return Ok(false);
    }

    // COPY FROM STDIN / COPY TO STDOUT — not yet supported
    if sql_lower.starts_with("copy ") {
        pg_wire::write_error_response(stream, "ERROR", "0A000", "COPY is not yet supported")
            .await?;
        *tx_status = pg_tx_status_for_session(session, session.tx_active);
        return Ok(true);
    }

    // Extract and strip RETURNING clause from DML (PG-specific)
    let (sql_without_returning, returning_cols) = pg_extract_returning(sql);
    let sql_for_rewrite = if returning_cols.is_some() {
        &sql_without_returning
    } else {
        sql
    };

    // Rewrite PG-specific SQL syntax before feeding to the shared engine
    let rewritten = pg_rewrite_sql(sql_for_rewrite);
    let sql = &rewritten;

    match mysql_execute_sql(state, sql, session).await {
        Ok(MySqlQueryOutcome::ResultSet { columns, rows }) => {
            let default_db = session.default_db.clone();
            let mut pg_columns = pg_result_columns_to_pg(
                state,
                sql,
                default_db.as_deref(),
                &columns,
                &rows,
                described_columns,
            )
            .await;
            // Apply result format codes from Bind to PgColumn.format
            for (idx, col) in pg_columns.iter_mut().enumerate() {
                col.format = pg_format_code_at(result_formats, idx);
            }
            pg_wire::write_row_description(stream, &pg_columns).await?;
            for row in &rows {
                let encoded_values: Vec<Option<Vec<u8>>> = row
                    .iter()
                    .enumerate()
                    .map(|(idx, value)| {
                        let col = pg_columns.get(idx);
                        if col.map(|c| c.format) == Some(1) {
                            // Binary format requested
                            let type_oid = col.map(|c| c.type_oid).unwrap_or(0);
                            match value.as_deref() {
                                None => None,
                                Some(v) => pg_wire::encode_binary_value(type_oid, v)
                                    .or_else(|| Some(v.as_bytes().to_vec())),
                            }
                        } else {
                            pg_text_value_for_column(value.as_deref(), col)
                        }
                    })
                    .collect();
                let values: Vec<Option<&[u8]>> = encoded_values
                    .iter()
                    .map(|value| value.as_deref())
                    .collect();
                pg_wire::write_data_row(stream, &values).await?;
            }
            let tag = format!("SELECT {}", rows.len());
            pg_wire::write_command_complete(stream, &tag).await?;
            *tx_status = pg_tx_status_for_session(session, false);
            Ok(false)
        }
        Ok(MySqlQueryOutcome::Ok {
            affected_rows,
            last_insert_id,
        }) => {
            // INSERT/UPDATE/DELETE with RETURNING — do a follow-up SELECT to get the data
            if let Some(ref ret_cols) = returning_cols {
                if affected_rows > 0 && last_insert_id > 0 && sql_lower.starts_with("insert") {
                    if let Some(table_name) = pg_extract_insert_table(&sql_lower) {
                        let select_cols = if ret_cols.len() == 1 && ret_cols[0] == "*" {
                            "*".to_string()
                        } else {
                            ret_cols.join(", ")
                        };
                        // Look up PK column from engine schema
                        let pk_col =
                            pg_lookup_pk_column(state, &table_name, session.default_db.as_deref())
                                .await;
                        let follow_up = format!(
                            "SELECT {} FROM {} WHERE {} = {}",
                            select_cols, table_name, pk_col, last_insert_id
                        );
                        if let Ok(MySqlQueryOutcome::ResultSet { columns, rows }) =
                            mysql_execute_sql(state, &follow_up, session).await
                        {
                            let default_db = session.default_db.clone();
                            let mut pg_columns = pg_result_columns_to_pg(
                                state,
                                &follow_up,
                                default_db.as_deref(),
                                &columns,
                                &rows,
                                described_columns,
                            )
                            .await;
                            for (idx, col) in pg_columns.iter_mut().enumerate() {
                                col.format = pg_format_code_at(result_formats, idx);
                            }
                            pg_wire::write_row_description(stream, &pg_columns).await?;
                            for row in &rows {
                                let encoded_values: Vec<Option<Vec<u8>>> = row
                                    .iter()
                                    .enumerate()
                                    .map(|(idx, value)| {
                                        let col = pg_columns.get(idx);
                                        if col.map(|c| c.format) == Some(1) {
                                            let type_oid = col.map(|c| c.type_oid).unwrap_or(0);
                                            match value.as_deref() {
                                                None => None,
                                                Some(v) => {
                                                    pg_wire::encode_binary_value(type_oid, v)
                                                        .or_else(|| Some(v.as_bytes().to_vec()))
                                                }
                                            }
                                        } else {
                                            pg_text_value_for_column(value.as_deref(), col)
                                        }
                                    })
                                    .collect();
                                let values: Vec<Option<&[u8]>> = encoded_values
                                    .iter()
                                    .map(|value| value.as_deref())
                                    .collect();
                                pg_wire::write_data_row(stream, &values).await?;
                            }
                            let tag = pg_command_tag_for_sql(&sql_lower, affected_rows);
                            pg_wire::write_command_complete(stream, &tag).await?;
                            *tx_status = pg_tx_status_for_session(session, false);
                            return Ok(false);
                        }
                    }
                }
                // Fallback for UPDATE/DELETE RETURNING or failed follow-up:
                // return empty result set with column headers
                let pg_columns: Vec<pg_wire::PgColumn> = ret_cols
                    .iter()
                    .map(|c| pg_wire::PgColumn::text(c, pg_wire::oid::TEXT, -1))
                    .collect();
                pg_wire::write_row_description(stream, &pg_columns).await?;
                let tag = pg_command_tag_for_sql(&sql_lower, affected_rows);
                pg_wire::write_command_complete(stream, &tag).await?;
                *tx_status = pg_tx_status_for_session(session, false);
                return Ok(false);
            }
            let tag = pg_command_tag_for_sql(&sql_lower, affected_rows);
            pg_wire::write_command_complete(stream, &tag).await?;
            *tx_status = pg_tx_status_for_session(session, false);
            Ok(false)
        }
        Err((code, state_code, message)) => {
            pg_wire::write_error_response(
                stream,
                "ERROR",
                pg_sqlstate_from_mysql_error(code, state_code, &message),
                &message,
            )
            .await?;
            *tx_status = pg_tx_status_for_session(session, session.tx_active);
            Ok(true)
        }
    }
}

async fn handle_pg_connection(
    state: AppState,
    mut stream: TcpStream,
    connection_id: u32,
) -> anyhow::Result<()> {
    use crate::pg_wire::{self, frontend, TxStatus};

    // SSL negotiation loop: reject SSL and wait for real startup.
    let startup = loop {
        match pg_wire::read_startup_message(&mut stream).await? {
            Some(msg) => break msg,
            None => {
                // SSLRequest — reject with 'N'.
                stream.write_u8(b'N').await?;
                stream.flush().await?;
            }
        }
    };

    if startup.protocol_version != pg_wire::PG_PROTOCOL_V3 {
        pg_wire::write_error_response(
            &mut stream,
            "FATAL",
            "08P01",
            &format!("unsupported protocol version: {}", startup.protocol_version),
        )
        .await?;
        return Ok(());
    }

    let username = startup.user().unwrap_or("skein").to_string();
    let database = startup
        .database()
        .or(Some(&username))
        .map(|s| s.to_string());

    // Authentication: trust when SKEINDB_TOKEN is unset, SCRAM-SHA-256 otherwise.
    if let Ok(expected_password) = std::env::var("SKEINDB_TOKEN") {
        // Derive SCRAM credentials from the token.
        let scram_salt = pg_scram_salt_for_token(&expected_password);
        let scram_creds =
            pg_wire::scram::ScramCredentials::from_password(&expected_password, &scram_salt, 4096);

        // Offer SCRAM-SHA-256 as the SASL mechanism.
        pg_wire::write_auth_sasl(&mut stream, &[pg_wire::SCRAM_SHA256_NAME]).await?;

        // Step 1: Read SASLInitialResponse (client-first-message)
        let msg = pg_wire::read_message(&mut stream).await?;
        if msg.tag != frontend::PASSWORD_MESSAGE {
            pg_wire::write_error_response(
                &mut stream,
                "FATAL",
                "28000",
                "expected SASL initial response",
            )
            .await?;
            return Ok(());
        }

        let (mechanism, client_first) = match pg_wire::parse_sasl_initial_response(&msg.payload) {
            Some(pair) => pair,
            None => {
                pg_wire::write_error_response(
                    &mut stream,
                    "FATAL",
                    "08P01",
                    "malformed SASL initial response",
                )
                .await?;
                return Ok(());
            }
        };

        if mechanism != pg_wire::SCRAM_SHA256_NAME {
            pg_wire::write_error_response(
                &mut stream,
                "FATAL",
                "0A000",
                &format!("unsupported SASL mechanism: {mechanism}"),
            )
            .await?;
            return Ok(());
        }

        // Process client-first, generate server-first.
        let (scram_state, server_first) =
            match pg_wire::scram::ScramServer::process_client_first(&client_first, &scram_creds) {
                Ok(pair) => pair,
                Err(err) => {
                    pg_wire::write_error_response(&mut stream, "FATAL", "28000", &err).await?;
                    return Ok(());
                }
            };

        pg_wire::write_auth_sasl_continue(&mut stream, &server_first).await?;

        // Step 2: Read SASLResponse (client-final-message)
        let msg = pg_wire::read_message(&mut stream).await?;
        if msg.tag != frontend::PASSWORD_MESSAGE {
            pg_wire::write_error_response(&mut stream, "FATAL", "28000", "expected SASL response")
                .await?;
            return Ok(());
        }

        let client_final = pg_wire::parse_sasl_response(&msg.payload);

        // Verify client proof, generate server signature.
        let server_final = match scram_state.process_client_final(&client_final) {
            Ok(sf) => sf,
            Err(_) => {
                pg_wire::write_error_response(
                    &mut stream,
                    "FATAL",
                    "28P01",
                    "password authentication failed",
                )
                .await?;
                return Ok(());
            }
        };

        pg_wire::write_auth_sasl_final(&mut stream, &server_final).await?;
    }

    pg_wire::write_auth_ok(&mut stream).await?;

    // Send initial ParameterStatus messages (matches what psql expects).
    pg_wire::write_parameter_status(&mut stream, "server_version", pg_wire::PG_SERVER_VERSION)
        .await?;
    pg_wire::write_parameter_status(&mut stream, "server_encoding", "UTF8").await?;
    pg_wire::write_parameter_status(&mut stream, "client_encoding", "UTF8").await?;
    pg_wire::write_parameter_status(&mut stream, "DateStyle", "ISO, MDY").await?;
    pg_wire::write_parameter_status(&mut stream, "TimeZone", "UTC").await?;
    pg_wire::write_parameter_status(&mut stream, "standard_conforming_strings", "on").await?;
    pg_wire::write_parameter_status(&mut stream, "integer_datetimes", "on").await?;
    pg_wire::write_parameter_status(&mut stream, "is_superuser", "on").await?;

    pg_wire::write_backend_key_data(&mut stream, connection_id as i32, 0).await?;
    pg_wire::write_ready_for_query(&mut stream, TxStatus::Idle).await?;

    let mut session = MySqlSessionState::new(database, connection_id);
    let mut tx_status = TxStatus::Idle;
    let mut savepoints = Vec::new();
    let mut prepared_statements: HashMap<String, PgPreparedStatement> = HashMap::new();
    let mut portals: HashMap<String, PgPortal> = HashMap::new();
    let mut skip_until_sync = false;

    // Command loop.
    loop {
        let msg = match pg_wire::read_message(&mut stream).await {
            Ok(m) => m,
            Err(err) => {
                let disconnect = err
                    .downcast_ref::<std::io::Error>()
                    .map(|io| {
                        matches!(
                            io.kind(),
                            std::io::ErrorKind::UnexpectedEof
                                | std::io::ErrorKind::ConnectionReset
                                | std::io::ErrorKind::BrokenPipe
                        )
                    })
                    .unwrap_or(false);
                if disconnect {
                    return Ok(());
                }
                return Err(err);
            }
        };

        if skip_until_sync && !matches!(msg.tag, frontend::SYNC | frontend::TERMINATE) {
            continue;
        }

        match msg.tag {
            frontend::TERMINATE => {
                return Ok(());
            }
            frontend::QUERY => {
                prepared_statements.remove("");
                portals.remove("");
                let sql_raw = pg_wire::parse_query(&msg.payload);
                let _ = pg_dispatch_sql(
                    &state,
                    &mut stream,
                    &mut session,
                    &mut tx_status,
                    &mut savepoints,
                    &sql_raw,
                    None,
                    &[],
                )
                .await?;
                pg_wire::write_ready_for_query(&mut stream, tx_status).await?;
            }
            frontend::SYNC => {
                skip_until_sync = false;
                portals.remove("");
                pg_wire::write_ready_for_query(&mut stream, tx_status).await?;
            }
            frontend::PARSE => {
                let mut offset = 0usize;
                let (statement_name, next_offset) =
                    pg_wire::read_cstring_from(&msg.payload, offset);
                offset = next_offset;
                let (sql, next_offset) = pg_wire::read_cstring_from(&msg.payload, offset);
                offset = next_offset;
                let param_type_count =
                    pg_read_i16_be(&msg.payload, &mut offset).map_err(anyhow::Error::msg)?;
                if param_type_count < 0 {
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        "08P01",
                        "negative parameter type count in Parse message",
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                }
                let mut param_types = Vec::with_capacity(param_type_count as usize);
                for _ in 0..param_type_count as usize {
                    param_types.push(
                        pg_read_i32_be(&msg.payload, &mut offset).map_err(anyhow::Error::msg)?,
                    );
                }

                let placeholder_count = pg_max_placeholder_index(&sql);
                if param_types.len() < placeholder_count {
                    param_types.resize(placeholder_count, 0);
                }

                let describe_sql = if placeholder_count == 0 {
                    sql.clone()
                } else {
                    let default_params: Vec<Lit> = param_types
                        .iter()
                        .map(|type_oid| pg_default_lit_for_oid(*type_oid))
                        .collect();
                    pg_substitute_stmt_sql(&sql, &default_params).unwrap_or_else(|_| sql.clone())
                };
                let result_columns = mysql_stmt_prepare_columns(
                    &state,
                    &describe_sql,
                    session.default_db.as_deref(),
                )
                .await;

                if statement_name.is_empty() {
                    portals.remove("");
                }
                prepared_statements.insert(
                    statement_name,
                    PgPreparedStatement {
                        sql,
                        param_types,
                        result_columns,
                    },
                );
                pg_wire::write_parse_complete(&mut stream).await?;
            }
            frontend::BIND => {
                let mut offset = 0usize;
                let (portal_name, next_offset) = pg_wire::read_cstring_from(&msg.payload, offset);
                offset = next_offset;
                let (statement_name, next_offset) =
                    pg_wire::read_cstring_from(&msg.payload, offset);
                offset = next_offset;

                let Some(statement) = prepared_statements.get(&statement_name).cloned() else {
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        "26000",
                        &format!("unknown prepared statement '{statement_name}'"),
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                };

                let param_format_count =
                    pg_read_i16_be(&msg.payload, &mut offset).map_err(anyhow::Error::msg)?;
                if param_format_count < 0 {
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        "08P01",
                        "negative parameter format count in Bind message",
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                }
                let mut param_formats = Vec::with_capacity(param_format_count as usize);
                for _ in 0..param_format_count as usize {
                    param_formats.push(
                        pg_read_i16_be(&msg.payload, &mut offset).map_err(anyhow::Error::msg)?,
                    );
                }

                let param_count =
                    pg_read_i16_be(&msg.payload, &mut offset).map_err(anyhow::Error::msg)?;
                if param_count < 0 {
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        "08P01",
                        "negative parameter count in Bind message",
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                }
                let param_count = param_count as usize;
                if param_count != statement.param_types.len() {
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        "08P01",
                        &format!(
                            "bind parameter count mismatch: expected {}, got {param_count}",
                            statement.param_types.len()
                        ),
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                }
                if let Err(message) =
                    pg_validate_format_codes(&param_formats, param_count, "parameter")
                {
                    pg_wire::write_error_response(&mut stream, "ERROR", "08P01", &message).await?;
                    skip_until_sync = true;
                    continue;
                }

                let mut params = Vec::with_capacity(param_count);
                let mut bind_error = None::<(String, &'static str)>;
                for idx in 0..param_count {
                    let value_len = match pg_read_i32_be(&msg.payload, &mut offset) {
                        Ok(value) => value,
                        Err(message) => {
                            bind_error = Some((message, "08P01"));
                            break;
                        }
                    };
                    if value_len == -1 {
                        params.push(Lit::Null);
                        continue;
                    }
                    if value_len < -1 {
                        bind_error = Some((
                            "invalid negative parameter length in Bind message".to_string(),
                            "08P01",
                        ));
                        break;
                    }
                    let format_code = pg_format_code_at(&param_formats, idx);
                    if format_code != 0 {
                        bind_error = Some((
                            "binary parameter formats are not supported yet".to_string(),
                            "0A000",
                        ));
                        break;
                    }
                    let end = offset.saturating_add(value_len as usize);
                    let Some(bytes) = msg.payload.get(offset..end) else {
                        bind_error = Some((
                            "truncated parameter payload in Bind message".to_string(),
                            "08P01",
                        ));
                        break;
                    };
                    offset = end;
                    let text = String::from_utf8_lossy(bytes).into_owned();
                    let type_oid = statement.param_types.get(idx).copied().unwrap_or(0);
                    params.push(pg_decode_text_param_lit(&text, type_oid));
                }

                let result_format_count =
                    pg_read_i16_be(&msg.payload, &mut offset).map_err(anyhow::Error::msg)?;
                if result_format_count < 0 {
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        "08P01",
                        "negative result format count in Bind message",
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                }
                let mut result_formats = Vec::with_capacity(result_format_count as usize);
                for _ in 0..result_format_count as usize {
                    result_formats.push(
                        pg_read_i16_be(&msg.payload, &mut offset).map_err(anyhow::Error::msg)?,
                    );
                }
                if bind_error.is_none() {
                    if let Err(message) = pg_validate_format_codes(
                        &result_formats,
                        statement.result_columns.len(),
                        "result-column",
                    ) {
                        bind_error = Some((message, "08P01"));
                    }
                }
                if let Some((message, sqlstate)) = bind_error {
                    pg_wire::write_error_response(&mut stream, "ERROR", sqlstate, &message).await?;
                    skip_until_sync = true;
                    continue;
                }

                portals.insert(
                    portal_name,
                    PgPortal {
                        sql: statement.sql,
                        params,
                        result_columns: statement.result_columns,
                        result_formats,
                    },
                );
                pg_wire::write_bind_complete(&mut stream).await?;
            }
            frontend::DESCRIBE => {
                let Some(kind) = msg.payload.first().copied() else {
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        "08P01",
                        "Describe message missing target kind",
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                };
                let (name, _) = pg_wire::read_cstring_from(&msg.payload, 1);
                match kind {
                    b'S' => {
                        let Some(statement) = prepared_statements.get(&name) else {
                            pg_wire::write_error_response(
                                &mut stream,
                                "ERROR",
                                "26000",
                                &format!("unknown prepared statement '{name}'"),
                            )
                            .await?;
                            skip_until_sync = true;
                            continue;
                        };
                        pg_wire::write_parameter_description(&mut stream, &statement.param_types)
                            .await?;
                        pg_write_prepare_row_description(&mut stream, &statement.result_columns)
                            .await?;
                    }
                    b'P' => {
                        let Some(portal) = portals.get(&name) else {
                            pg_wire::write_error_response(
                                &mut stream,
                                "ERROR",
                                "34000",
                                &format!("unknown portal '{name}'"),
                            )
                            .await?;
                            skip_until_sync = true;
                            continue;
                        };
                        pg_write_prepare_row_description(&mut stream, &portal.result_columns)
                            .await?;
                    }
                    _ => {
                        pg_wire::write_error_response(
                            &mut stream,
                            "ERROR",
                            "08P01",
                            "Describe target kind must be 'S' or 'P'",
                        )
                        .await?;
                        skip_until_sync = true;
                        continue;
                    }
                }
            }
            frontend::EXECUTE => {
                let (portal_name, mut offset) = pg_wire::read_cstring_from(&msg.payload, 0);
                let max_rows = match pg_read_i32_be(&msg.payload, &mut offset) {
                    Ok(value) => value,
                    Err(message) => {
                        pg_wire::write_error_response(&mut stream, "ERROR", "08P01", &message)
                            .await?;
                        skip_until_sync = true;
                        continue;
                    }
                };
                if max_rows < 0 {
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        "08P01",
                        "Execute row limit must be non-negative",
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                }

                let Some(portal) = portals.get(&portal_name).cloned() else {
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        "34000",
                        &format!("unknown portal '{portal_name}'"),
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                };
                let exec_sql = match pg_substitute_stmt_sql(&portal.sql, &portal.params) {
                    Ok(sql) => sql,
                    Err(message) => {
                        pg_wire::write_error_response(&mut stream, "ERROR", "08P01", &message)
                            .await?;
                        skip_until_sync = true;
                        continue;
                    }
                };
                let had_error = pg_dispatch_sql(
                    &state,
                    &mut stream,
                    &mut session,
                    &mut tx_status,
                    &mut savepoints,
                    &exec_sql,
                    Some(&portal.result_columns),
                    &portal.result_formats,
                )
                .await?;
                if had_error {
                    skip_until_sync = true;
                }
            }
            frontend::CLOSE => {
                let Some(kind) = msg.payload.first().copied() else {
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        "08P01",
                        "Close message missing target kind",
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                };
                let (name, _) = pg_wire::read_cstring_from(&msg.payload, 1);
                let removed = match kind {
                    b'S' => prepared_statements.remove(&name).is_some(),
                    b'P' => portals.remove(&name).is_some(),
                    _ => {
                        pg_wire::write_error_response(
                            &mut stream,
                            "ERROR",
                            "08P01",
                            "Close target kind must be 'S' or 'P'",
                        )
                        .await?;
                        skip_until_sync = true;
                        continue;
                    }
                };
                if !removed {
                    let (sqlstate, object_type) = if kind == b'S' {
                        ("26000", "prepared statement")
                    } else {
                        ("34000", "portal")
                    };
                    pg_wire::write_error_response(
                        &mut stream,
                        "ERROR",
                        sqlstate,
                        &format!("unknown {object_type} '{name}'"),
                    )
                    .await?;
                    skip_until_sync = true;
                    continue;
                }
                pg_wire::write_close_complete(&mut stream).await?;
            }
            frontend::FLUSH => {
                stream.flush().await?;
            }
            _ => {
                pg_wire::write_error_response(
                    &mut stream,
                    "ERROR",
                    "0A000",
                    &format!("unsupported message type: {}", char::from(msg.tag)),
                )
                .await?;
                pg_wire::write_ready_for_query(&mut stream, tx_status).await?;
            }
        }
    }
}

async fn run_pg_listener(
    state: AppState,
    bind: String,
    pg_port: u16,
    mut shutdown_rx: watch::Receiver<bool>,
) -> anyhow::Result<()> {
    if pg_port == 0 {
        return Ok(());
    }
    let addr = format!("{}:{}", bind, pg_port);
    let listener = tokio::net::TcpListener::bind(&addr).await?;
    tracing::info!(pg_addr = %addr, "PostgreSQL listening");
    let mut connection_id: u32 = 100_000; // offset from MySQL connection IDs
    loop {
        tokio::select! {
            _ = shutdown_rx.changed() => {
                break;
            }
            accepted = listener.accept() => {
                let (stream, peer_addr) = match accepted {
                    Ok(v) => v,
                    Err(err) => {
                        tracing::warn!(?err, "PG accept failed");
                        continue;
                    }
                };
                let cid = connection_id;
                connection_id = connection_id.wrapping_add(1).max(100_000);
                let state = state.clone();
                tokio::spawn(async move {
                    if let Err(err) = handle_pg_connection(state, stream, cid).await {
                        tracing::debug!(%peer_addr, ?err, "PG connection failed");
                    }
                });
            }
        }
    }
    Ok(())
}

async fn run_mysql_listener(
    state: AppState,
    bind: String,
    mysql_port: u16,
    mut shutdown_rx: watch::Receiver<bool>,
) -> anyhow::Result<()> {
    if mysql_port == 0 {
        return Ok(());
    }
    let addr = format!("{}:{}", bind, mysql_port);
    let listener = tokio::net::TcpListener::bind(&addr).await?;
    tracing::info!(mysql_addr = %addr, "MySQL listening");
    let mut connection_id: u32 = 1;
    loop {
        tokio::select! {
            _ = shutdown_rx.changed() => {
                break;
            }
            accepted = listener.accept() => {
                let (stream, peer_addr) = match accepted {
                    Ok(v) => v,
                    Err(err) => {
                        tracing::warn!(?err, "MySQL accept failed");
                        continue;
                    }
                };
                let cid = connection_id;
                connection_id = connection_id.wrapping_add(1).max(1);
                let state = state.clone();
                tokio::spawn(async move {
                    if let Err(err) = handle_mysql_connection(state, stream, cid).await {
                        tracing::debug!(%peer_addr, ?err, "MySQL handshake failed");
                    }
                });
            }
        }
    }
    Ok(())
}

pub async fn serve(opts: ServeOpts) -> anyhow::Result<()> {
    let http_addr: SocketAddr = format!("{}:{}", opts.bind, opts.http_port).parse()?;

    // Ensure data dir exists.
    let data_dir = PathBuf::from(&opts.data_dir);
    std::fs::create_dir_all(&data_dir)?;

    let engine = Engine::open_with_storage_mode_name(&data_dir, &opts.storage_mode)?;
    let advertised_host = if opts.bind == "0.0.0.0" {
        "127.0.0.1".to_string()
    } else {
        opts.bind.clone()
    };
    let local_rpc_url = format!("http://{}:{}", advertised_host, opts.http_port);
    let local_node_id = format!(
        "node-{}-{}",
        advertised_host.replace('.', "-"),
        opts.cluster_port
    );
    let transport = TransportCapabilities {
        http: true,
        quic: opts.quic_port.is_some(),
    };
    let (shutdown_tx, mut shutdown_rx) = watch::channel(false);
    let (etag_tx, _) = tokio::sync::broadcast::channel::<String>(64);

    let state = AppState {
        started: Instant::now(),
        data_dir,
        local_rpc_url: local_rpc_url.clone(),
        settings: Arc::new(Mutex::new(serde_json::Map::new())),
        cluster: Arc::new(Mutex::new(ClusterStateModel::bootstrap(
            local_node_id,
            local_rpc_url,
        ))),
        counters: Arc::new(Mutex::new(Counters::default())),
        txns: Arc::new(Mutex::new(HashMap::new())),
        engine: Arc::new(RwLock::new(engine)),
        subs: Arc::new(Mutex::new(Subscriptions::default())),
        coalesce: Arc::new(QueryCoalescer::default()),
        transport,
        shutdown_tx,
        etag_notify: Arc::new(etag_tx),
    };

    // Load persisted settings if present.
    load_settings(&state).ok();
    load_cluster_state(&state).ok();

    let app_state = state.clone();
    let app = Router::new()
        .route("/api/v1/rpc", post(rpc_handler))
        .route("/api/v1/sql/exec", post(sql_exec_http_handler))
        .route("/api/v1/q/:query_id", get(prepared_get_handler))
        .route("/api/v1/q/:query_id/events", get(prepared_sse_handler))
        .route("/api/v1/cdc/sse/:sub_id", get(cdc_sse_handler))
        .route("/metrics", get(metrics_handler))
        .route("/health", get(health_handler))
        .route("/console", get(console_handler))
        .route("/console/", get(console_handler))
        .route("/console/src/main.js", get(console_main_js_handler))
        .route("/admin", get(admin_handler))
        .route("/admin/", get(admin_handler))
        .route("/admin/src/main.js", get(admin_main_js_handler))
        .route("/src/main.js", get(admin_main_js_handler))
        .with_state(state)
        .layer(
            CorsLayer::new()
                .allow_origin(Any)
                .allow_methods([Method::GET, Method::POST, Method::OPTIONS])
                .allow_headers(Any),
        );

    let quic_handle = if let Some(quic_port) = opts.quic_port {
        let cert_path = opts
            .quic_cert
            .clone()
            .ok_or_else(|| anyhow::anyhow!("--quic-cert is required when --quic is set"))?;
        let key_path = opts
            .quic_key
            .clone()
            .ok_or_else(|| anyhow::anyhow!("--quic-key is required when --quic is set"))?;
        let quic_opts = quic::QuicServeOpts {
            bind: opts.bind.clone(),
            port: quic_port,
            cert_path,
            key_path,
        };
        let state = app_state.clone();
        Some(tokio::spawn(async move {
            if let Err(err) = quic::serve_quic(state, quic_opts).await {
                tracing::error!(?err, "QUIC server failed");
            }
        }))
    } else {
        None
    };
    let mysql_handle = if opts.mysql_port == 0 {
        None
    } else {
        let state = app_state.clone();
        let bind = opts.bind.clone();
        let mysql_port = opts.mysql_port;
        let shutdown_rx = app_state.shutdown_tx.subscribe();
        Some(tokio::spawn(async move {
            if let Err(err) = run_mysql_listener(state, bind, mysql_port, shutdown_rx).await {
                tracing::error!(?err, "MySQL listener failed");
            }
        }))
    };
    let pg_handle = if opts.pg_port == 0 {
        None
    } else {
        let state = app_state.clone();
        let bind = opts.bind.clone();
        let pg_port = opts.pg_port;
        let shutdown_rx = app_state.shutdown_tx.subscribe();
        Some(tokio::spawn(async move {
            if let Err(err) = run_pg_listener(state, bind, pg_port, shutdown_rx).await {
                tracing::error!(?err, "PostgreSQL listener failed");
            }
        }))
    };

    tracing::info!(
        bind = %opts.bind,
        http_port = %opts.http_port,
        mysql_port = %opts.mysql_port,
        pg_port = %opts.pg_port,
        cluster_port = %opts.cluster_port,
        storage_mode = %opts.storage_mode,
        "SkeinDB server starting"
    );
    print_startup_banner(&opts);
    if opts.mysql_port == 0 {
        tracing::info!("MySQL listener disabled (--mysql 0)");
    } else {
        tracing::info!(
            "MySQL listener enabled (handshake/auth + COM_QUERY plus baseline COM_STMT_* compatibility via sql.exec translator)"
        );
    }
    if opts.pg_port == 0 {
        tracing::info!("PostgreSQL listener disabled (--pg 0)");
    } else {
        tracing::info!(
            "PostgreSQL v3 listener enabled (simple + extended query protocol, trust/SCRAM auth)"
        );
    }

    let listener = tokio::net::TcpListener::bind(http_addr).await?;
    tracing::info!(%http_addr, "HTTP listening");

    let shutdown_requested = Arc::new(AtomicBool::new(false));
    let shutdown_flag = shutdown_requested.clone();
    axum::serve(listener, app)
        .with_graceful_shutdown(async move {
            tokio::select! {
                _ = shutdown_signal() => {},
                changed = shutdown_rx.changed() => {
                    if changed.is_ok() {
                        tracing::info!("shutdown requested via system.shutdown");
                    }
                }
            }
            shutdown_flag.store(true, Ordering::SeqCst);
        })
        .await?;

    if let Some(handle) = quic_handle {
        handle.abort();
    }
    if let Some(handle) = mysql_handle {
        handle.abort();
    }
    if let Some(handle) = pg_handle {
        handle.abort();
    }

    if shutdown_requested.load(Ordering::SeqCst) {
        run_shutdown_tasks(&app_state).await;
    }

    Ok(())
}

async fn shutdown_signal() {
    #[cfg(unix)]
    {
        if let Ok(mut sigterm) =
            tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
        {
            tokio::select! {
                _ = tokio::signal::ctrl_c() => {},
                _ = sigterm.recv() => {},
            }
        } else {
            let _ = tokio::signal::ctrl_c().await;
        }
    }

    #[cfg(not(unix))]
    {
        let _ = tokio::signal::ctrl_c().await;
    }

    tracing::info!("shutdown signal received");
}

async fn run_shutdown_tasks(state: &AppState) {
    if let Err(err) = checkpoint_engine_for_shutdown(state).await {
        tracing::warn!(error = %err, "shutdown checkpoint failed");
    }
    if let Err(err) = mark_local_node_offline(state) {
        tracing::warn!(error = %err, "failed to mark local node offline");
    }
    if let Err(err) = notify_cluster_node_leave(state).await {
        tracing::warn!(error = %err, "failed to notify peers about node leave");
    }
}

async fn checkpoint_engine_for_shutdown(state: &AppState) -> anyhow::Result<()> {
    let mut engine = state.engine.write().await;
    engine.checkpoint_for_shutdown()
}

fn mark_local_node_offline(state: &AppState) -> anyhow::Result<()> {
    let now = now_unix_ms_u64();
    {
        let mut cluster = state.cluster.lock().unwrap();
        let local_node_id = cluster.local_node_id.clone();
        let Some(local_node) = cluster
            .nodes
            .iter_mut()
            .find(|n| n.node_id == local_node_id)
        else {
            return Ok(());
        };
        local_node.status = "offline".to_string();
        local_node.last_seen_ms = now;
    }
    persist_cluster_state(state)?;
    Ok(())
}

async fn notify_cluster_node_leave(state: &AppState) -> anyhow::Result<()> {
    let (enabled, local_node_id, targets) = {
        let cluster = state.cluster.lock().unwrap();
        (
            cluster.enabled,
            cluster.local_node_id.clone(),
            cluster
                .nodes
                .iter()
                .filter(|node| node.node_id != cluster.local_node_id && node.status == "online")
                .map(|node| node.rpc_url.clone())
                .collect::<Vec<_>>(),
        )
    };

    if !enabled || targets.is_empty() {
        return Ok(());
    }

    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(2))
        .build()?;
    let auth_token = std::env::var("SKEINDB_TOKEN").ok();
    let payload = serde_json::json!({
        "skeinql": SKEINQL_VERSION,
        "method": "cluster.node.leave",
        "params": {
            "node_id": local_node_id,
        },
    });

    for rpc_url in targets {
        let url = format!("{}/api/v1/rpc", rpc_url.trim_end_matches('/'));
        let mut req = client
            .post(&url)
            .header(header::CONTENT_TYPE.as_str(), "application/json")
            .header(REPLICATION_HEADER, "1")
            .json(&payload);
        if let Some(token) = auth_token.as_ref() {
            req = req.bearer_auth(token);
        }
        match req.send().await {
            Ok(resp) if resp.status().is_success() => {}
            Ok(resp) => {
                tracing::warn!(peer = %url, status = %resp.status(), "cluster leave notify failed");
            }
            Err(err) => {
                tracing::warn!(peer = %url, error = %err, "cluster leave transport error");
            }
        }
    }

    Ok(())
}

