    #[tokio::test]
    async fn objects_missing_and_fetch_roundtrip() -> anyhow::Result<()> {
        let dir = temp_dir("objects_fetch");
        let engine = Engine::open(&dir)?;
        let state = build_state(dir.clone(), engine);

        // Compute the value id for "hello".
        let hello_id = skeindb_core::value_id(b"hello");
        let hello_hex = hello_id
            .iter()
            .map(|b| format!("{:02x}", b))
            .collect::<String>();

        // Before inserting, the value should be missing.
        let resp = call_rpc(&state, "objects.missing", json!({"ids": [hello_hex]})).await;
        assert!(resp.ok);
        let missing = resp.result.unwrap()["missing"].as_array().unwrap().clone();
        assert_eq!(missing.len(), 1);

        // Store the value via the engine's value store.
        {
            let eng = state.engine.write().await;
            let mut vs = eng.value_store_lock();
            vs.put(skeindb_core::ValueKind::Cell, b"hello".to_vec());
        }

        // Now it should not be missing.
        let resp = call_rpc(&state, "objects.missing", json!({"ids": [hello_hex]})).await;
        assert!(resp.ok);
        let missing = resp.result.unwrap()["missing"].as_array().unwrap().clone();
        assert_eq!(missing.len(), 0);

        // Fetch should return the bytes.
        let resp = call_rpc(&state, "objects.fetch", json!({"ids": [hello_hex]})).await;
        assert!(resp.ok);
        let objects = resp.result.unwrap()["objects"].as_array().unwrap().clone();
        assert_eq!(objects.len(), 1);
        assert_eq!(objects[0]["id"].as_str().unwrap(), hello_hex);
        assert!(objects[0]["verified"].as_bool().unwrap());
        assert_eq!(objects[0]["kind"].as_str().unwrap(), "Cell");
        assert!(objects[0]["entry_b64"].as_str().is_some());

        // Decode the base64 bytes and verify content.
        use base64::Engine as _;
        let b64 = objects[0]["bytes_b64"].as_str().unwrap();
        let bytes = base64::engine::general_purpose::STANDARD
            .decode(b64)
            .unwrap();
        assert_eq!(bytes, b"hello");

        std::fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[tokio::test]
    async fn objects_pull_batches_missing_ids_and_skips_local_hits() -> anyhow::Result<()> {
        let local_dir = temp_dir("objects_pull_local");
        let remote_dir = temp_dir("objects_pull_remote");
        let local_state = build_state(local_dir.clone(), Engine::open(&local_dir)?);
        let remote_state = build_state(remote_dir.clone(), Engine::open(&remote_dir)?);

        let local_hit = {
            let eng = local_state.engine.write().await;
            let mut vs = eng.value_store_lock();
            vs.put(skeindb_core::ValueKind::Cell, b"local-hit".to_vec())
        };
        let remote_ids = {
            let eng = remote_state.engine.write().await;
            let mut vs = eng.value_store_lock();
            vec![
                vs.put(skeindb_core::ValueKind::Cell, b"remote-a".to_vec()),
                vs.put(skeindb_core::ValueKind::Cell, b"remote-b".to_vec()),
                vs.put(skeindb_core::ValueKind::Cell, b"remote-c".to_vec()),
            ]
        };
        let local_hit_hex = value_id_to_hex(&local_hit);
        let remote_hex: Vec<String> = remote_ids.iter().map(value_id_to_hex).collect();

        let seen_fetch_batches = Arc::new(Mutex::new(Vec::<Vec<String>>::new()));
        let (remote_url, remote_handle) =
            spawn_rpc_test_server(remote_state.clone(), seen_fetch_batches.clone()).await?;

        let resp = call_rpc(
            &local_state,
            "objects.pull",
            json!({
                "source_rpc_url": remote_url,
                "ids": [local_hit_hex, remote_hex[0], remote_hex[1], remote_hex[2]],
                "batch_size": 2
            }),
        )
        .await;

        remote_handle.abort();
        assert!(resp.ok, "{resp:?}");
        let result = resp.result.unwrap();
        assert_eq!(result["requested"].as_u64().unwrap(), 4);
        assert_eq!(result["batch_size"].as_u64().unwrap(), 2);
        assert_eq!(result["batches"].as_u64().unwrap(), 2);
        assert_eq!(result["already_present"].as_u64().unwrap(), 1);
        assert_eq!(result["fetched_objects"].as_u64().unwrap(), 3);
        assert_eq!(result["stored"].as_u64().unwrap(), 3);
        assert_eq!(result["invalid_ids"].as_array().unwrap().len(), 0);
        assert_eq!(result["remote_missing"].as_array().unwrap().len(), 0);
        assert_eq!(result["verification_failed"].as_array().unwrap().len(), 0);
        assert_eq!(
            seen_fetch_batches.lock().unwrap().clone(),
            vec![
                vec![remote_hex[0].clone(), remote_hex[1].clone()],
                vec![remote_hex[2].clone()],
            ]
        );

        {
            let eng = local_state.engine.read().await;
            let vs = eng.value_store_lock();
            for id in &remote_ids {
                assert!(vs.contains(*id));
            }
        }

        std::fs::remove_dir_all(&local_dir).ok();
        std::fs::remove_dir_all(&remote_dir).ok();
        Ok(())
    }

    #[tokio::test]
    async fn objects_pull_fetches_missing_delta_base_dependency() -> anyhow::Result<()> {
        let local_dir = temp_dir("objects_pull_delta_local");
        let remote_dir = temp_dir("objects_pull_delta_remote");
        let local_state = build_state(local_dir.clone(), Engine::open(&local_dir)?);
        let remote_state = build_state(remote_dir.clone(), Engine::open(&remote_dir)?);

        let (base_id, delta_id, delta_bytes) = {
            let eng = remote_state.engine.write().await;
            let mut vs = eng.value_store_lock();
            vs.set_delta_policy(skeindb_core::valuestore::DeltaPolicy {
                enabled: true,
                min_bytes: 1,
                max_chain: 8,
                min_savings_ratio: 1.0,
                snapshot_interval: 0,
                max_skip: 0,
            });
            let base_bytes = b"hello from the remote base value".to_vec();
            let delta_bytes = b"hello from the remote delta value".to_vec();
            let base_id = vs.put(skeindb_core::ValueKind::Cell, base_bytes);
            let delta_id = vs.put_with_delta(
                skeindb_core::ValueKind::Cell,
                delta_bytes.clone(),
                Some(base_id),
            );
            assert_eq!(
                vs.get(&delta_id).expect("delta entry exists").kind,
                skeindb_core::ValueKind::Delta
            );
            (base_id, delta_id, delta_bytes)
        };
        let delta_hex = value_id_to_hex(&delta_id);
        let base_hex = value_id_to_hex(&base_id);

        let seen_fetch_batches = Arc::new(Mutex::new(Vec::<Vec<String>>::new()));
        let (remote_url, remote_handle) =
            spawn_rpc_test_server(remote_state.clone(), seen_fetch_batches.clone()).await?;

        let resp = call_rpc(
            &local_state,
            "objects.pull",
            json!({
                "source_rpc_url": remote_url,
                "ids": [delta_hex],
                "batch_size": 1
            }),
        )
        .await;

        remote_handle.abort();
        assert!(resp.ok, "{resp:?}");
        let result = resp.result.unwrap();
        assert_eq!(result["batches"].as_u64().unwrap(), 2);
        assert_eq!(result["stored"].as_u64().unwrap(), 2);
        assert_eq!(result["verification_failed"].as_array().unwrap().len(), 0);
        assert_eq!(
            seen_fetch_batches.lock().unwrap().clone(),
            vec![vec![value_id_to_hex(&delta_id)], vec![base_hex]]
        );

        {
            let eng = local_state.engine.read().await;
            let mut vs = eng.value_store_lock();
            assert!(vs.contains(base_id));
            assert!(vs.contains(delta_id));
            assert_eq!(vs.materialize(&delta_id)?, delta_bytes);
        }

        std::fs::remove_dir_all(&local_dir).ok();
        std::fs::remove_dir_all(&remote_dir).ok();
        Ok(())
    }

    #[tokio::test]
    async fn objects_pull_rejects_hash_mismatch() -> anyhow::Result<()> {
        use base64::Engine as _;

        let dir = temp_dir("objects_pull_hash_mismatch");
        let engine = Engine::open(&dir)?;
        let state = build_state(dir.clone(), engine);

        let bad_bytes = b"tampered".to_vec();
        let good_id = skeindb_core::value_id(&bad_bytes);
        let mut bad_id = good_id;
        bad_id[0] ^= 0x55;
        let bad_hex = value_id_to_hex(&bad_id);
        let payload = skeindb_core::valuestore::encode_transfer_entry(
            bad_id,
            &skeindb_core::valuestore::ValueEntry {
                kind: skeindb_core::ValueKind::Cell,
                bytes: bad_bytes.clone(),
                delta: None,
            },
        )?;
        let payload_b64 = base64::engine::general_purpose::STANDARD.encode(payload);
        let bytes_b64 = base64::engine::general_purpose::STANDARD.encode(&bad_bytes);

        let app = Router::new().route(
            "/api/v1/rpc",
            post(
                move |_headers: HeaderMap, Json(_req): Json<RpcRequest>| async move {
                    Json(serde_json::json!({
                        "skeinql": SKEINQL_VERSION,
                        "ok": true,
                        "result": {
                            "ok": true,
                            "objects": [{
                                "id": bad_hex,
                                "bytes_b64": bytes_b64,
                                "entry_b64": payload_b64,
                                "kind": "Cell",
                                "verified": false
                            }]
                        }
                    }))
                },
            ),
        );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await?;
        let addr = listener.local_addr()?;
        let remote = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });

        let resp = call_rpc(
            &state,
            "objects.pull",
            json!({
                "source_rpc_url": format!("http://{}", addr),
                "ids": [value_id_to_hex(&bad_id)],
                "batch_size": 1
            }),
        )
        .await;

        remote.abort();
        assert!(resp.ok);
        let result = resp.result.unwrap();
        assert_eq!(result["stored"].as_u64().unwrap(), 0);
        let failures = result["verification_failed"].as_array().unwrap();
        let expected_bad_hex = value_id_to_hex(&bad_id);
        assert_eq!(failures.len(), 1);
        assert_eq!(failures[0].as_str(), Some(expected_bad_hex.as_str()));

        {
            let eng = state.engine.read().await;
            let vs = eng.value_store_lock();
            assert!(!vs.contains(bad_id));
        }

        std::fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    // -----------------------------------------------------------------------
    // T167: CAS replication bandwidth metrics tests
    // -----------------------------------------------------------------------

    #[tokio::test]
    async fn cluster_replication_stats_tracks_hits_misses_and_bytes() -> anyhow::Result<()> {
        let dir = temp_dir("replication_stats");
        let engine = Engine::open(&dir)?;
        let state = build_state(dir.clone(), engine);

        // Seed a known object so hit/miss accounting is deterministic.
        {
            let eng = state.engine.write().await;
            let mut vs = eng.value_store_lock();
            vs.put(skeindb_core::ValueKind::Cell, b"payload-xyz".to_vec());
        }
        let hit_id = skeindb_core::value_id(b"payload-xyz");
        let hit_hex: String = hit_id.iter().map(|b| format!("{:02x}", b)).collect();
        let miss_hex = "00000000000000000000000000000001".to_string();

        // Baseline snapshot: all counters should be zero.
        let resp = call_rpc(&state, "cluster.replication_stats", json!({})).await;
        assert!(resp.ok);
        let base = resp.result.unwrap();
        assert_eq!(base["need_calls"].as_u64().unwrap(), 0);
        assert_eq!(base["fetch_calls"].as_u64().unwrap(), 0);
        assert_eq!(base["ref_bytes"].as_u64().unwrap(), 0);

        // `objects.need` with one hit + one miss → hit/miss counters advance,
        // and `ref_bytes` records bytes that did NOT need to be re-shipped.
        let resp = call_rpc(
            &state,
            "objects.need",
            json!({ "ids": [hit_hex.clone(), miss_hex.clone()] }),
        )
        .await;
        assert!(resp.ok);

        // `objects.missing` should also advance missing_* counters.
        let resp = call_rpc(
            &state,
            "objects.missing",
            json!({ "ids": [hit_hex.clone(), miss_hex.clone()] }),
        )
        .await;
        assert!(resp.ok);

        // `objects.fetch` on the hit id should record obj_bytes.
        let resp = call_rpc(&state, "objects.fetch", json!({ "ids": [hit_hex.clone()] })).await;
        assert!(resp.ok);

        let resp = call_rpc(&state, "cluster.replication_stats", json!({})).await;
        assert!(resp.ok);
        let s = resp.result.unwrap();
        assert_eq!(s["need_calls"].as_u64().unwrap(), 1);
        assert_eq!(s["need_ids_total"].as_u64().unwrap(), 2);
        assert_eq!(s["need_hits"].as_u64().unwrap(), 1);
        assert_eq!(s["need_misses"].as_u64().unwrap(), 1);
        assert_eq!(s["missing_calls"].as_u64().unwrap(), 1);
        assert_eq!(s["missing_hits"].as_u64().unwrap(), 1);
        assert_eq!(s["missing_misses"].as_u64().unwrap(), 1);
        assert_eq!(s["fetch_calls"].as_u64().unwrap(), 1);
        assert_eq!(s["fetch_objects_served"].as_u64().unwrap(), 1);
        assert_eq!(
            s["ref_bytes"].as_u64().unwrap(),
            b"payload-xyz".len() as u64
        );
        assert_eq!(
            s["obj_bytes"].as_u64().unwrap(),
            b"payload-xyz".len() as u64
        );
        let hit_rate = s["hit_rate"].as_f64().unwrap();
        assert!((hit_rate - 0.5).abs() < 1e-9, "hit_rate={}", hit_rate);
        let saved_ratio = s["saved_bytes_ratio"].as_f64().unwrap();
        assert!(
            (saved_ratio - 0.5).abs() < 1e-9,
            "saved_bytes_ratio={}",
            saved_ratio
        );

        // The same counters must also appear in `stats.snapshot` under
        // `cluster.replication_objects`.
        let resp = call_rpc(&state, "stats.snapshot", json!({})).await;
        assert!(resp.ok);
        let snap = resp.result.unwrap();
        let emb = &snap["cluster"]["replication_objects"];
        assert_eq!(emb["need_hits"].as_u64().unwrap(), 1);
        assert_eq!(
            emb["ref_bytes"].as_u64().unwrap(),
            b"payload-xyz".len() as u64
        );

        std::fs::remove_dir_all(&dir).ok();
        Ok(())
    }

